def _birth_place_label(place, latitude=None, longitude=None):
    place_text = str(place or "").strip()
    if place_text.casefold() not in {"", "none", "null", "undefined", "nan"}:
        return place_text

    try:
        lat = float(latitude)
        lon = float(longitude)
    except (TypeError, ValueError):
        return "Belirtilmedi"

    for label, known_lat, known_lon in KNOWN_BIRTH_PLACE_COORDINATES:
        if abs(lat - known_lat) <= 0.001 and abs(lon - known_lon) <= 0.001:
            return label
    return "Belirtilmedi"


@app.before_request
def _require_local_access():
    content_length = request.content_length
    max_content_length = app.config.get("MAX_CONTENT_LENGTH")
    if (
        content_length is not None
        and max_content_length is not None
        and content_length > max_content_length
    ):
        return jsonify({
            "ok": False,
            "error": "İstek güvenli boyut sınırını aşıyor.",
        }), 413

    if request.path == "/healthz":
        return None

    if app.config["LOCAL_ACCESS_ONLY"]:
        remote_addr = request.remote_addr
        try:
            is_local = bool(remote_addr) and ip_address(remote_addr).is_loopback
        except ValueError:
            is_local = False

        if not is_local:
            return jsonify({
                "ok": False,
                "error": "Bu API yalnızca yerel cihazdan kullanılabilir.",
            }), 403
        return None

    expected_token = (
        app.config.get("ACCOUNT_DELETE_TOKEN", "")
        if request.path == "/api/v2/account/delete-data"
        else app.config.get("API_TOKEN", "")
    )
    if not expected_token:
        return jsonify({
            "ok": False,
            "error": "Sunucu erişim anahtarı yapılandırılmamış.",
        }), 503

    authorization = request.headers.get("Authorization", "")
    scheme, separator, supplied_token = authorization.partition(" ")
    authorized = (
        separator == " "
        and scheme.casefold() == "bearer"
        and bool(supplied_token)
        and hmac.compare_digest(supplied_token, expected_token)
    )
    if not authorized:
        response = jsonify({
            "ok": False,
            "error": "Geçerli servis erişim anahtarı gerekli.",
        })
        response.headers["WWW-Authenticate"] = "Bearer"
        return response, 401
    return None


@app.after_request
def _add_security_headers(response):
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "no-referrer"
    response.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
    response.headers["Cross-Origin-Resource-Policy"] = "same-origin"
    if request.path.startswith(("/api/", "/vedic/")):
        response.headers["Cache-Control"] = "no-store"
    return response


@app.errorhandler(413)
def _request_too_large(_error):
    return jsonify({
        "ok": False,
        "error": "İstek güvenli boyut sınırını aşıyor.",
    }), 413


@app.route("/healthz", methods=["GET"])
def healthz():
    catalog_path = Path(app.config["PLACES_DB_PATH"])
    catalog_ready = False
    place_count = 0
    if catalog_path.is_file():
        try:
            uri = f"file:{catalog_path.resolve()}?mode=ro"
            with closing(sqlite3.connect(uri, uri=True)) as conn:
                place_count = int(
                    conn.execute(
                        "SELECT value FROM catalog_metadata WHERE key = 'place_count'"
                    ).fetchone()[0]
                )
            catalog_ready = place_count > 0
        except (sqlite3.Error, TypeError, ValueError, IndexError):
            catalog_ready = False
    running_on_railway = bool(os.environ.get("RAILWAY_ENVIRONMENT_ID"))
    artifact_storage_persistent = bool(RAILWAY_VOLUME_ROOT)
    storage_ready = not running_on_railway or artifact_storage_persistent
    service_ready = catalog_ready and storage_ready
    status_code = 200 if service_ready else 503
    return jsonify({
        "ok": service_ready,
        "service": "vedic-chart-api",
        "status": "ready" if service_ready else "not_ready",
        "catalog_ready": catalog_ready,
        "place_count": place_count,
        "artifact_storage_ready": storage_ready,
        "artifact_storage_persistent": artifact_storage_persistent,
    }), status_code


