def _require_int(data, key):
    return int(data[key])


def _optional_second(data):
    return int(data.get("second") or 0)


def _require_float(data, key):
    return float(data[key])


def _coordinate_direction(data, keys):
    for key in keys:
        value = data.get(key)
        if value not in {None, ""}:
            return str(value).strip().upper()
    return None


def _require_coordinate(data, value_key, direction_keys, positive_direction, negative_direction, label):
    raw_value = data[value_key]
    text_value = str(raw_value).strip()
    suffix_direction = None
    if text_value and text_value[-1:].upper() in {positive_direction, negative_direction}:
        suffix_direction = text_value[-1:].upper()
        text_value = text_value[:-1].strip()

    value = float(text_value)
    direction = _coordinate_direction(data, direction_keys) or suffix_direction
    if direction:
        if direction not in {positive_direction, negative_direction}:
            raise ValueError(
                f"Geçersiz {label} yönü: {direction}. Desteklenen: {positive_direction}/{negative_direction}"
            )
        value = abs(value) if direction == positive_direction else -abs(value)
    return value


def _require_latitude(data):
    return _require_coordinate(
        data,
        "lat",
        ["lat_direction", "latitude_direction", "lat_dir", "latitude_hemisphere"],
        "N",
        "S",
        "enlem",
    )


def _require_longitude(data):
    return _require_coordinate(
        data,
        "lon",
        ["lon_direction", "longitude_direction", "lon_dir", "lng_dir", "longitude_hemisphere"],
        "E",
        "W",
        "boylam",
    )


def _validate_birth_fields(year, month, day, hour, minute, lat, lon, second=0):
    if not (1 <= month <= 12):
        raise ValueError("Geçersiz ay değeri")
    if not (1 <= day <= 31):
        raise ValueError("Geçersiz gün değeri")
    if not (0 <= hour <= 23):
        raise ValueError("Geçersiz saat değeri")
    if not (0 <= minute <= 59):
        raise ValueError("Geçersiz dakika değeri")
    if not (0 <= second <= 59):
        raise ValueError("Geçersiz saniye değeri")
    if not (-90 <= lat <= 90):
        raise ValueError("Geçersiz enlem değeri")
    if not (-180 <= lon <= 180):
        raise ValueError("Geçersiz boylam değeri")


def _resolve_timezone_offset(birth, year, month, day, hour, minute, second=0):
    timezone_id = birth.get("timezone_id")
    if timezone_id:
        try:
            zone = ZoneInfo(timezone_id)
        except ZoneInfoNotFoundError as exc:
            raise ValueError(f"Geçersiz timezone_id: {timezone_id}") from exc

        local_dt = datetime(year, month, day, hour, minute, second, tzinfo=zone)
        utc_offset = local_dt.utcoffset()
        if utc_offset is None:
            raise ValueError(f"timezone_id için UTC farkı çözülemedi: {timezone_id}")

        return utc_offset.total_seconds() / 3600.0, timezone_id

    if "tz_offset" not in birth:
        raise KeyError("birth.tz_offset veya birth.timezone_id")

    return float(birth["tz_offset"]), None


def _validate_v2_options(options):
    for key, supported_values in SUPPORTED_V2_OPTIONS.items():
        value = options.get(key)
        if value is not None and value not in supported_values:
            supported = ", ".join(sorted(supported_values))
            raise ValueError(f"Desteklenmeyen options.{key}: {value}. Desteklenen: {supported}")


def _datetime_to_julian_day_utc(dt_utc):
    return swe.julday(
        dt_utc.year,
        dt_utc.month,
        dt_utc.day,
        dt_utc.hour + dt_utc.minute / 60.0 + dt_utc.second / 3600.0,
    )


def _transit_reference_from_options(options, default_tz_offset):
    transit_date = str(options.get("transit_date") or "").strip()
    transit_time = str(options.get("transit_time") or "").strip()
    transit_timezone_id = str(options.get("transit_timezone_id") or "").strip()
    if not transit_date:
        now_utc = datetime.now(timezone.utc)
        return {
            "mode": "current",
            "datetime_utc": now_utc,
            "requested_date": None,
            "requested_time": None,
            "tz_offset": 0.0,
            "time_source": "request_time_utc",
        }

    if not transit_time:
        transit_time = "12:00"

    try:
        year_text, month_text, day_text = transit_date.split("-")
        hour_text, minute_text = transit_time.split(":")
        year = int(year_text)
        month = int(month_text)
        day = int(day_text)
        hour = int(hour_text)
        minute = int(minute_text)
        _validate_birth_fields(year, month, day, hour, minute, 0, 0)
    except (AttributeError, TypeError, ValueError) as exc:
        raise ValueError("Geçersiz transit tarihi/saat formatı. Beklenen: YYYY-MM-DD ve HH:MM") from exc

    if transit_timezone_id:
        try:
            zone = ZoneInfo(transit_timezone_id)
        except ZoneInfoNotFoundError as exc:
            raise ValueError(f"Geçersiz transit_timezone_id: {transit_timezone_id}") from exc
        local_dt = datetime(year, month, day, hour, minute, tzinfo=zone)
        utc_offset = local_dt.utcoffset()
        if utc_offset is None:
            raise ValueError(f"transit_timezone_id için UTC farkı çözülemedi: {transit_timezone_id}")
        tz_offset = utc_offset.total_seconds() / 3600.0
        utc_dt = local_dt.astimezone(timezone.utc)
        time_source = "options.transit_date_time_and_timezone_id"
    else:
        tz_offset = float(options.get("transit_tz_offset", default_tz_offset))
        local_dt = datetime(year, month, day, hour, minute)
        utc_dt = (local_dt - timedelta(hours=tz_offset)).replace(tzinfo=timezone.utc)
        time_source = "options.transit_date_and_transit_time"

    return {
        "mode": "user_selected",
        "datetime_utc": utc_dt,
        "requested_date": transit_date,
        "requested_time": transit_time,
        "tz_offset": tz_offset,
        "timezone_id": transit_timezone_id or None,
        "time_source": time_source,
    }


def _split_planet_name(name):
    if " / " not in name:
        return name, name
    name_en, name_tr = name.split(" / ", 1)
    return name_en, name_tr


def _planet_name_en(planet):
    return _split_planet_name(planet["name"])[0].replace(" (True)", "")


def _sign_tr(sign):
    if " (" in sign:
        return sign.split(" (", 1)[0]
    return sign


def _is_moolatrikona(name_en, sign_index, degree):
    moolatrikona = MOOLATRIKONA_RANGES.get(name_en)
    if not moolatrikona or sign_index != moolatrikona["sign"]:
        return False

    return moolatrikona["start"] <= degree < moolatrikona["end"]


def _natural_friendship(name_en, sign_lord):
    if sign_lord == name_en:
        return "own"

    relationships = NATURAL_FRIENDSHIPS.get(name_en)
    if not relationships or sign_lord is None:
        return "unknown"

    if sign_lord in relationships["friends"]:
        return "friend"
    if sign_lord in relationships["enemies"]:
        return "enemy"
    if sign_lord in relationships["neutrals"]:
        return "neutral"

    return "unknown"


def _natural_relationship_between(from_planet, to_planet):
    if from_planet == to_planet:
        return "self"

    relationships = NATURAL_FRIENDSHIPS.get(from_planet)
    if not relationships:
        return "unknown"

    if to_planet in relationships["friends"]:
        return "friend"
    if to_planet in relationships["enemies"]:
        return "enemy"
    if to_planet in relationships["neutrals"]:
        return "neutral"

    return "unknown"


def _dignity_for_planet(planet):
    name_en = _planet_name_en(planet)
    sign_index = planet["sign_index"]
    degree = planet["degree"]
    sign_lord = SIGN_LORDS.get(sign_index)
    is_swakshetra = sign_lord == name_en
    is_uccha = EXALTATION_SIGNS.get(name_en) == sign_index
    is_neecha = DEBILITATION_SIGNS.get(name_en) == sign_index
    is_moolatrikona = _is_moolatrikona(name_en, sign_index, degree)
    natural_friendship = _natural_friendship(name_en, sign_lord)

    if is_uccha:
        essential = "exalted"
    elif is_neecha:
        essential = "debilitated"
    elif is_moolatrikona:
        essential = "moolatrikona"
    elif is_swakshetra:
        essential = "own_sign"
    elif natural_friendship == "friend":
        essential = "friendly"
    elif natural_friendship == "enemy":
        essential = "enemy"
    else:
        essential = "neutral"

    return {
        "essential": essential,
        "uccha": is_uccha,
        "neecha": is_neecha,
        "swakshetra": is_swakshetra,
        "moolatrikona": is_moolatrikona,
        "natural_friendship": natural_friendship,
        "temporary_friendship": "unknown",
        "compound_friendship": "unknown",
    }


def _angular_distance(longitude_a, longitude_b):
    distance = abs((longitude_a - longitude_b) % 360.0)
    return min(distance, 360.0 - distance)


def _combustion_severity(distance, threshold):
    if distance >= threshold:
        return "none"
    if distance <= threshold / 3.0:
        return "severe"
    if distance <= (threshold * 2.0) / 3.0:
        return "moderate"
    return "mild"


def _combustion_for_planet(planet, sun_longitude):
    name_en = _planet_name_en(planet)
    if name_en == "Sun":
        return {
            "is_combust": False,
            "distance_from_sun": 0.0,
            "threshold": None,
            "severity": "not_calculated",
        }

    distance = _angular_distance(planet["longitude"], sun_longitude)
    if name_en == "Moon":
        return {
            "is_combust": False,
            "distance_from_sun": distance,
            "threshold": None,
            "severity": "none",
        }

    threshold = COMBUSTION_THRESHOLDS.get(name_en)
    if threshold is None:
        return {
            "is_combust": False,
            "distance_from_sun": distance,
            "threshold": None,
            "severity": "not_calculated",
        }

    severity = _combustion_severity(distance, threshold)
    return {
        "is_combust": severity != "none",
        "distance_from_sun": distance,
        "threshold": threshold,
        "severity": severity,
    }


def _default_war_for_planet(planet):
    if _planet_name_en(planet) not in TARA_GRAHAS:
        return {
            "in_graha_yuddha": False,
            "opponent": None,
            "status": "not_applicable",
            "orb": None,
        }

    return {
        "in_graha_yuddha": False,
        "opponent": None,
        "status": "none",
        "orb": None,
    }


def _build_war_map(planets):
    war_by_name = {
        _planet_name_en(planet): _default_war_for_planet(planet)
        for planet in planets
    }
    tara_planets = [
        planet
        for planet in planets
        if _planet_name_en(planet) in TARA_GRAHAS
    ]

    for index, planet in enumerate(tara_planets):
        planet_name = _planet_name_en(planet)
        for other in tara_planets[index + 1:]:
            other_name = _planet_name_en(other)
            orb = _angular_distance(planet["longitude"], other["longitude"])
            if orb > GRAHA_YUDDHA_ORB:
                continue

            for current_name, opponent_name in (
                (planet_name, other_name),
                (other_name, planet_name),
            ):
                current_war = war_by_name[current_name]
                if current_war["orb"] is None or orb < current_war["orb"]:
                    war_by_name[current_name] = {
                        "in_graha_yuddha": True,
                        "opponent": opponent_name,
                        "status": "in_war",
                        "orb": orb,
                    }

    return war_by_name


def _planet_index_by_name(chart):
    return {_planet_name_en(planet): planet for planet in chart["planets"]}


def _v2_lagna(source):
    return {
        "longitude": source.get("longitude"),
        "sign_index": source.get("sign_index"),
        "sign": source.get("sign_en"),
        "sign_tr": _sign_tr(source.get("sign", "")),
        "degree": source.get("degree"),
        "degree_str": source.get("degree_str"),
        "nakshatra": source.get("nakshatra"),
    }


def _varga_segment_index(degree_in_sign, division_number):
    segment_size = 30.0 / division_number
    segment_index = int(degree_in_sign / segment_size)
    if segment_index >= division_number:
        segment_index = division_number - 1
    return segment_index, segment_size


def _trimshamsha_position(degree_in_sign, is_odd_sign):
    if is_odd_sign:
        segments = [
            (0.0, 5.0, 0),
            (5.0, 10.0, 10),
            (10.0, 18.0, 8),
            (18.0, 25.0, 2),
            (25.0, 30.0, 6),
        ]
    else:
        segments = [
            (0.0, 5.0, 1),
            (5.0, 12.0, 5),
            (12.0, 20.0, 11),
            (20.0, 25.0, 9),
            (25.0, 30.0, 7),
        ]

    for start, end, sign_index in segments:
        if start <= degree_in_sign < end:
            degree = ((degree_in_sign - start) / (end - start)) * 30.0
            return sign_index, degree

    start, end, sign_index = segments[-1]
    degree = ((degree_in_sign - start) / (end - start)) * 30.0
    return sign_index, degree


def _varga_metadata(division):
    externally_verified = division in VARGA_EXTERNAL_VALIDATION_VERIFIED
    calculation_validation = {
        "status": "astroseek_verified" if externally_verified else "internal_formula",
        "sources": ["AstroSeek"] if externally_verified else [],
        "note": (
            "AstroSeek karşılaştırması ve iç formül örnek testleri tamamlandı."
            if externally_verified
            else "Mevcut iç formül seti."
        ),
    }
    return {
        "source_rule": VARGA_SOURCE_RULES.get(division, "standard_varga_rule"),
        "confidence": VARGA_INTERPRETATION_CONFIDENCE.get(division, "low"),
        "calculation_validation": calculation_validation.copy(),
        # Geriye dönük API uyumluluğu için korunur. Doğum saati güven politikası
        # bu eski alanı değiştirebilir; tablolar calculation_validation kullanır.
        "external_validation": calculation_validation.copy(),
    }


def _varga_calculation_validation(varga, division):
    validation = (varga or {}).get("calculation_validation")
    if validation:
        return validation
    if division in VARGA_EXTERNAL_VALIDATION_VERIFIED:
        return {
            "status": "astroseek_verified",
            "sources": ["AstroSeek"],
            "note": "AstroSeek karşılaştırması ve iç formül örnek testleri tamamlandı.",
        }
    return (varga or {}).get("external_validation") or {}


def _astroseek_verified_person_label(person):
    if not isinstance(person, dict):
        return None

    for key in ("id", "name"):
        value = str(person.get(key) or "").strip().casefold()
        if value in VARGA_ASTROSEEK_VERIFIED_PERSON_ALIASES:
            return VARGA_ASTROSEEK_VERIFIED_PERSON_ALIASES[value]

    return None


def _apply_person_varga_validation(vargas, person):
    label = _astroseek_verified_person_label(person)
    if not label:
        return []

    verified_divisions = [
        division
        for division in VARGA_NAMES
        if division in vargas
        and division in VARGA_ASTROSEEK_VERIFIED_DIVISIONS
    ]
    for division in verified_divisions:
        person_validation = {
            "status": "astroseek_verified",
            "sources": ["AstroSeek"],
            "note": (
                f"{label} için AstroSeek karşılaştırması kullanıcı tarafından "
                "doğrulandı; yorum güveni müşteri doğum saati beyanı politikasından gelir."
            ),
        }
        vargas[division]["calculation_validation"] = person_validation.copy()
        vargas[division]["external_validation"] = person_validation.copy()

    return verified_divisions


def _rectification_source_label(source):
    labels = {
        "external_astrolog": "Dış astrolog rektifikasyonu",
        "external_astrolog_or_user_confirmed": "Dış/onaylı rektifikasyon",
        "imported_rectified_chart": "İçe aktarılan rektifiye harita",
        "user_confirmed_external_rectification": "Kullanıcı onaylı dış rektifikasyon",
        "api_v1_decision_gate": "API v1 rektifikasyon karar kapısı",
        "unspecified_rectified_time": "Kaynağı belirtilmemiş rektifiye saat",
    }
    return labels.get(str(source or "").strip(), "Rektifikasyonlu saat")


def _rectification_source_from_label(value):
    text = str(value or "").strip()
    if text in EXTERNAL_RECTIFICATION_SOURCES or text in {
        "api_v1_decision_gate",
        "unspecified_rectified_time",
    }:
        return text
    labels = {
        _rectification_source_label(source): source
        for source in [
            *sorted(EXTERNAL_RECTIFICATION_SOURCES),
            "api_v1_decision_gate",
            "unspecified_rectified_time",
        ]
    }
    return labels.get(text)


def _apply_rectified_varga_confidence(vargas, birth_time_quality):
    if birth_time_quality.get("rectification_status") != "yapıldı":
        return []

    rectification_source = birth_time_quality.get("rectification_source")
    source_label = _rectification_source_label(rectification_source)
    rectified_divisions = [
        division
        for division in VARGA_NAMES
        if division in vargas
        and division in VARGA_RECTIFIED_HIGH_DIVISIONS
    ]
    for division in rectified_divisions:
        confidence = "high"
        vargas[division]["confidence"] = confidence
        vargas[division]["external_validation"] = {
            "status": "rectified_time_supported",
            "sources": [rectification_source or "birth_time_rectification"],
            "note": (
                f"{source_label} nedeniyle varga yorum güveni "
                f"{confidence} seviyesine yükseltildi."
            ),
        }

    return rectified_divisions


def _apply_birth_time_varga_confidence(vargas, birth_time_quality):
    declaration = birth_time_quality.get("declaration") or "approximate"
    confidence_policy = BIRTH_TIME_VARGA_CONFIDENCE.get(
        declaration,
        BIRTH_TIME_VARGA_CONFIDENCE["approximate"],
    )
    affected_divisions = []
    for division, confidence in confidence_policy.items():
        if division not in vargas:
            continue
        vargas[division]["confidence"] = confidence
        vargas[division]["external_validation"] = {
            "status": "customer_time_declaration_policy",
            "sources": ["customer_declaration"],
            "note": (
                f"{birth_time_quality.get('confidence_label', declaration)} müşteri "
                f"beyanı nedeniyle {division} yorum güveni {confidence} kabul edildi."
            ),
        }
        affected_divisions.append(division)
    return affected_divisions


def _chart_is_rectified(chart):
    birth = chart.get("birth") or {}
    time_confidence = str(birth.get("time_confidence") or "").strip().lower()
    return birth.get("rectification_status") == "yapıldı" or time_confidence == "rectified"


def _birth_time_confidence_display_label(birth):
    if not isinstance(birth, dict):
        return ""
    if birth.get("rectification_status") == "yapıldı" or birth.get("time_confidence") == "rectified":
        return "rektifiye"
    return birth.get("time_confidence_label") or birth.get("time_confidence") or ""


def _apply_rectified_varga_confidence_to_chart(chart):
    if not _chart_is_rectified(chart):
        return []

    vargas = chart.get("vargas") or {}
    birth = chart.get("birth") or {}
    rectification_source = (
        birth.get("rectification_source")
        or (chart.get("data_quality") or {}).get("rectification_source")
        or "api_v1_decision_gate"
    )
    rectified_vargas = _apply_rectified_varga_confidence(
        vargas,
        {
            "rectification_status": "yapıldı",
            "rectification_source": rectification_source,
        },
    )
    if not rectified_vargas:
        return []

    data_quality = chart.setdefault("data_quality", {})
    varga_confidence = data_quality.setdefault(
        "varga_interpretation_confidence",
        VARGA_INTERPRETATION_CONFIDENCE.copy(),
    )
    for division in rectified_vargas:
        varga_confidence[division] = vargas[division]["confidence"]

    data_quality["rectified_time_supported_vargas"] = rectified_vargas
    data_quality["rectification_source"] = rectification_source
    data_quality["rectification_source_label"] = _rectification_source_label(rectification_source)
    notes = data_quality.setdefault("notes", [])
    note = (
        f"{_rectification_source_label(rectification_source)} desteğiyle tüm "
        "vargalar high yorum güveni kayıtlı."
    )
    if note not in notes:
        notes.append(note)

    rectification = chart.setdefault("rectification", {})
    low_confidence = [
        division
        for division in rectification.get("low_confidence_interpretations", [])
        if division not in rectified_vargas
    ]
    rectification["low_confidence_interpretations"] = low_confidence

    return rectified_vargas


def _varga_position_from_longitude(longitude, division):
    longitude = longitude % 360.0
    rashi_sign_index = int(longitude / 30.0)
    degree_in_sign = longitude % 30.0
    is_odd_sign = rashi_sign_index % 2 == 0

    if division == "D1":
        sign_index = rashi_sign_index
        degree = degree_in_sign
    elif division == "D2":
        segment_index = 0 if degree_in_sign < 15.0 else 1
        if rashi_sign_index % 2 == 0:
            sign_index = 4 if segment_index == 0 else 3
        else:
            sign_index = 3 if segment_index == 0 else 4
        degree = (degree_in_sign - segment_index * 15.0) * 2.0
    elif division == "D3":
        segment_size = 10.0
        segment_index = int(degree_in_sign / segment_size)
        if segment_index >= 3:
            segment_index = 2
        sign_index = (rashi_sign_index + segment_index * 4) % 12
        degree = (degree_in_sign - segment_index * segment_size) * 3.0
    elif division == "D60":
        segment_size = 0.5
        segment_index = int(degree_in_sign / segment_size)
        if segment_index >= 60:
            segment_index = 59
        if rashi_sign_index % 2 == 0:
            sign_index = (rashi_sign_index + segment_index) % 12
        else:
            sign_index = (rashi_sign_index - segment_index) % 12
        degree = (degree_in_sign - segment_index * segment_size) * 60.0
    elif division == "D30":
        sign_index, degree = _trimshamsha_position(degree_in_sign, is_odd_sign)
    else:
        division_number = int(division[1:])
        segment_index, segment_size = _varga_segment_index(degree_in_sign, division_number)

        if division == "D4":
            start_sign = rashi_sign_index + segment_index * 3
            sign_index = start_sign % 12
            degree = (degree_in_sign - (segment_index * segment_size)) * division_number
        elif division == "D6":
            start_sign = 0 if is_odd_sign else 6
        elif division == "D7":
            start_sign = rashi_sign_index if is_odd_sign else (rashi_sign_index + 6)
        elif division == "D9":
            element = rashi_sign_index % 4
            start_sign = {0: 0, 1: 9, 2: 6, 3: 3}[element]
        elif division == "D10":
            start_sign = rashi_sign_index if is_odd_sign else (rashi_sign_index + 8)
        elif division == "D11":
            start_sign = (-rashi_sign_index) % 12
        elif division == "D12":
            start_sign = rashi_sign_index
        elif division == "D16":
            # Shodasamsha (Kalamsha): 16 equal divisions of 1°52'30".
            # Movable signs begin from Aries, fixed signs from Leo and dual
            # signs from Sagittarius; the segment is counted forward.
            modality = rashi_sign_index % 3
            start_sign = {0: 0, 1: 4, 2: 8}[modality]
        elif division == "D20":
            modality = rashi_sign_index % 3
            start_sign = {0: 0, 1: 8, 2: 4}[modality]
        elif division == "D24":
            start_sign = 4 if is_odd_sign else 3
        else:
            raise ValueError(f"Desteklenmeyen varga bölümü: {division}")

        if division != "D4":
            sign_index = (start_sign + segment_index) % 12
            degree = (degree_in_sign - (segment_index * segment_size)) * division_number

    return {
        "sign_index": sign_index,
        "sign": SIGNS_EN[sign_index],
        "sign_tr": _sign_tr(SIGNS_TR[sign_index]),
        "degree": degree,
        "degree_str": dms_str(degree),
    }


def _varga_lagna(chart, division):
    if division == "D1":
        return _v2_lagna(chart["lagna"])

    position = _varga_position_from_longitude(chart["lagna"]["longitude"], division)
    return {
        "sign_index": position["sign_index"],
        "sign": position["sign"],
        "sign_tr": position["sign_tr"],
        "degree": position["degree"],
        "degree_str": position["degree_str"],
    }


def _varga_status_for_planet(planet, lagna_vargottama):
    vargas = {
        division: _varga_position_from_longitude(planet["longitude"], division)
        for division in VARGA_NAMES
    }
    d1 = vargas["D1"]
    d9 = vargas["D9"]

    return {
        "vargottama": d1["sign_index"] == d9["sign_index"],
        "lagna_vargottama": lagna_vargottama,
        **vargas,
        "vargas": {
            division: position["sign"]
            for division, position in vargas.items()
        },
    }


def _v2_planet(planet, sun_longitude, war_by_name, lagna_vargottama):
    name_en, name_tr = _split_planet_name(planet["name"])
    sign = planet["sign_en"]

    return {
        "id": PLANET_IDS.get(planet["abbr"], name_en.lower().replace(" ", "_")),
        "name": name_en,
        "name_tr": name_tr,
        "abbr": planet["abbr"],
        "longitude": planet["longitude"],
        "sign_index": planet["sign_index"],
        "sign": sign,
        "sign_tr": _sign_tr(planet["sign"]),
        "degree": planet["degree"],
        "degree_str": planet["degree_str"],
        "house": planet["house"],
        "nakshatra": planet["nakshatra"],
        "motion": {
            "retrograde": planet["retrograde"],
            "speed": planet["speed"],
            "speed_status": "retrograde" if planet["retrograde"] else "normal",
        },
        "dignity": _dignity_for_planet(planet),
        "combustion": _combustion_for_planet(planet, sun_longitude),
        "war": war_by_name[_planet_name_en(planet)],
        "varga_status": _varga_status_for_planet(planet, lagna_vargottama),
    }


def _aspect_type(offset):
    if offset == 7:
        return "seventh"
    suffixes = {
        3: "3rd",
        4: "4th",
        5: "5th",
        8: "8th",
        9: "9th",
        10: "10th",
    }
    return f"special_{suffixes[offset]}"


def _build_graha_drishti(chart):
    planets_by_house = {house: [] for house in range(1, 13)}
    for planet in chart["planets"]:
        planets_by_house[planet["house"]].append(_planet_name_en(planet))

    aspects = []
    for planet in chart["planets"]:
        planet_name = _planet_name_en(planet)
        offsets = GRAHA_DRISHTI_OFFSETS.get(planet_name)
        if not offsets:
            continue

        for offset in offsets:
            target_house = ((planet["house"] + offset - 2) % 12) + 1
            target_sign_index = (planet["sign_index"] + offset - 1) % 12
            aspects.append({
                "from": planet_name,
                "from_id": PLANET_IDS.get(planet["abbr"]),
                "from_house": planet["house"],
                "from_sign": planet["sign_en"],
                "from_sign_index": planet["sign_index"],
                "to_house": target_house,
                "to_sign": SIGNS_EN[target_sign_index],
                "to_sign_index": target_sign_index,
                "to_planets": planets_by_house[target_house],
                "aspect_type": _aspect_type(offset),
                "orb": None,
                "strength": "full",
            })

    return aspects


def _rashi_type(sign_index):
    if sign_index in {0, 3, 6, 9}:
        return "movable"
    if sign_index in {1, 4, 7, 10}:
        return "fixed"
    return "dual"


def _rashi_drishti_target_signs(sign_index):
    sign_type = _rashi_type(sign_index)
    if sign_type == "movable":
        return [
            target for target in [1, 4, 7, 10]
            if target != (sign_index + 1) % 12
        ]
    if sign_type == "fixed":
        return [
            target for target in [0, 3, 6, 9]
            if target != (sign_index - 1) % 12
        ]
    return [
        target for target in [2, 5, 8, 11]
        if target != sign_index
    ]


def _build_rashi_drishti(chart):
    lagna_sign_index = chart["lagna"]["sign_index"]
    planets_by_sign = {sign_index: [] for sign_index in range(12)}
    for planet in chart["planets"]:
        planets_by_sign[planet["sign_index"]].append(_planet_name_en(planet))

    aspects = []
    for planet in chart["planets"]:
        planet_name = _planet_name_en(planet)
        from_sign_index = planet["sign_index"]
        for target_sign_index in _rashi_drishti_target_signs(from_sign_index):
            aspects.append({
                "from": planet_name,
                "from_id": PLANET_IDS.get(planet["abbr"]),
                "from_house": planet["house"],
                "from_sign": planet["sign_en"],
                "from_sign_index": from_sign_index,
                "from_rashi_type": _rashi_type(from_sign_index),
                "to_house": ((target_sign_index - lagna_sign_index) % 12) + 1,
                "to_sign": SIGNS_EN[target_sign_index],
                "to_sign_index": target_sign_index,
                "to_rashi_type": _rashi_type(target_sign_index),
                "to_planets": planets_by_sign[target_sign_index],
                "aspect_type": "jaimini_rashi_drishti",
                "strength": "sign",
            })

    return aspects


def _build_houses(chart, graha_drishti=None, rashi_drishti=None):
    lagna_sign_index = chart["lagna"]["sign_index"]
    planets_by_house = {house: [] for house in range(1, 13)}
    for planet in chart["planets"]:
        planets_by_house[planet["house"]].append(_planet_name_en(planet))
    aspected_by_house = {house: [] for house in range(1, 13)}
    for aspect in graha_drishti or []:
        aspected_by_house[aspect["to_house"]].append(aspect["from"])
    rashi_aspected_by_house = {house: [] for house in range(1, 13)}
    for aspect in rashi_drishti or []:
        rashi_aspected_by_house[aspect["to_house"]].append(aspect["from"])

    houses = []
    for house_number in range(1, 13):
        sign_index = (lagna_sign_index + house_number - 1) % 12
        occupants = planets_by_house[house_number]
        supporting_factors = []
        if occupants:
            supporting_factors.append("occupied")

        houses.append({
            "house": house_number,
            "sign_index": sign_index,
            "sign": SIGNS_EN[sign_index],
            "sign_tr": _sign_tr(SIGNS_TR[sign_index]),
            "lord": SIGN_LORDS[sign_index],
            "occupants": occupants,
            "aspected_by": aspected_by_house[house_number],
            "rashi_aspected_by": rashi_aspected_by_house[house_number],
            "karakas": HOUSE_KARAKAS.get(house_number, []),
            "strength_summary": {
                "status": "not_assessed",
                "supporting_factors": supporting_factors,
                "challenging_factors": [],
            },
        })

    return houses


def _bhava_chalit_cusp_row(house_number, cusp_longitude, previous_cusp, next_cusp):
    cusp_longitude = cusp_longitude % 360.0
    sign_index = int(cusp_longitude / 30.0)
    return {
        "house": house_number,
        "cusp_longitude": cusp_longitude,
        "cusp_sign": SIGNS_EN[sign_index],
        "cusp_sign_tr": _sign_tr(SIGNS_TR[sign_index]),
        "cusp_sign_index": sign_index,
        "cusp_degree": cusp_longitude % 30.0,
        "cusp_degree_str": dms_str(cusp_longitude % 30.0),
        "start_longitude": (previous_cusp + ((cusp_longitude - previous_cusp) % 360.0) / 2.0) % 360.0,
        "end_longitude": (cusp_longitude + ((next_cusp - cusp_longitude) % 360.0) / 2.0) % 360.0,
        "lord": SIGN_LORDS[sign_index],
    }


def _bhava_chalit_house_for_longitude(longitude, houses):
    for house in houses:
        if _longitude_in_arc(
            longitude % 360.0,
            house["start_longitude"],
            house["end_longitude"],
        ):
            return house["house"]
    return None


def _build_bhava_chalit(chart, birth_jd):
    flags = swe.FLG_SIDEREAL | swe.FLG_SPEED
    try:
        cusps, _ascmc = swe.houses_ex(
            birth_jd,
            chart["birth_info"]["latitude"],
            chart["birth_info"]["longitude_geo"],
            b"O",
            flags,
        )
        cusp_status = "implemented_sripati"
        confidence = "medium"
    except Exception as exc:
        return {
            "status": "not_available",
            "confidence": "none",
            "method": "sripati_house_cusps_with_chalit_planet_house_assignment",
            "reason": "sripati_cusps_unavailable",
            "error": str(exc),
            "assumptions": [
                "whole_sign_primary_house_system_unchanged",
                "sripati_intended_as_secondary_bhava_reference",
            ],
            "excluded_rules": [
                "interpretive_prediction_text",
                "automatic_replacement_of_whole_sign_houses",
                "generator_package_wide_usage",
                "ui_layout_change",
            ],
        }

    cusp_longitudes = [longitude % 360.0 for longitude in cusps[:12]]
    houses = []
    for index, cusp_longitude in enumerate(cusp_longitudes):
        houses.append(_bhava_chalit_cusp_row(
            index + 1,
            cusp_longitude,
            cusp_longitudes[index - 1],
            cusp_longitudes[(index + 1) % 12],
        ))

    planet_rows = []
    changed_planets = []
    for planet in chart["planets"]:
        bhava_house = _bhava_chalit_house_for_longitude(planet["longitude"], houses)
        whole_sign_house = planet["house"]
        house_changed = bhava_house is not None and bhava_house != whole_sign_house
        planet_name = _planet_name_en(planet)
        if house_changed:
            changed_planets.append(planet_name)
        cusp = next((house for house in houses if house["house"] == bhava_house), None)
        planet_rows.append({
            "planet": planet_name,
            "planet_id": PLANET_IDS.get(planet["abbr"]),
            "longitude": planet["longitude"],
            "sign": planet["sign_en"],
            "sign_tr": _sign_tr(planet["sign"]),
            "sign_index": planet["sign_index"],
            "degree": planet["degree"],
            "degree_str": planet["degree_str"],
            "whole_sign_house": whole_sign_house,
            "bhava_chalit_house": bhava_house,
            "house_changed": house_changed,
            "distance_from_cusp": (
                round(_angular_distance(planet["longitude"], cusp["cusp_longitude"]), 6)
                if cusp
                else None
            ),
        })

    return {
        "status": "implemented_passive_technical_layer",
        "confidence": confidence,
        "method": "sripati_house_cusps_with_chalit_planet_house_assignment",
        "source_rule": (
            "D1 planet longitudes are assigned to Sripati bhava cusp arcs as a "
            "secondary technical reference; the primary Whole Sign house system is unchanged."
        ),
        "assumptions": [
            "lahiri_ayanamsa",
            "birth_time_sensitive",
            "whole_sign_primary_house_system_unchanged",
            "sripati_used_as_secondary_bhava_reference",
        ],
        "excluded_rules": [
            "interpretive_prediction_text",
            "automatic_replacement_of_whole_sign_houses",
            "generator_package_wide_usage",
            "ui_layout_change",
            "rectification_window_collapse",
        ],
        "cusp_status": cusp_status,
        "houses": houses,
        "planets": planet_rows,
        "summary": {
            "changed_house_count": len(changed_planets),
            "changed_planets": changed_planets,
            "birth_time_sensitive": True,
            "whole_sign_primary_house_system_unchanged": True,
        },
        "notes": [
            "Technical control layer only; no prediction text is generated.",
            "Whole Sign houses remain the primary house system in this API response.",
            "Rectification candidate windows and interpretive flexibility are not collapsed by this layer.",
        ],
    }


def _build_bhava_bala(houses, lordships, ashtakavarga, shadbala, bhava_chalit):
    sarva_rows = (ashtakavarga or {}).get("sarva", {}).get("by_sign", [])
    sarva_by_house = {
        row.get("house"): row
        for row in sarva_rows
    }
    shadbala_by_planet = {
        planet.get("planet"): planet
        for planet in (shadbala or {}).get("planets", [])
    }
    bhava_chalit_houses = {
        house.get("house"): house
        for house in (bhava_chalit or {}).get("houses", [])
    }
    bhava_chalit_planets = (bhava_chalit or {}).get("planets", [])
    rows = []

    for house in houses:
        house_number = house["house"]
        sign_index = house["sign_index"]
        lordship = lordships.get(str(house_number), {})
        lord_name = house.get("lord")
        lord_shadbala = shadbala_by_planet.get(lord_name, {})
        sarva_row = sarva_by_house.get(house_number, {})
        bhinna_row = next(
            (
                row
                for row in (ashtakavarga or {})
                .get("bhinna", {})
                .get(lord_name, {})
                .get("by_sign", [])
                if row.get("sign_index") == sign_index
            ),
            {},
        )
        chalit_house = bhava_chalit_houses.get(house_number, {})
        chalit_changes = [
            {
                "planet": planet.get("planet"),
                "whole_sign_house": planet.get("whole_sign_house"),
                "bhava_chalit_house": planet.get("bhava_chalit_house"),
            }
            for planet in bhava_chalit_planets
            if planet.get("house_changed")
            and (
                planet.get("whole_sign_house") == house_number
                or planet.get("bhava_chalit_house") == house_number
            )
        ]

        kendra_house = house_number in {1, 4, 7, 10}
        panapara_house = house_number in {2, 5, 8, 11}
        bhava_dig_bala = 60.0 if kendra_house else 30.0 if panapara_house else 15.0
        aspect_names = list(house.get("aspected_by", []))
        benefic_aspects = sum(1 for name in aspect_names if name in DRIK_BALA_NATURAL_BENEFICS)
        malefic_aspects = sum(1 for name in aspect_names if name in DRIK_BALA_NATURAL_MALEFICS)
        bhava_drishti_bala = (benefic_aspects - malefic_aspects) * 15.0
        lord_score = lord_shadbala.get("total_score")
        score = round(
            float(lord_score or 0.0) + bhava_dig_bala + bhava_drishti_bala,
            2,
        )

        rows.append({
            "house": house_number,
            "sign": house.get("sign"),
            "sign_tr": house.get("sign_tr"),
            "sign_index": sign_index,
            "lord": lord_name,
            "occupants": house.get("occupants", []),
            "graha_aspected_by": house.get("aspected_by", []),
            "rashi_aspected_by": house.get("rashi_aspected_by", []),
            "karakas": house.get("karakas", []),
            "lordship": {
                "lord_house": lordship.get("lord_house"),
                "lord_sign": lordship.get("lord_sign"),
                "condition": lordship.get("condition", {}),
            },
            "ashtakavarga": {
                "sav": sarva_row.get("bindus"),
                "sav_support_level": (
                    _ashtakavarga_transit_support_level(sarva_row["bindus"])
                    if isinstance(sarva_row.get("bindus"), (int, float))
                    else "not_available"
                ),
                "lord_bav": bhinna_row.get("bindus"),
            },
            "lord_shadbala": {
                "total_score": lord_shadbala.get("total_score"),
                "grade": lord_shadbala.get("grade"),
                "confidence": lord_shadbala.get("confidence"),
            },
            "bhava_chalit": {
                "cusp_sign": chalit_house.get("cusp_sign"),
                "cusp_degree": chalit_house.get("cusp_degree"),
                "changed_planets_touching_house": chalit_changes,
            },
            "components": {
                "bhavadhipati_bala": lord_score,
                "bhava_dig_bala": bhava_dig_bala,
                "bhava_drishti_bala": bhava_drishti_bala,
                "benefic_graha_aspect_count": benefic_aspects,
                "malefic_graha_aspect_count": malefic_aspects,
            },
            "score": score,
            "score_status": "calculated_internal_formula",
        })

    return {
        "status": "implemented_internal_formula",
        "confidence": "medium",
        "method": "bhavadhipati_bala_plus_bhava_dig_bala_plus_bhava_drishti_bala",
        "source_layers": [
            "houses",
            "lordships",
            "aspects",
            "ashtakavarga",
            "shadbala",
            "bhava_chalit",
        ],
        "assumptions": [
            "whole_sign_primary_house_system_unchanged",
            "uses_existing_lord_shadbala",
            "kendra_panapara_apoklima_dig_bala_scale",
            "graha_aspect_benefic_malefic_component_scale",
        ],
        "excluded_rules": [
            "interpretive_prediction_text",
            "rectification_window_collapse",
            "prediction_window_narrowing",
            "automatic_house_system_replacement",
            "external_reference_result_comparison_pending",
        ],
        "houses": rows,
        "summary": {
            "house_count": len(rows),
            "scored": True,
            "score_status": "calculated_internal_formula",
            "external_validation_status": "pending_reference_validation",
            "birth_time_sensitive": True,
            "whole_sign_primary_house_system_unchanged": True,
        },
    }


def _build_lordships(chart):
    planet_by_name = _planet_index_by_name(chart)
    sun_longitude = planet_by_name["Sun"]["longitude"]
    lagna_sign_index = chart["lagna"]["sign_index"]
    lordships = {}

    for house_number in range(1, 13):
        sign_index = (lagna_sign_index + house_number - 1) % 12
        lord_name = SIGN_LORDS[sign_index]
        lord_planet = planet_by_name[lord_name]
        dignity = _dignity_for_planet(lord_planet)
        combustion = _combustion_for_planet(lord_planet, sun_longitude)
        vargottama = lord_planet["sign_en"] == lord_planet["navamsha_sign_en"]

        lordships[str(house_number)] = {
            "lord": lord_name,
            "lord_id": PLANET_IDS.get(lord_planet["abbr"], lord_name.lower()),
            "lord_house": lord_planet["house"],
            "lord_sign": lord_planet["sign_en"],
            "lord_sign_index": lord_planet["sign_index"],
            "lord_nakshatra": lord_planet["nakshatra"]["name"],
            "lord_nakshatra_lord": lord_planet["nakshatra"]["lord"],
            "condition": {
                "dignity": dignity["essential"],
                "uccha": dignity["uccha"],
                "neecha": dignity["neecha"],
                "swakshetra": dignity["swakshetra"],
                "moolatrikona": dignity["moolatrikona"],
                "natural_friendship": dignity["natural_friendship"],
                "combust": combustion["is_combust"],
                "retrograde": lord_planet["retrograde"],
                "vargottama": vargottama,
            },
        }

    return lordships


def _ashtakavarga_sign_row(sign_index, bindus, lagna_sign_index):
    return {
        "sign_index": sign_index,
        "sign": SIGNS_EN[sign_index],
        "sign_tr": _sign_tr(SIGNS_TR[sign_index]),
        "house": ((sign_index - lagna_sign_index) % 12) + 1,
        "bindus": bindus,
    }


def _rank_ashtakavarga_signs(rows, reverse):
    return sorted(
        (
            {
                "sign": row["sign"],
                "sign_index": row["sign_index"],
                "house": row["house"],
                "bindus": row["bindus"],
            }
            for row in rows
        ),
        key=lambda row: (row["bindus"], row["house"]),
        reverse=reverse,
    )[:3]


def _ashtakavarga_transit_support_level(bindus):
    if bindus >= 30:
        return "high_support"
    if bindus >= 25:
        return "moderate_support"
    if bindus >= 20:
        return "low_support"
    return "challenging"


def _build_ashtakavarga_transit_scoring(sarva_rows, bhinna, transit_planets):
    if not transit_planets:
        return {
            "status": "not_available",
            "reason": "transit_snapshot_not_supplied",
            "rows": [],
        }

    sarva_by_sign = {row["sign_index"]: row for row in sarva_rows}
    rows = []
    for transit in transit_planets:
        sign_index = transit["sign_index"]
        sarva_row = sarva_by_sign[sign_index]
        planet_bhinna = bhinna.get(transit["name"])
        planet_bhinna_row = None
        if planet_bhinna:
            planet_bhinna_row = next(
                row for row in planet_bhinna["by_sign"]
                if row["sign_index"] == sign_index
            )

        rows.append({
            "planet": transit["name"],
            "planet_id": transit["id"],
            "sign": transit["sign"],
            "sign_tr": transit["sign_tr"],
            "sign_index": sign_index,
            "degree_str": transit["degree_str"],
            "house_from_natal_lagna": transit["house_from_natal_lagna"],
            "house_from_natal_moon": transit["house_from_natal_moon"],
            "sarva_bindus": sarva_row["bindus"],
            "sarva_support_level": _ashtakavarga_transit_support_level(sarva_row["bindus"]),
            "planet_bhinna_bindus": planet_bhinna_row["bindus"] if planet_bhinna_row else None,
            "planet_bhinna_available": planet_bhinna_row is not None,
        })

    return {
        "status": "implemented_snapshot_scoring",
        "method": "current_transit_sign_scored_by_sarvashtakavarga_bindus",
        "source_rule": "A transit receives the Sarvashtakavarga bindu score of its current sign; planet-specific BAV bindu is included when available",
        "assumptions": [
            "uses_current_transit_snapshot_generated_in_same_api_response",
            "support_thresholds_are_api_technical_buckets_not_prediction",
            "nodes_have_sarva_bindus_but_no_planet_specific_bhinna_bindus",
        ],
        "excluded_rules": [
            "ashtakavarga_rekha_reduction",
            "gochar_vedha_rules",
            "planet_specific_transit_result_text",
            "period_search_for_transit_ingress",
        ],
        "rows": rows,
    }


TRIKONA_SHODHANA_GROUPS = [
    [0, 4, 8],
    [1, 5, 9],
    [2, 6, 10],
    [3, 7, 11],
]

EKADHIPATYA_SHODHANA_PAIRS = [
    {"lord": "Mars", "signs": [0, 7]},
    {"lord": "Venus", "signs": [1, 6]},
    {"lord": "Mercury", "signs": [2, 5]},
    {"lord": "Jupiter", "signs": [8, 11]},
    {"lord": "Saturn", "signs": [9, 10]},
]
RASHI_GUNAKARA = {
    0: 7,
    1: 10,
    2: 8,
    3: 4,
    4: 10,
    5: 5,
    6: 7,
    7: 8,
    8: 9,
    9: 5,
    10: 11,
    11: 12,
}
GRAHA_GUNAKARA = {
    "Sun": 5,
    "Moon": 5,
    "Mars": 8,
    "Mercury": 5,
    "Jupiter": 10,
    "Venus": 7,
    "Saturn": 5,
}


def _build_trikona_shodhana_for_planet(planet_name, rows, lagna_sign_index):
    bindus_by_sign = {row["sign_index"]: row["bindus"] for row in rows}
    adjusted = dict(bindus_by_sign)
    group_rows = []

    for group in TRIKONA_SHODHANA_GROUPS:
        original_values = [bindus_by_sign[sign_index] for sign_index in group]
        reduction = min(original_values)
        for sign_index in group:
            adjusted[sign_index] = max(0, adjusted[sign_index] - reduction)
        group_rows.append({
            "group_signs": [
                {
                    "sign": SIGNS_EN[sign_index],
                    "sign_index": sign_index,
                    "original_bindus": bindus_by_sign[sign_index],
                    "adjusted_bindus": adjusted[sign_index],
                }
                for sign_index in group
            ],
            "reduction": reduction,
        })

    adjusted_rows = [
        _ashtakavarga_sign_row(sign_index, adjusted[sign_index], lagna_sign_index)
        for sign_index in range(12)
    ]
    total_before = sum(bindus_by_sign.values())
    total_after = sum(adjusted.values())

    return {
        "planet": planet_name,
        "total_before": total_before,
        "total_after": total_after,
        "total_reduction": total_before - total_after,
        "groups": group_rows,
        "by_sign": adjusted_rows,
    }


def _build_trikona_shodhana(bhinna, lagna_sign_index):
    planet_rows = {
        planet_name: _build_trikona_shodhana_for_planet(
            planet_name,
            data["by_sign"],
            lagna_sign_index,
        )
        for planet_name, data in bhinna.items()
    }
    sarva_after_counts = [0] * 12
    for planet in planet_rows.values():
        for row in planet["by_sign"]:
            sarva_after_counts[row["sign_index"]] += row["bindus"]

    sarva_after_rows = [
        _ashtakavarga_sign_row(sign_index, bindus, lagna_sign_index)
        for sign_index, bindus in enumerate(sarva_after_counts)
    ]

    return {
        "status": "implemented_technical_variant",
        "method": "trikona_group_minimum_bindu_reduction",
        "source_rule": "For each trinal sign group, the minimum bindu count is subtracted from all three signs in that group",
        "assumptions": [
            "groups_are_fire_earth_air_water_trines",
            "applied_to_each_planet_bhinna_ashtakavarga_independently",
            "negative_bindus_are_clamped_to_zero",
            "used_as_technical_intermediate_table_not_final_shodhya_pinda",
        ],
        "excluded_rules": [
            "ekadhipatya_shodhana",
            "shodhya_pinda",
            "parampara_specific_exception_rules",
        ],
        "groups": [
            [SIGNS_EN[sign_index] for sign_index in group]
            for group in TRIKONA_SHODHANA_GROUPS
        ],
        "planets": planet_rows,
        "sarva_after_trikona": {
            "total": sum(sarva_after_counts),
            "by_sign": sarva_after_rows,
            "strongest_signs": _rank_ashtakavarga_signs(sarva_after_rows, True),
            "weakest_signs": _rank_ashtakavarga_signs(sarva_after_rows, False),
        },
    }


def _occupied_signs_for_ekadhipatya(chart):
    occupied = {sign_index: [] for sign_index in range(12)}
    for planet in chart["planets"]:
        occupied[planet["sign_index"]].append(_planet_name_en(planet))
    return occupied


def _ekadhipatya_pair_adjustment(adjusted, pair, occupied_signs):
    first, second = pair["signs"]
    first_before = adjusted[first]
    second_before = adjusted[second]
    first_occupied = bool(occupied_signs[first])
    second_occupied = bool(occupied_signs[second])
    first_reduction = 0
    second_reduction = 0

    if first_before == 0 or second_before == 0:
        action = "skipped_zero_bindu_pair"
    elif first_occupied and second_occupied:
        action = "skipped_both_signs_occupied"
    elif first_occupied and not second_occupied:
        second_reduction = min(first_before, second_before)
        action = "reduced_unoccupied_pair_sign"
    elif second_occupied and not first_occupied:
        first_reduction = min(first_before, second_before)
        action = "reduced_unoccupied_pair_sign"
    else:
        reduction = min(first_before, second_before)
        first_reduction = reduction
        second_reduction = reduction
        action = "reduced_both_unoccupied_pair_signs_by_minimum"

    adjusted[first] = max(0, first_before - first_reduction)
    adjusted[second] = max(0, second_before - second_reduction)

    return {
        "lord": pair["lord"],
        "signs": [
            {
                "sign": SIGNS_EN[first],
                "sign_index": first,
                "occupied_by": occupied_signs[first],
                "before": first_before,
                "reduction": first_reduction,
                "after": adjusted[first],
            },
            {
                "sign": SIGNS_EN[second],
                "sign_index": second,
                "occupied_by": occupied_signs[second],
                "before": second_before,
                "reduction": second_reduction,
                "after": adjusted[second],
            },
        ],
        "action": action,
    }


def _build_ekadhipatya_shodhana_for_planet(planet_name, trikona_row, occupied_signs, lagna_sign_index):
    bindus_by_sign = {
        row["sign_index"]: row["bindus"]
        for row in trikona_row["by_sign"]
    }
    adjusted = dict(bindus_by_sign)
    pair_rows = [
        _ekadhipatya_pair_adjustment(adjusted, pair, occupied_signs)
        for pair in EKADHIPATYA_SHODHANA_PAIRS
    ]
    adjusted_rows = [
        _ashtakavarga_sign_row(sign_index, adjusted[sign_index], lagna_sign_index)
        for sign_index in range(12)
    ]
    total_before = sum(bindus_by_sign.values())
    total_after = sum(adjusted.values())

    return {
        "planet": planet_name,
        "total_before": total_before,
        "total_after": total_after,
        "total_reduction": total_before - total_after,
        "pairs": pair_rows,
        "by_sign": adjusted_rows,
    }


def _build_ekadhipatya_shodhana(trikona, chart, lagna_sign_index):
    occupied_signs = _occupied_signs_for_ekadhipatya(chart)
    planet_rows = {
        planet_name: _build_ekadhipatya_shodhana_for_planet(
            planet_name,
            data,
            occupied_signs,
            lagna_sign_index,
        )
        for planet_name, data in trikona["planets"].items()
    }
    sarva_after_counts = [0] * 12
    for planet in planet_rows.values():
        for row in planet["by_sign"]:
            sarva_after_counts[row["sign_index"]] += row["bindus"]

    sarva_after_rows = [
        _ashtakavarga_sign_row(sign_index, bindus, lagna_sign_index)
        for sign_index, bindus in enumerate(sarva_after_counts)
    ]

    return {
        "status": "implemented_technical_variant",
        "method": "same_lord_sign_pair_reduction_after_trikona_shodhana",
        "source_rule": "For non-luminary same-lord sign pairs, reduce bindus based on occupancy-aware pair rules after Trikona Shodhana",
        "assumptions": [
            "applied_after_trikona_shodhana",
            "same_lord_pairs_exclude_sun_and_moon_single_sign_ownership",
            "occupied_signs_use_all_natal_grahas_including_nodes",
            "both_signs_occupied_pairs_are_not_reduced",
            "one_occupied_pair_reduces_only_the_unoccupied_sign_by_pair_minimum",
            "no_occupied_pair_reduces_both_signs_by_pair_minimum",
        ],
        "excluded_rules": [
            "alternate_ekadhipatya_exception_orders",
            "shodhya_pinda",
            "parampara_specific_occupied_sign_exceptions",
        ],
        "pairs": [
            {
                "lord": pair["lord"],
                "signs": [SIGNS_EN[sign_index] for sign_index in pair["signs"]],
            }
            for pair in EKADHIPATYA_SHODHANA_PAIRS
        ],
        "occupied_signs": {
            SIGNS_EN[sign_index]: occupants
            for sign_index, occupants in occupied_signs.items()
            if occupants
        },
        "planets": planet_rows,
        "sarva_after_ekadhipatya": {
            "total": sum(sarva_after_counts),
            "by_sign": sarva_after_rows,
            "strongest_signs": _rank_ashtakavarga_signs(sarva_after_rows, True),
            "weakest_signs": _rank_ashtakavarga_signs(sarva_after_rows, False),
        },
    }


def _build_shodhya_pinda_for_planet(planet_name, ekadhipatya_row, chart):
    bindus_by_sign = {
        row["sign_index"]: row["bindus"]
        for row in ekadhipatya_row["by_sign"]
    }
    rashi_rows = []
    for sign_index in range(12):
        bindus = bindus_by_sign[sign_index]
        multiplier = RASHI_GUNAKARA[sign_index]
        rashi_rows.append({
            "sign": SIGNS_EN[sign_index],
            "sign_index": sign_index,
            "bindus": bindus,
            "multiplier": multiplier,
            "product": bindus * multiplier,
        })

    graha_rows = []
    for natal in chart["planets"]:
        occupant = _planet_name_en(natal)
        multiplier = GRAHA_GUNAKARA.get(occupant)
        if multiplier is None:
            continue
        bindus = bindus_by_sign[natal["sign_index"]]
        graha_rows.append({
            "occupant": occupant,
            "occupant_id": PLANET_IDS.get(natal["abbr"]),
            "sign": natal["sign_en"],
            "sign_index": natal["sign_index"],
            "bindus": bindus,
            "multiplier": multiplier,
            "product": bindus * multiplier,
        })

    rashi_pinda = sum(row["product"] for row in rashi_rows)
    graha_pinda = sum(row["product"] for row in graha_rows)

    return {
        "planet": planet_name,
        "rashi_pinda": rashi_pinda,
        "graha_pinda": graha_pinda,
        "shodhya_pinda": rashi_pinda + graha_pinda,
        "rashi_rows": rashi_rows,
        "graha_rows": graha_rows,
    }


def _build_shodhya_pinda(ekadhipatya, chart):
    planet_rows = {
        planet_name: _build_shodhya_pinda_for_planet(
            planet_name,
            data,
            chart,
        )
        for planet_name, data in ekadhipatya["planets"].items()
    }
    ranking = sorted(
        (
            {
                "planet": planet_name,
                "rashi_pinda": row["rashi_pinda"],
                "graha_pinda": row["graha_pinda"],
                "shodhya_pinda": row["shodhya_pinda"],
            }
            for planet_name, row in planet_rows.items()
        ),
        key=lambda row: (-row["shodhya_pinda"], row["planet"]),
    )

    return {
        "status": "implemented_technical_variant",
        "method": "rashi_pinda_plus_graha_pinda_from_ekadhipatya_reduced_bav",
        "source_rule": "After Trikona and Ekadhipatya Shodhana, reduced bindus are multiplied by Rashi Gunakara and Graha Gunakara; the sum is Shodhya Pinda",
        "assumptions": [
            "uses_ekadhipatya_reduced_bav_as_input",
            "virgo_rashi_gunakara_uses_5",
            "graha_pinda_uses_seven_classical_planet_occupants_only",
            "rahu_ketu_excluded_from_graha_pinda_multiplier_rows",
            "ranking_is_numeric_only_not_interpretive_judgement",
        ],
        "excluded_rules": [
            "alternative_virgo_multiplier_6_variant",
            "post_pinda_lagna_or_lordship_interpretation",
            "longevity_or_event_timing_applications",
            "external_reference_validation_pending",
        ],
        "rashi_gunakara": {
            SIGNS_EN[sign_index]: multiplier
            for sign_index, multiplier in RASHI_GUNAKARA.items()
        },
        "graha_gunakara": GRAHA_GUNAKARA,
        "planets": planet_rows,
        "ranking": ranking,
    }


def _build_ashtakavarga(chart, transit_planets=None):
    planet_by_name = _planet_index_by_name(chart)
    source_signs = {
        planet_name: planet_by_name[planet_name]["sign_index"]
        for planet_name in ASHTAKAVARGA_PLANETS
    }
    source_signs["Lagna"] = chart["lagna"]["sign_index"]
    lagna_sign_index = chart["lagna"]["sign_index"]

    bhinna = {}
    sarva_counts = [0] * 12

    for target_planet in ASHTAKAVARGA_PLANETS:
        sign_counts = [0] * 12
        source_breakdown = []
        for source_name, offsets in ASHTAKAVARGA_BINDU_RULES[target_planet].items():
            source_sign_index = source_signs[source_name]
            bindu_signs = sorted(
                (source_sign_index + offset - 1) % 12
                for offset in offsets
            )
            for sign_index in bindu_signs:
                sign_counts[sign_index] += 1
                sarva_counts[sign_index] += 1
            source_breakdown.append({
                "source": source_name,
                "source_sign": SIGNS_EN[source_sign_index],
                "source_sign_index": source_sign_index,
                "bindu_houses_from_source": offsets,
                "bindu_signs": [
                    {
                        "sign": SIGNS_EN[sign_index],
                        "sign_index": sign_index,
                    }
                    for sign_index in bindu_signs
                ],
            })

        rows = [
            _ashtakavarga_sign_row(sign_index, bindus, lagna_sign_index)
            for sign_index, bindus in enumerate(sign_counts)
        ]
        bhinna[target_planet] = {
            "total": sum(sign_counts),
            "expected_total": sum(
                len(offsets)
                for offsets in ASHTAKAVARGA_BINDU_RULES[target_planet].values()
            ),
            "by_sign": rows,
            "strongest_signs": _rank_ashtakavarga_signs(rows, True),
            "weakest_signs": _rank_ashtakavarga_signs(rows, False),
            "sources": source_breakdown,
        }

    sarva_rows = [
        _ashtakavarga_sign_row(sign_index, bindus, lagna_sign_index)
        for sign_index, bindus in enumerate(sarva_counts)
    ]
    trikona_shodhana = _build_trikona_shodhana(bhinna, lagna_sign_index)
    ekadhipatya_shodhana = _build_ekadhipatya_shodhana(
        trikona_shodhana,
        chart,
        lagna_sign_index,
    )
    shodhya_pinda = _build_shodhya_pinda(ekadhipatya_shodhana, chart)

    return {
        "status": "implemented_shodhana_pinda_and_transit_scoring",
        "confidence": "medium",
        "method": "classical_bhinna_ashtakavarga_and_sarvashtakavarga_from_d1_sign_positions",
        "includes": [
            "bhinna_ashtakavarga_for_7_classical_planets",
            "sarvashtakavarga_sign_totals",
            "lagna_as_source",
            "current_transit_sarva_scoring",
            "trikona_shodhana_technical_variant",
            "ekadhipatya_shodhana_technical_variant",
            "shodhya_pinda_technical_variant",
        ],
        "excludes": [
            "prastara_ashtakavarga",
            "post_pinda_interpretive_applications",
        ],
        "ruleset": {
            "source_count": 8,
            "target_planets": ASHTAKAVARGA_PLANETS,
            "nodes": "excluded",
        },
        "bhinna": bhinna,
        "sarva": {
            "total": sum(sarva_counts),
            "expected_total": sum(
                item["expected_total"]
                for item in bhinna.values()
            ),
            "by_sign": sarva_rows,
            "strongest_signs": _rank_ashtakavarga_signs(sarva_rows, True),
            "weakest_signs": _rank_ashtakavarga_signs(sarva_rows, False),
        },
        "transit_scoring": _build_ashtakavarga_transit_scoring(
            sarva_rows,
            bhinna,
            transit_planets or [],
        ),
        "shodhana": {
            "trikona": trikona_shodhana,
            "ekadhipatya": ekadhipatya_shodhana,
            "shodhya_pinda": shodhya_pinda,
        },
    }


def _transit_planet(body_id, name, abbr, jd, flags, chart, planets_by_sign, moon_sign_index):
    pos, _ = swe.calc_ut(jd, body_id, flags)
    longitude = pos[0] % 360.0
    speed = pos[3]
    sign_index = int(longitude / 30.0)
    degree = longitude % 30.0

    return {
        "id": PLANET_IDS.get(abbr, name.lower().replace(" ", "_")),
        "name": name,
        "abbr": abbr,
        "longitude": longitude,
        "sign_index": sign_index,
        "sign": SIGNS_EN[sign_index],
        "sign_tr": _sign_tr(SIGNS_TR[sign_index]),
        "degree": degree,
        "degree_str": dms_str(degree),
        "nakshatra": get_nakshatra(longitude),
        "motion": {
            "retrograde": speed < 0 if body_id not in (swe.SUN, swe.MOON) else False,
            "speed": speed,
            "speed_status": "retrograde" if speed < 0 and body_id not in (swe.SUN, swe.MOON) else "normal",
        },
        "house_from_natal_lagna": ((sign_index - chart["lagna"]["sign_index"]) % 12) + 1,
        "house_from_natal_moon": ((sign_index - moon_sign_index) % 12) + 1,
        "natal_planets_in_sign": planets_by_sign[sign_index],
    }


def _find_transit(transit_planets, name):
    return next(planet for planet in transit_planets if planet["name"] == name)


def _transit_axis_info(node, reference_sign_index):
    return {
        "node": node["name"],
        "sign": node["sign"],
        "sign_index": node["sign_index"],
        "house_from_reference": ((node["sign_index"] - reference_sign_index) % 12) + 1,
        "degree_str": node["degree_str"],
    }


def _build_transit_special_checks(chart, transit_planets, moon):
    saturn = _find_transit(transit_planets, "Saturn")
    jupiter = _find_transit(transit_planets, "Jupiter")
    rahu = _find_transit(transit_planets, "Rahu (True)")
    ketu = _find_transit(transit_planets, "Ketu")
    lagna_sign_index = chart["lagna"]["sign_index"]
    moon_sign_index = moon["sign_index"]

    saturn_from_moon = saturn["house_from_natal_moon"]
    saturn_from_lagna = saturn["house_from_natal_lagna"]
    jupiter_from_moon = jupiter["house_from_natal_moon"]
    jupiter_from_lagna = jupiter["house_from_natal_lagna"]

    return {
        "saturn": {
            "sade_sati": {
                "is_active": saturn_from_moon in {12, 1, 2},
                "phase": {
                    12: "first_phase_12th_from_moon",
                    1: "middle_phase_over_moon",
                    2: "last_phase_2nd_from_moon",
                }.get(saturn_from_moon),
                "house_from_moon": saturn_from_moon,
                "saturn_sign": saturn["sign"],
                "saturn_degree_str": saturn["degree_str"],
            },
            "ashtama_shani": {
                "is_active": saturn_from_moon == 8,
                "house_from_moon": saturn_from_moon,
            },
            "kantaka_shani": {
                "is_active": saturn_from_moon in {4, 7, 10},
                "house_from_moon": saturn_from_moon,
            },
            "from_lagna": {
                "house": saturn_from_lagna,
                "sign": saturn["sign"],
                "degree_str": saturn["degree_str"],
            },
        },
        "jupiter": {
            "from_moon": {
                "house": jupiter_from_moon,
                "sign": jupiter["sign"],
                "degree_str": jupiter["degree_str"],
                "traditionally_supportive": jupiter_from_moon in {2, 5, 7, 9, 11},
            },
            "from_lagna": {
                "house": jupiter_from_lagna,
                "sign": jupiter["sign"],
                "degree_str": jupiter["degree_str"],
                "traditionally_supportive": jupiter_from_lagna in {2, 5, 7, 9, 11},
            },
        },
        "nodes": {
            "from_moon": {
                "rahu": _transit_axis_info(rahu, moon_sign_index),
                "ketu": _transit_axis_info(ketu, moon_sign_index),
            },
            "from_lagna": {
                "rahu": _transit_axis_info(rahu, lagna_sign_index),
                "ketu": _transit_axis_info(ketu, lagna_sign_index),
            },
        },
    }


def _build_transit_natal_contacts(chart, transit_planets, orb=3.0):
    contacts = []
    for transit in transit_planets:
        for natal in chart["planets"]:
            distance = _angular_distance(transit["longitude"], natal["longitude"])
            same_sign = transit["sign_index"] == natal["sign_index"]
            if same_sign or distance <= orb:
                contacts.append({
                    "transit_planet": transit["name"],
                    "natal_planet": _planet_name_en(natal),
                    "contact_type": "degree_orb" if distance <= orb else "same_sign",
                    "orb": distance,
                    "orb_limit": orb,
                    "sign": transit["sign"],
                    "transit_degree_str": transit["degree_str"],
                    "natal_degree_str": natal["degree_str"],
                    "house_from_lagna": transit["house_from_natal_lagna"],
                    "house_from_moon": transit["house_from_natal_moon"],
                })

    return sorted(
        contacts,
        key=lambda item: (item["contact_type"] != "degree_orb", item["orb"], item["transit_planet"]),
    )


def _transit_name_for_dasha_lord(lord):
    if lord == "Rahu":
        return "Rahu (True)"
    return lord


def _build_transit_dasha_cross_reference(chart, transit_planets, natal_contacts, dashas):
    active = dashas.get("vimshottari", {}).get("current_active", {}) if dashas else {}
    active_rows = []

    for level in DASHA_LEVELS:
        period = active.get(level)
        if not period:
            continue
        lord = period["lord"]
        transit_name = _transit_name_for_dasha_lord(lord)
        transit = next(
            (planet for planet in transit_planets if planet["name"] == transit_name),
            None,
        )
        natal = next(
            (_v2_planet for _v2_planet in chart["planets"] if _planet_name_en(_v2_planet) == lord),
            None,
        )
        contacts_as_transit = [
            contact for contact in natal_contacts
            if contact["transit_planet"] == transit_name
        ]
        contacts_to_natal_lord = [
            contact for contact in natal_contacts
            if contact["natal_planet"] == lord
        ]

        active_rows.append({
            "level": level,
            "lord": lord,
            "period_start": period.get("actual_start"),
            "period_end": period.get("actual_end"),
            "transit": {
                "available": transit is not None,
                "sign": transit.get("sign") if transit else None,
                "sign_tr": transit.get("sign_tr") if transit else None,
                "degree_str": transit.get("degree_str") if transit else None,
                "house_from_natal_lagna": transit.get("house_from_natal_lagna") if transit else None,
                "house_from_natal_moon": transit.get("house_from_natal_moon") if transit else None,
                "natal_planets_in_sign": transit.get("natal_planets_in_sign", []) if transit else [],
            },
            "natal": {
                "available": natal is not None,
                "sign": natal.get("sign_en") if natal else None,
                "house": natal.get("house") if natal else None,
                "degree_str": natal.get("degree_str") if natal else None,
            },
            "contacts_as_transit": contacts_as_transit,
            "contacts_to_natal_lord": contacts_to_natal_lord,
        })

    return {
        "status": "implemented_current_dasha_transit_cross_reference" if active_rows else "not_available",
        "method": "current_vimshottari_lords_cross_referenced_with_current_gochar_snapshot",
        "source_rule": "For each current Vimshottari level, expose the lord's current transit position and exact/same-sign natal contacts",
        "assumptions": [
            "uses_dashas.vimshottari.current_active_not_birth_active",
            "transit_snapshot_and_current_active_share_reference_datetime",
            "contacts_reuse_transit_natal_contacts_orb_model",
            "rahu_dasha_lord_maps_to_true_node_transit",
        ],
        "excluded_rules": [
            "event_specific_prediction",
            "transit_period_start_end_search",
            "dasha_lord_strength_weighting",
            "gochar_ashtakavarga_scoring",
        ],
        "active_path": active.get("path", []),
        "rows": active_rows,
    }


def _build_transits(chart, dashas=None, transit_reference=None):
    reference = transit_reference or _transit_reference_from_options({}, 0.0)
    reference_dt_utc = reference["datetime_utc"]
    jd = _datetime_to_julian_day_utc(reference_dt_utc)
    swe.set_sid_mode(swe.SIDM_LAHIRI)
    flags = swe.FLG_SIDEREAL | swe.FLG_SPEED
    planets_by_sign = {sign_index: [] for sign_index in range(12)}
    for planet in chart["planets"]:
        planets_by_sign[planet["sign_index"]].append(_planet_name_en(planet))
    moon = next(planet for planet in chart["planets"] if planet["abbr"] == "Mo")

    transit_planets = [
        _transit_planet(
            body_id,
            name,
            abbr,
            jd,
            flags,
            chart,
            planets_by_sign,
            moon["sign_index"],
        )
        for body_id, name, abbr in TRANSIT_BODY_SPECS
    ]

    rahu = next(planet for planet in transit_planets if planet["abbr"] == "Ra")
    ketu_longitude = (rahu["longitude"] + 180.0) % 360.0
    ketu_sign_index = int(ketu_longitude / 30.0)
    ketu = {
        "id": "ketu",
        "name": "Ketu",
        "abbr": "Ke",
        "longitude": ketu_longitude,
        "sign_index": ketu_sign_index,
        "sign": SIGNS_EN[ketu_sign_index],
        "sign_tr": _sign_tr(SIGNS_TR[ketu_sign_index]),
        "degree": ketu_longitude % 30.0,
        "degree_str": dms_str(ketu_longitude % 30.0),
        "nakshatra": get_nakshatra(ketu_longitude),
        "motion": {
            "retrograde": True,
            "speed": rahu["motion"]["speed"],
            "speed_status": "retrograde",
        },
        "house_from_natal_lagna": ((ketu_sign_index - chart["lagna"]["sign_index"]) % 12) + 1,
        "house_from_natal_moon": ((ketu_sign_index - moon["sign_index"]) % 12) + 1,
        "natal_planets_in_sign": planets_by_sign[ketu_sign_index],
    }
    transit_planets.append(ketu)
    special_checks = _build_transit_special_checks(chart, transit_planets, moon)
    natal_contacts = _build_transit_natal_contacts(chart, transit_planets)

    return {
        "status": "implemented_current_snapshot_with_dasha_cross_reference"
        if reference["mode"] == "current"
        else "implemented_selected_date_snapshot_with_dasha_cross_reference",
        "confidence": "medium",
        "method": "lahiri_sidereal_gochar_snapshot_against_natal_lagna_and_moon",
        "source_rule": "Sidereal transits for the reference datetime are counted from natal whole-sign Lagna and natal Moon",
        "assumptions": [
            "lahiri_ayanamsa",
            "whole_sign_reference_houses",
            "true_node_for_rahu_and_opposite_ketu",
            "same_sign_contacts_and_3_degree_orb_contacts",
            "selected_transit_datetime_uses_options_transit_tz_offset_or_birth_tz_offset",
        ],
        "excluded_rules": [
            "transit_period_search",
            "gochar_ashtakavarga_scoring",
            "regional_parampara_variants_for_jupiter_saturn_results",
            "interpretive_prediction_text",
        ],
        "generated_at_utc": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "reference_datetime_utc": reference_dt_utc.isoformat(timespec="seconds"),
        "reference_mode": reference["mode"],
        "requested_date": reference["requested_date"],
        "requested_time": reference["requested_time"],
        "requested_tz_offset": reference["tz_offset"],
        "time_source": reference["time_source"],
        "julian_day_ut": jd,
        "reference": {
            "natal_lagna_sign": chart["lagna"]["sign_en"],
            "natal_lagna_sign_index": chart["lagna"]["sign_index"],
            "natal_moon_sign": moon["sign_en"],
            "natal_moon_sign_index": moon["sign_index"],
        },
        "planets": transit_planets,
        "special_checks": special_checks,
        "natal_contacts": natal_contacts,
        "dasha_cross_reference": _build_transit_dasha_cross_reference(
            chart,
            transit_planets,
            natal_contacts,
            dashas or {},
        ),
        "notes": [
            "Snapshot only; no transit period search.",
            "Transit houses are counted from natal whole-sign Lagna and natal Moon.",
            "Natal contacts include same-sign contacts and exact-degree contacts within 3 degrees.",
        ],
    }


def _sun_longitude_at_jd(jd):
    swe.set_sid_mode(swe.SIDM_LAHIRI)
    flags = swe.FLG_SIDEREAL | swe.FLG_SPEED
    pos, _ = swe.calc_ut(jd, swe.SUN, flags)
    return pos[0] % 360.0


def _signed_longitude_delta(longitude, target_longitude):
    return ((longitude - target_longitude + 180.0) % 360.0) - 180.0


def _safe_target_date(year, month, day):
    while day > 28:
        try:
            return datetime(year, month, day)
        except ValueError:
            day -= 1
    return datetime(year, month, day)


def _utc_datetime_from_jd(jd):
    year, month, day, hour_decimal = swe.revjul(jd)
    return (
        datetime(year, month, day, tzinfo=timezone.utc)
        + timedelta(hours=hour_decimal)
    )


def _find_sidereal_solar_return_jd(target_year, birth_month, birth_day, natal_sun_longitude):
    target_date = _safe_target_date(target_year, birth_month, birth_day)
    center_jd = swe.julday(target_date.year, target_date.month, target_date.day, 12.0)
    start_jd = center_jd - 3.0
    end_jd = center_jd + 3.0

    def delta(jd):
        return _signed_longitude_delta(_sun_longitude_at_jd(jd), natal_sun_longitude)

    previous_jd = start_jd
    previous_delta = delta(previous_jd)
    bracket = None
    step = 0.25
    probe_jd = start_jd + step
    while probe_jd <= end_jd:
        current_delta = delta(probe_jd)
        if previous_delta == 0 or current_delta == 0 or previous_delta * current_delta <= 0:
            bracket = (previous_jd, probe_jd)
            break
        previous_jd = probe_jd
        previous_delta = current_delta
        probe_jd += step

    if bracket is None:
        samples = [
            (abs(delta(start_jd + index * step)), start_jd + index * step)
            for index in range(int((end_jd - start_jd) / step) + 1)
        ]
        return min(samples)[1]

    low, high = bracket
    for _ in range(48):
        mid = (low + high) / 2.0
        low_delta = delta(low)
        mid_delta = delta(mid)
        if low_delta == 0:
            return low
        if mid_delta == 0:
            return mid
        if low_delta * mid_delta <= 0:
            high = mid
        else:
            low = mid
    return (low + high) / 2.0


def _local_datetime_for_return(dt_utc, timezone_id, fallback_tz_offset):
    if timezone_id:
        zone = ZoneInfo(timezone_id)
        local_dt = dt_utc.astimezone(zone)
        offset = local_dt.utcoffset().total_seconds() / 3600.0
        return local_dt, offset

    local_dt = (dt_utc + timedelta(hours=fallback_tz_offset)).replace(tzinfo=None)
    return local_dt, fallback_tz_offset


def _rounded_chart_minute(local_dt):
    return (local_dt + timedelta(seconds=30)).replace(second=0, microsecond=0)


def _varsha_planet_rows(varsha_chart, natal_chart):
    natal_by_name = {
        _planet_name_en(planet): planet
        for planet in natal_chart["planets"]
    }
    rows = []
    for planet in varsha_chart["planets"]:
        name = _planet_name_en(planet)
        natal = natal_by_name.get(name)
        rows.append({
            "name": name,
            "abbr": planet["abbr"],
            "longitude": planet["longitude"],
            "sign": planet["sign_en"],
            "sign_tr": _sign_tr(planet["sign"]),
            "sign_index": planet["sign_index"],
            "degree": planet["degree"],
            "degree_str": planet["degree_str"],
            "house": planet["house"],
            "nakshatra": planet["nakshatra"],
            "motion": {
                "retrograde": planet["retrograde"],
                "speed": planet["speed"],
                "speed_status": "retrograde" if planet["retrograde"] else "normal",
            },
            "natal_house": natal.get("house") if natal else None,
            "natal_sign": natal.get("sign_en") if natal else None,
            "natal_degree_str": natal.get("degree_str") if natal else None,
        })
    return rows


def _varsha_houses(varsha_chart):
    planets_by_house = {house: [] for house in range(1, 13)}
    for planet in varsha_chart["planets"]:
        planets_by_house[planet["house"]].append(_planet_name_en(planet))

    lagna_sign_index = varsha_chart["lagna"]["sign_index"]
    return [
        {
            "house": house,
            "sign": SIGNS_EN[(lagna_sign_index + house - 1) % 12],
            "sign_tr": _sign_tr(SIGNS_TR[(lagna_sign_index + house - 1) % 12]),
            "sign_index": (lagna_sign_index + house - 1) % 12,
            "lord": SIGN_LORDS[(lagna_sign_index + house - 1) % 12],
            "planets": planets_by_house[house],
        }
        for house in range(1, 13)
    ]


def _planet_annual_strength_candidate(planet_name, varsha_planets):
    planet = next((item for item in varsha_planets if item["name"] == planet_name), None)
    if not planet:
        return {
            "planet": planet_name,
            "score": 0.0,
            "factors": ["planet_not_in_varsha_visible_set"],
        }

    score = 0.0
    factors = []
    if planet["house"] in {1, 4, 7, 10}:
        score += 4.0
        factors.append("kendra_house")
    if planet["house"] in {1, 5, 9}:
        score += 4.0
        factors.append("trikona_house")
    if planet["house"] in {3, 6, 10, 11}:
        score += 2.0
        factors.append("upachaya_house")
    if EXALTATION_SIGNS.get(planet_name) == planet["sign_index"]:
        score += 5.0
        factors.append("exalted")
    if SIGN_LORDS.get(planet["sign_index"]) == planet_name:
        score += 4.0
        factors.append("own_sign")
    if DEBILITATION_SIGNS.get(planet_name) == planet["sign_index"]:
        score -= 4.0
        factors.append("debilitated")
    if planet["motion"]["retrograde"]:
        score -= 1.0
        factors.append("retrograde")

    return {
        "planet": planet_name,
        "score": round(score, 2),
        "factors": factors,
        "house": planet["house"],
        "sign": planet["sign"],
        "sign_index": planet["sign_index"],
        "degree_str": planet["degree_str"],
    }


def _varsha_year_lord_candidates(varsha_chart, varsha_planets, return_local_dt, muntha):
    lagna_lord = SIGN_LORDS[varsha_chart["lagna"]["sign_index"]]
    sun = next(planet for planet in varsha_planets if planet["name"] == "Sun")
    moon = next(planet for planet in varsha_planets if planet["name"] == "Moon")
    candidate_roles = [
        ("weekday_lord", WEEKDAY_LORDS[return_local_dt.weekday()]),
        ("varsha_lagna_lord", lagna_lord),
        ("muntha_lord", muntha["lord"]),
        ("sun_sign_lord", SIGN_LORDS[sun["sign_index"]]),
        ("moon_sign_lord", SIGN_LORDS[moon["sign_index"]]),
    ]
    rows = []
    for role, planet_name in candidate_roles:
        strength = _planet_annual_strength_candidate(planet_name, varsha_planets)
        rows.append({
            "role": role,
            "planet": planet_name,
            "score": strength["score"],
            "strength_factors": strength["factors"],
            "annual_house": strength.get("house"),
            "annual_sign": strength.get("sign"),
            "annual_degree_str": strength.get("degree_str"),
        })

    ranked = sorted(rows, key=lambda item: (-item["score"], item["role"], item["planet"]))
    return {
        "method": "five_candidate_varshesha_scored_by_annual_house_and_basic_dignity",
        "source_rule": "Expose weekday lord, Varsha Lagna lord, Muntha lord, Sun sign lord, and Moon sign lord; select the highest technical strength score",
        "assumptions": [
            "selection_is_technical_variant_not_final_parampara_claim",
            "strength_uses_kendra_trikona_upachaya_and_basic_dignity",
            "combustion_and_full_panchadhikari_dispute_resolution_excluded",
        ],
        "excluded_rules": [
            "full_panchadhikari_varshesha_judgement",
            "tajika_aspectual_strength_in_year_lord_selection",
            "manual_astrologer_override",
        ],
        "candidates": rows,
        "selected": ranked[0] if ranked else None,
    }


