TAJIKA_STARTER_ASPECTS = [
    {"angle": 0.0, "label": "0_degree_contact"},
    {"angle": 60.0, "label": "60_degree_contact"},
    {"angle": 90.0, "label": "90_degree_contact"},
    {"angle": 120.0, "label": "120_degree_contact"},
    {"angle": 180.0, "label": "180_degree_contact"},
]
TAJIKA_STARTER_PLANETS = ["Sun", "Moon", "Mars", "Mercury", "Jupiter", "Venus", "Saturn"]
TAJIKA_STARTER_ORB_LIMIT = 6.0


def _longitude_point_payload(longitude, lagna_sign_index=None):
    longitude = longitude % 360.0
    sign_index = int(longitude // 30.0)
    degree = longitude % 30.0
    payload = {
        "longitude": round(longitude, 6),
        "sign": SIGNS_EN[sign_index],
        "sign_tr": _sign_tr(SIGNS_TR[sign_index]),
        "sign_index": sign_index,
        "degree": round(degree, 6),
        "degree_str": dms_str(degree),
    }
    if lagna_sign_index is not None:
        payload["house"] = _relative_house_from_sign(lagna_sign_index, sign_index)
    return payload


def _build_varshaphala_sahams(varsha_chart, varsha_planets):
    lagna_longitude = varsha_chart["lagna"]["longitude"] % 360.0
    lagna_sign_index = varsha_chart["lagna"]["sign_index"]
    planets_by_name = {
        planet["name"]: planet
        for planet in varsha_planets
    }
    points = []
    for formula in SAHAM_STARTER_FORMULAS:
        plus = planets_by_name.get(formula["plus"])
        minus = planets_by_name.get(formula["minus"])
        if not plus or not minus:
            points.append({
                "key": formula["key"],
                "label": formula["label"],
                "status": "not_available",
                "reason": "required_annual_planet_missing",
                "formula": formula["formula"],
                "meaning_limit": formula["meaning_limit"],
            })
            continue
        longitude = lagna_longitude + plus["longitude"] - minus["longitude"]
        points.append({
            "key": formula["key"],
            "label": formula["label"],
            "status": "starter_pending_reference_validation",
            "formula": formula["formula"],
            "inputs": {
                "lagna_longitude": round(lagna_longitude, 6),
                "plus_planet": formula["plus"],
                "plus_longitude": round(plus["longitude"], 6),
                "minus_planet": formula["minus"],
                "minus_longitude": round(minus["longitude"], 6),
            },
            "point": _longitude_point_payload(longitude, lagna_sign_index),
            "meaning_limit": formula["meaning_limit"],
            "score_status": "not_scored",
        })

    return {
        "status": "starter_pending_reference_validation",
        "score_status": "not_scored",
        "method": "selected_varshaphala_saham_points_lagna_plus_planet_minus_planet",
        "source_rule": "Starter Saham points expose selected annual lots as technical coordinates only; formula variants require external reference validation.",
        "assumptions": [
            "uses_annual_varsha_lagna_longitude",
            "uses_annual_planet_longitudes_from_existing_varshaphala_chart",
            "day_night_formula_variants_not_applied",
        ],
        "excluded_rules": [
            "full_saham_catalog",
            "day_night_reversal_variants",
            "tajika_aspect_judgement_to_saham",
            "interpretive_prediction_text",
            "rectification_score_use",
        ],
        "points": points,
        "summary": {
            "point_count": len(points),
            "scored": False,
            "rectification_score_used": False,
            "reference_validation": "pending",
        },
        "safety_notes": [
            "technical_coordinates_only",
            "do_not_present_as_yearly_prediction",
            "do_not_use_for_final_varshesha_or_rectification_decision",
        ],
    }


def _nearest_tajika_starter_aspect(angle):
    return min(
        TAJIKA_STARTER_ASPECTS,
        key=lambda aspect: abs(angle - aspect["angle"]),
    )


def _tajika_speed_context(planet_a, planet_b):
    speed_a = abs(((planet_a.get("motion") or {}).get("speed")) or 0.0)
    speed_b = abs(((planet_b.get("motion") or {}).get("speed")) or 0.0)
    if speed_a == speed_b:
        return "same_speed_context"
    faster = planet_a["name"] if speed_a > speed_b else planet_b["name"]
    slower = planet_b["name"] if speed_a > speed_b else planet_a["name"]
    return f"{faster}_faster_than_{slower}"


def _build_varshaphala_tajika_aspects(varsha_planets):
    annual_planets = [
        planet for planet in varsha_planets
        if planet.get("name") in TAJIKA_STARTER_PLANETS
    ]
    relationships = []
    for index, planet_a in enumerate(annual_planets):
        for planet_b in annual_planets[index + 1:]:
            angle = _angular_distance(planet_a["longitude"], planet_b["longitude"])
            nearest = _nearest_tajika_starter_aspect(angle)
            orb = abs(angle - nearest["angle"])
            relationships.append({
                "planet_a": planet_a["name"],
                "planet_b": planet_b["name"],
                "angle_degrees": round(angle, 6),
                "nearest_contact": nearest["label"],
                "nearest_contact_degrees": nearest["angle"],
                "orb_degrees": round(orb, 6),
                "status": (
                    "candidate_orb_within_starter_limit"
                    if orb <= TAJIKA_STARTER_ORB_LIMIT
                    else "nearest_angle_reference_only"
                ),
                "score_status": "not_scored",
                "speed_context": _tajika_speed_context(planet_a, planet_b),
                "interpretation_limit": "angular_contact_only_not_tajika_yoga_judgement",
            })

    relationships = sorted(
        relationships,
        key=lambda row: (
            row["orb_degrees"],
            row["planet_a"],
            row["planet_b"],
        ),
    )
    candidate_count = sum(
        1 for row in relationships
        if row["status"] == "candidate_orb_within_starter_limit"
    )
    return {
        "status": "starter_pending_reference_validation",
        "score_status": "not_scored",
        "method": "annual_planet_pair_nearest_angular_contact_candidates",
        "source_rule": "Starter Tajika aspect layer lists annual planet-pair angular contacts only; no Ithasala, Isarapha or yoga judgement is produced.",
        "orb_limit_degrees": TAJIKA_STARTER_ORB_LIMIT,
        "assumptions": [
            "uses_visible_annual_planets_only",
            "uses_nearest_0_60_90_120_180_degree_contact_family",
            "speed_context_is_reported_without_applying_or_separating_judgement",
        ],
        "excluded_rules": [
            "ithasala_isarapha_yoga_judgement",
            "tajika_friend_enemy_aspect_strength",
            "moon_application_rules",
            "saham_aspect_judgement",
            "interpretive_prediction_text",
            "rectification_score_use",
        ],
        "relationships": relationships,
        "summary": {
            "planet_count": len(annual_planets),
            "relationship_count": len(relationships),
            "candidate_orb_count": candidate_count,
            "scored": False,
            "rectification_score_used": False,
            "reference_validation": "pending",
        },
        "safety_notes": [
            "technical_angular_contacts_only",
            "do_not_present_as_tajika_yoga_result",
            "do_not_use_for_final_yearly_prediction",
        ],
    }


def _build_varshaphala_tajika_relationship_conditions(varsha_planets, tajika_aspects):
    planets_by_name = {
        planet["name"]: planet
        for planet in varsha_planets
    }
    conditions = []
    for relationship in tajika_aspects.get("relationships", []):
        planet_a = planets_by_name.get(relationship.get("planet_a"))
        planet_b = planets_by_name.get(relationship.get("planet_b"))
        if not planet_a or not planet_b:
            continue

        speed_a = ((planet_a.get("motion") or {}).get("speed")) or 0.0
        speed_b = ((planet_b.get("motion") or {}).get("speed")) or 0.0
        current_orb = float(relationship.get("orb_degrees") or 0.0)
        future_angle = _angular_distance(
            (planet_a["longitude"] + speed_a) % 360.0,
            (planet_b["longitude"] + speed_b) % 360.0,
        )
        future_orb = abs(
            future_angle - float(relationship.get("nearest_contact_degrees") or 0.0)
        )
        if future_orb < current_orb - 0.01:
            motion_status = "applying_candidate"
            relationship_status = "ithasala_condition_candidate"
        elif future_orb > current_orb + 0.01:
            motion_status = "separating_candidate"
            relationship_status = "isarapha_condition_candidate"
        else:
            motion_status = "stationary_or_unclear"
            relationship_status = "technical_reference_only"

        within_orb = relationship.get("status") == "candidate_orb_within_starter_limit"
        if not within_orb:
            relationship_status = "outside_starter_orb_reference_only"

        conditions.append({
            "planet_a": planet_a["name"],
            "planet_b": planet_b["name"],
            "nearest_contact": relationship.get("nearest_contact"),
            "orb_degrees": relationship.get("orb_degrees"),
            "future_orb_degrees": round(future_orb, 6),
            "motion_status": motion_status,
            "relationship_status": relationship_status,
            "within_starter_orb": within_orb,
            "faster_planet": (
                planet_a["name"]
                if abs(speed_a) >= abs(speed_b)
                else planet_b["name"]
            ),
            "slower_planet": (
                planet_b["name"]
                if abs(speed_a) >= abs(speed_b)
                else planet_a["name"]
            ),
            "score_status": "not_scored",
            "interpretation_limit": "starter_condition_only_not_final_ithasala_isarapha_judgement",
        })

    ithasala_count = sum(
        1 for row in conditions
        if row["relationship_status"] == "ithasala_condition_candidate"
    )
    isarapha_count = sum(
        1 for row in conditions
        if row["relationship_status"] == "isarapha_condition_candidate"
    )
    return {
        "status": "starter_pending_reference_validation",
        "score_status": "not_scored",
        "method": "one_day_speed_projection_application_separation_from_starter_tajika_aspects",
        "source_rule": "Starter relationship layer checks whether each starter Tajika angular contact is moving toward or away from exactness; it does not issue final Ithasala or Isarapha judgement.",
        "assumptions": [
            "uses_existing_annual_planet_daily_speeds",
            "uses_starter_tajika_aspects_as_input",
            "one_day_projection_is_a_technical_indicator_not_a_classical_final_rule",
        ],
        "excluded_rules": [
            "full_ithasala_isarapha_judgement",
            "deeptamsa_or_classical_orb_table_validation",
            "moon_translation_or_collection_rules",
            "tajika_yoga_result_text",
            "rectification_score_use",
        ],
        "conditions": conditions,
        "summary": {
            "condition_count": len(conditions),
            "ithasala_candidate_count": ithasala_count,
            "isarapha_candidate_count": isarapha_count,
            "scored": False,
            "rectification_score_used": False,
            "reference_validation": "pending",
        },
        "safety_notes": [
            "technical_condition_table_only",
            "do_not_present_as_final_tajika_yoga",
            "do_not_use_for_yearly_prediction",
        ],
    }


def _build_varshaphala_tajika_yoga_candidates(tajika_relationships):
    candidates = []
    for condition in tajika_relationships.get("conditions", []):
        relationship_status = condition.get("relationship_status")
        if relationship_status not in {
            "ithasala_condition_candidate",
            "isarapha_condition_candidate",
        }:
            continue

        yoga_family = (
            "ithasala"
            if relationship_status == "ithasala_condition_candidate"
            else "isarapha"
        )
        candidates.append({
            "candidate": f"{yoga_family}_starter_candidate",
            "status": "candidate_pending_reference_validation",
            "planet_a": condition.get("planet_a"),
            "planet_b": condition.get("planet_b"),
            "nearest_contact": condition.get("nearest_contact"),
            "orb_degrees": condition.get("orb_degrees"),
            "future_orb_degrees": condition.get("future_orb_degrees"),
            "motion_status": condition.get("motion_status"),
            "relationship_status": relationship_status,
            "score_status": "not_scored",
            "missing_for_final_judgement": [
                "deeptamsa_or_classical_orb_table_validation",
                "tajika_friend_enemy_aspect_strength",
                "moon_translation_or_collection_rules",
                "human_astrologer_review",
            ],
            "interpretation_limit": "candidate_inventory_only_not_final_tajika_yoga",
        })

    return {
        "status": "starter_candidate_inventory",
        "score_status": "not_scored",
        "method": "candidate_inventory_from_starter_ithasala_isarapha_conditions",
        "source_rule": "Lists possible Tajika yoga candidates from starter relationship conditions only; final Tajika yoga judgement remains unavailable.",
        "assumptions": [
            "uses_varshaphala_tajika_relationships_conditions",
            "only_candidate_relationship_statuses_are_listed",
            "candidate_rows_are_not_interpretive_results",
        ],
        "excluded_rules": [
            "full_tajika_yoga_set",
            "final_ithasala_isarapha_judgement",
            "deeptamsa_or_classical_orb_table_validation",
            "tajika_yoga_strength_or_result",
            "rectification_score_use",
        ],
        "candidates": candidates,
        "summary": {
            "candidate_count": len(candidates),
            "ithasala_candidate_count": sum(
                1 for row in candidates
                if row["candidate"] == "ithasala_starter_candidate"
            ),
            "isarapha_candidate_count": sum(
                1 for row in candidates
                if row["candidate"] == "isarapha_starter_candidate"
            ),
            "scored": False,
            "rectification_score_used": False,
            "reference_validation": "pending",
        },
        "safety_notes": [
            "candidate_inventory_only",
            "do_not_present_as_final_tajika_yoga",
            "do_not_use_for_prediction_or_rectification_score",
        ],
    }


def _build_varshaphala_tajika_orb_diagnostics(tajika_aspects):
    relationships = tajika_aspects.get("relationships", [])
    rows = []
    for aspect in TAJIKA_STARTER_ASPECTS:
        contact_rows = [
            row for row in relationships
            if row.get("nearest_contact") == aspect["label"]
        ]
        within_rows = [
            row for row in contact_rows
            if row.get("status") == "candidate_orb_within_starter_limit"
        ]
        tightest = min(
            contact_rows,
            key=lambda row: row.get("orb_degrees", 999.0),
            default=None,
        )
        rows.append({
            "contact_family": aspect["label"],
            "contact_degrees": aspect["angle"],
            "starter_orb_limit_degrees": TAJIKA_STARTER_ORB_LIMIT,
            "nearest_reference_count": len(contact_rows),
            "within_starter_orb_count": len(within_rows),
            "tightest_pair": (
                f"{tightest.get('planet_a')}-{tightest.get('planet_b')}"
                if tightest else None
            ),
            "tightest_orb_degrees": (
                tightest.get("orb_degrees") if tightest else None
            ),
            "diagnostic_status": "starter_limit_only_pending_deeptamsa_validation",
            "score_status": "not_scored",
            "interpretation_limit": "orb_policy_visibility_only_not_classical_deeptamsa_judgement",
        })

    return {
        "status": "starter_pending_reference_validation",
        "score_status": "not_scored",
        "method": "starter_orb_policy_visibility_for_tajika_contact_candidates",
        "source_rule": "Shows the provisional orb policy used by starter Tajika aspect candidates; classical Deeptamsa or planet-specific orb tables are not yet validated.",
        "orb_policy": {
            "starter_orb_limit_degrees": TAJIKA_STARTER_ORB_LIMIT,
            "contact_families_degrees": [
                aspect["angle"] for aspect in TAJIKA_STARTER_ASPECTS
            ],
            "classical_deeptamsa_status": "not_validated",
        },
        "assumptions": [
            "uses_same_starter_orb_limit_as_varshaphala_tajika_aspects",
            "counts_nearest_contact_family_rows_without_reclassifying_yogas",
            "does_not_apply_planet_specific_deeptamsa_orbs",
        ],
        "missing_for_final_judgement": [
            "deeptamsa_or_classical_orb_table_validation",
            "planet_specific_tajika_orb_table",
            "source_comparison_pending",
            "human_astrologer_review",
        ],
        "rows": rows,
        "summary": {
            "contact_family_count": len(rows),
            "relationship_count": len(relationships),
            "within_starter_orb_count": sum(
                row["within_starter_orb_count"] for row in rows
            ),
            "scored": False,
            "rectification_score_used": False,
            "reference_validation": "pending",
        },
        "safety_notes": [
            "diagnostic_orb_policy_only",
            "do_not_present_as_classical_deeptamsa_judgement",
            "do_not_use_for_prediction_or_rectification_score",
        ],
    }


