def _build_dhana_yogas(lordships):
    matches = []
    wealth_houses = ["2", "5", "9", "11"]
    checked_pairs = set()

    for source_key in wealth_houses:
        source = lordships.get(source_key)
        if not source:
            continue
        if source.get("lord_house") in {2, 5, 9, 11}:
            matches.append(_yoga_match(
                f"dhana_yoga_lord_{source_key}_placement",
                "Dhana Yoga",
                "starter_rule",
                "A 2nd/5th/9th/11th lord is placed in a wealth or trikona house.",
                "wealth",
                "supportive",
                "weak",
                "low",
                [f"lordships.{source_key}", "wealth_or_trikona_house"],
                supporting_factors=[
                    _yoga_factor(
                        "wealth_lord_in_wealth_or_trikona",
                        f"lordships.{source_key}",
                        {
                            "lord": source.get("lord"),
                            "source_house": int(source_key),
                            "lord_house": source.get("lord_house"),
                        },
                    ),
                ],
            ))

        for target_key in wealth_houses:
            if source_key >= target_key:
                continue
            pair_key = tuple(sorted([source_key, target_key]))
            if pair_key in checked_pairs:
                continue
            checked_pairs.add(pair_key)
            target = lordships.get(target_key)
            if not target:
                continue
            if source.get("lord_house") != target.get("lord_house"):
                continue

            matches.append(_yoga_match(
                f"dhana_yoga_lords_{source_key}_{target_key}_conjoin",
                "Dhana Yoga",
                "starter_rule",
                "Two 2nd/5th/9th/11th lords are placed in the same house.",
                "wealth",
                "supportive",
                "medium",
                "low",
                [f"lordships.{source_key}", f"lordships.{target_key}", "same_house"],
                supporting_factors=[
                    _yoga_factor(
                        "wealth_lords_same_house",
                        f"lordships.{source_key}+{target_key}",
                        {
                            "lords": [source.get("lord"), target.get("lord")],
                            "house": source.get("lord_house"),
                        },
                    ),
                ],
            ))

    return matches


def _build_rajayogas(lordships):
    matches = []
    kendra_houses = ["1", "4", "7", "10"]
    trikona_houses = ["1", "5", "9"]

    for kendra_key in kendra_houses:
        kendra = lordships.get(kendra_key)
        if not kendra:
            continue
        for trikona_key in trikona_houses:
            if kendra_key == trikona_key:
                continue
            trikona = lordships.get(trikona_key)
            if not trikona:
                continue
            same_lord = kendra.get("lord") == trikona.get("lord")
            same_house = kendra.get("lord_house") == trikona.get("lord_house")
            if not (same_lord or same_house):
                continue

            matches.append(_yoga_match(
                f"rajayoga_k{kendra_key}_t{trikona_key}",
                "Rajayoga",
                "starter_rule",
                "A kendra lord and trikona lord are connected by shared lordship or same-house placement.",
                "career",
                "supportive",
                "medium" if same_lord else "weak",
                "low",
                [f"lordships.{kendra_key}", f"lordships.{trikona_key}", "kendra_trikona_connection"],
                supporting_factors=[
                    _yoga_factor(
                        "kendra_trikona_connection",
                        f"lordships.{kendra_key}+{trikona_key}",
                        {
                            "kendra_house": int(kendra_key),
                            "trikona_house": int(trikona_key),
                            "same_lord": same_lord,
                            "same_house": same_house,
                            "lords": [kendra.get("lord"), trikona.get("lord")],
                            "houses": [kendra.get("lord_house"), trikona.get("lord_house")],
                        },
                    ),
                ],
            ))

    return matches


def _build_parivartana_yogas(planets):
    matches = []
    by_name = _planets_by_name(planets)
    classical_lords = set(SIGN_LORDS.values())
    seen_pairs = set()

    for planet in planets:
        planet_name = planet["name"]
        if planet_name not in classical_lords:
            continue
        dispositor_name = SIGN_LORDS.get(planet["sign_index"])
        dispositor = by_name.get(dispositor_name)
        if not dispositor or dispositor["name"] == planet_name:
            continue
        if SIGN_LORDS.get(dispositor["sign_index"]) != planet_name:
            continue

        pair_key = tuple(sorted([planet_name, dispositor["name"]]))
        if pair_key in seen_pairs:
            continue
        seen_pairs.add(pair_key)

        matches.append(_yoga_match(
            f"parivartana_{PLANET_IDS.get(pair_key[0], pair_key[0].lower())}_{PLANET_IDS.get(pair_key[1], pair_key[1].lower())}",
            "Parivartana Yoga",
            "starter_rule",
            "Two classical planets occupy each other's signs by sign lordship.",
            "general",
            "mixed",
            "medium",
            "medium",
            [planet_name, dispositor["name"], "mutual_sign_exchange"],
            supporting_factors=[
                _yoga_factor(
                    "mutual_sign_lord_exchange",
                    f"planets.{planet_name}+{dispositor['name']}",
                    {
                        "planet_a": planet_name,
                        "planet_a_sign": planet["sign"],
                        "planet_a_house": planet["house"],
                        "planet_b": dispositor["name"],
                        "planet_b_sign": dispositor["sign"],
                        "planet_b_house": dispositor["house"],
                    },
                ),
            ],
        ))

    return matches


