def _build_chandra_mangala_yogas(planets):
    by_name = _planets_by_name(planets)
    moon = by_name.get("Moon")
    mars = by_name.get("Mars")
    if not moon or not mars:
        return []

    relative_house = _relative_sign_house(moon["sign_index"], mars["sign_index"])
    if relative_house not in {1, 7}:
        return []

    relation = "same_sign" if relative_house == 1 else "opposition_by_sign"
    return [_yoga_match(
        "chandra_mangala",
        "Chandra-Mangala Yoga",
        "starter_rule",
        "Moon and Mars are connected by same sign or 7th-sign opposition.",
        "wealth",
        "supportive",
        "medium",
        "medium",
        ["Moon", "Mars", relation],
        supporting_factors=[
            _yoga_factor(
                "moon_mars_sign_connection",
                "planets.Moon+Mars",
                {
                    "relation": relation,
                    "relative_house_from_moon": relative_house,
                    "moon_sign": moon["sign"],
                    "mars_sign": mars["sign"],
                },
            ),
        ],
    )]


def _longitude_in_arc(longitude, start, end, tolerance=1e-7):
    arc = (end - start) % 360.0
    distance = (longitude - start) % 360.0
    return distance <= arc + tolerance


KALA_SARPA_SUBTYPES = {
    (1, 7): "Ananta",
    (2, 8): "Kulika",
    (3, 9): "Vasuki",
    (4, 10): "Shankhapala",
    (5, 11): "Padma",
    (6, 12): "Mahapadma",
    (7, 1): "Takshaka",
    (8, 2): "Karkotaka",
    (9, 3): "Shankhachuda",
    (10, 4): "Ghataka",
    (11, 5): "Vishadhara",
    (12, 6): "Shesha",
}


def _kala_sarpa_axis_subtype(rahu, ketu):
    return KALA_SARPA_SUBTYPES.get((rahu["house"], ketu["house"]), "unclassified_axis")


def _kala_sarpa_boundary_contacts(classical_planets, rahu, ketu, orb=3.0):
    contacts = []
    for planet in classical_planets:
        rahu_orb = _angular_distance(planet["longitude"], rahu["longitude"])
        ketu_orb = _angular_distance(planet["longitude"], ketu["longitude"])
        if rahu_orb <= orb:
            contacts.append({
                "planet": planet["name"],
                "node": "Rahu",
                "orb": round(rahu_orb, 4),
                "orb_limit": orb,
            })
        if ketu_orb <= orb:
            contacts.append({
                "planet": planet["name"],
                "node": "Ketu",
                "orb": round(ketu_orb, 4),
                "orb_limit": orb,
            })
    return contacts


def _build_kala_sarpa_dosha(planets):
    by_name = _planets_by_name(planets)
    rahu = by_name.get("Rahu (True)")
    ketu = by_name.get("Ketu")
    classical_planets = [
        planet for planet in planets
        if planet["name"] in ASHTAKAVARGA_PLANETS
    ]

    if not rahu or not ketu or len(classical_planets) != 7:
        return {
            "status": "not_assessed",
            "confidence": "none",
            "reason": "rahu_ketu_or_classical_planets_missing",
            "is_present": False,
        }

    rahu_to_ketu = [
        planet for planet in classical_planets
        if _longitude_in_arc(planet["longitude"], rahu["longitude"], ketu["longitude"])
    ]
    ketu_to_rahu = [
        planet for planet in classical_planets
        if _longitude_in_arc(planet["longitude"], ketu["longitude"], rahu["longitude"])
    ]

    if len(rahu_to_ketu) == 7:
        direction = "rahu_to_ketu"
        contained = rahu_to_ketu
    elif len(ketu_to_rahu) == 7:
        direction = "ketu_to_rahu"
        contained = ketu_to_rahu
    else:
        direction = None
        contained = []

    contained_names = {planet["name"] for planet in contained}
    outside = [
        planet["name"] for planet in classical_planets
        if planet["name"] not in contained_names
    ]
    containment_ratio = len(contained) / len(classical_planets)
    boundary_contacts = _kala_sarpa_boundary_contacts(classical_planets, rahu, ketu)
    cancellation_factors = []
    if outside:
        cancellation_factors.append({
            "rule": "classical_planets_outside_rahu_ketu_axis",
            "planets": outside,
            "effect": "cancels_full_kala_sarpa_condition",
        })
    if boundary_contacts:
        cancellation_factors.append({
            "rule": "planet_near_node_boundary",
            "contacts": boundary_contacts,
            "effect": "boundary_case_requires_parampara_review",
        })
    if direction is None:
        strength = "none"
    elif boundary_contacts:
        strength = "medium"
    else:
        strength = "strong"

    return {
        "status": "assessed",
        "confidence": "medium",
        "method": "all_7_classical_planets_between_rahu_ketu_axis_by_longitude",
        "source_rule": "Full Kala Sarpa requires all seven classical planets to fall inside one Rahu-Ketu semicircle",
        "assumptions": [
            "uses_true_node_rahu",
            "ketu_is_exact_opposition_from_rahu",
            "classical_7_planets_only_for_containment",
            "subtype_named_by_rahu_house_to_ketu_house_axis",
        ],
        "excluded_rules": [
            "lineage_specific_partial_kala_sarpa_definitions",
            "benefic_aspect_cancellations",
            "house_strength_weighting",
            "planetary_war_or_combustion_modifiers",
        ],
        "is_present": direction is not None,
        "direction": direction,
        "subtype": _kala_sarpa_axis_subtype(rahu, ketu) if direction else None,
        "strength": strength,
        "containment_ratio": round(containment_ratio, 4),
        "axis": {
            "rahu": {
                "longitude": rahu["longitude"],
                "sign": rahu["sign"],
                "house": rahu["house"],
            },
            "ketu": {
                "longitude": ketu["longitude"],
                "sign": ketu["sign"],
                "house": ketu["house"],
            },
        },
        "contained_planets": [planet["name"] for planet in contained],
        "planets_outside_axis": outside,
        "boundary_contacts": boundary_contacts,
        "cancellation_factors": cancellation_factors,
        "notes": [
            "Boundary and cancellation traditions vary by lineage.",
        ],
    }


def _relative_house_from_sign(source_sign_index, target_sign_index):
    return ((target_sign_index - source_sign_index) % 12) + 1


def _mangala_source_result(label, source_sign_index, mars):
    house = _relative_house_from_sign(source_sign_index, mars["sign_index"])
    trigger_houses = {1, 2, 4, 7, 8, 12}
    return {
        "source": label,
        "mars_house_from_source": house,
        "is_triggered": house in trigger_houses,
    }


def _mangala_cancellation_matrix(mars, checks):
    dignity = mars["dignity"]
    factors = []
    if dignity["swakshetra"]:
        factors.append({
            "rule": "mars_in_own_sign",
            "is_active": True,
            "effect": "strong_mitigation",
            "source": "dignity",
        })
    if dignity["uccha"]:
        factors.append({
            "rule": "mars_exalted",
            "is_active": True,
            "effect": "strong_mitigation",
            "source": "dignity",
        })
    if dignity["moolatrikona"]:
        factors.append({
            "rule": "mars_moolatrikona",
            "is_active": True,
            "effect": "moderate_mitigation",
            "source": "dignity",
        })
    if mars["sign_index"] in {0, 7}:
        factors.append({
            "rule": "mars_in_aries_or_scorpio",
            "is_active": True,
            "effect": "traditional_cancellation_variant",
            "source": "sign",
        })
    if mars["sign_index"] in {9, 3}:
        factors.append({
            "rule": "mars_in_capricorn_or_cancer",
            "is_active": True,
            "effect": "exaltation_debilitation_axis_variant_requires_review",
            "source": "sign",
        })

    triggered_sources = {check["source"] for check in checks if check["is_triggered"]}
    if triggered_sources == {"lagna", "moon", "venus"}:
        factors.append({
            "rule": "all_three_reference_sources_triggered",
            "is_active": True,
            "effect": "reinforces_condition",
            "source": "source_count",
        })

    return factors


def _mangala_net_severity(severity, cancellation_factors):
    severity_rank = {"none": 0, "low": 1, "medium": 2, "high": 3}
    rank_severity = {value: key for key, value in severity_rank.items()}
    rank = severity_rank[severity]
    for factor in cancellation_factors:
        if factor["effect"] == "strong_mitigation":
            rank -= 2
        elif factor["effect"] in {"moderate_mitigation", "traditional_cancellation_variant"}:
            rank -= 1
        elif factor["effect"] == "reinforces_condition":
            rank += 1
    return rank_severity[max(0, min(3, rank))]


def _build_mangala_dosha(planets):
    by_name = _planets_by_name(planets)
    mars = by_name.get("Mars")
    moon = by_name.get("Moon")
    venus = by_name.get("Venus")

    if not mars or not moon or not venus:
        return {
            "status": "not_assessed",
            "confidence": "none",
            "reason": "mars_moon_or_venus_missing",
            "is_present": False,
        }

    lagna_sign_index = (mars["sign_index"] - mars["house"] + 1) % 12
    checks = [
        _mangala_source_result("lagna", lagna_sign_index, mars),
        _mangala_source_result("moon", moon["sign_index"], mars),
        _mangala_source_result("venus", venus["sign_index"], mars),
    ]
    triggered = [check for check in checks if check["is_triggered"]]
    dignity = mars["dignity"]
    mitigation_factors = []
    if dignity["swakshetra"]:
        mitigation_factors.append("mars_in_own_sign")
    if dignity["uccha"]:
        mitigation_factors.append("mars_exalted")
    if dignity["moolatrikona"]:
        mitigation_factors.append("mars_moolatrikona")
    cancellation_factors = _mangala_cancellation_matrix(mars, checks)

    if not triggered:
        severity = "none"
    elif checks[0]["is_triggered"] and len(triggered) >= 2:
        severity = "high"
    elif checks[0]["is_triggered"] or len(triggered) >= 2:
        severity = "medium"
    else:
        severity = "low"
    net_severity = _mangala_net_severity(severity, cancellation_factors)

    return {
        "status": "assessed",
        "confidence": "medium",
        "method": "mars_in_1_2_4_7_8_12_from_lagna_moon_and_venus",
        "source_rule": "Mangala Dosha is triggered when Mars occupies 1,2,4,7,8,12 from Lagna, Moon, or Venus",
        "assumptions": [
            "three_reference_sources_lagna_moon_venus",
            "whole_sign_house_counting",
            "cancellation_matrix_is_explicit_and_variant_aware",
        ],
        "excluded_rules": [
            "regional_house_trigger_variants_excluding_1st_or_2nd",
            "matching_partner_chart_cancellation",
            "navamsha_based_secondary_mangala",
            "benefic_aspect_cancellation_not_applied",
        ],
        "is_present": bool(triggered),
        "severity": severity,
        "net_severity": net_severity,
        "checks": checks,
        "triggered_sources": [check["source"] for check in triggered],
        "mars": {
            "sign": mars["sign"],
            "sign_index": mars["sign_index"],
            "house": mars["house"],
            "degree_str": mars["degree_str"],
            "dignity": dignity,
        },
        "mitigation_factors": mitigation_factors,
        "cancellation_factors": cancellation_factors,
        "notes": [
            "Regional cancellation rules need a separate explicit layer.",
        ],
    }


def _build_doshas(planets):
    return {
        "kala_sarpa": _build_kala_sarpa_dosha(planets),
        "mangala": _build_mangala_dosha(planets),
    }


def _build_yogas(planets, lordships):
    matches = []
    matches.extend(_build_gaja_kesari_yogas(planets))
    matches.extend(_build_kemadruma_yogas(planets))
    matches.extend(_build_pancha_mahapurusha_yogas(planets))
    matches.extend(_build_neecha_bhanga_yogas(planets))
    matches.extend(_build_viparita_rajayogas(lordships))
    matches.extend(_build_dhana_yogas(lordships))
    matches.extend(_build_rajayogas(lordships))
    matches.extend(_build_parivartana_yogas(planets))
    matches.extend(_build_budha_aditya_yogas(planets))
    matches.extend(_build_chandra_mangala_yogas(planets))

    return {
        "matches": matches,
        "missing_checks": [],
    }


def _topic_factor(code, source, detail):
    return {
        "code": code,
        "source": source,
        "detail": detail,
    }


def _topic_missing_keys(missing):
    return {item["key"] for item in missing}


def _topic_required_but_missing(config, evidence, missing):
    missing_keys = _topic_missing_keys(missing)
    required = []

    if not evidence["houses"]:
        required.append("houses")
    if not evidence["lordships"]:
        required.append("lordships")
    if not evidence["planets"]:
        required.append("planets")
    for division in config["vargas"]:
        if division not in evidence["vargas"]:
            required.append(f"vargas.{division}")

    return sorted(set(required + [
        key for key in missing_keys
        if key in {"houses", "lordships"} or key.startswith("vargas.")
    ]))


def _topic_supporting_factors(evidence):
    factors = []

    for house in evidence["houses"]:
        if house["occupants"]:
            factors.append(_topic_factor(
                "house_occupied",
                f"houses.{house['house']}",
                {"occupants": house["occupants"]},
            ))
        if house["aspected_by"]:
            factors.append(_topic_factor(
                "house_aspected",
                f"houses.{house['house']}",
                {"aspected_by": house["aspected_by"]},
            ))

    for house_key, lordship in evidence["lordships"].items():
        condition = lordship.get("condition", {})
        if condition.get("swakshetra"):
            factors.append(_topic_factor(
                "lord_own_sign",
                f"lordships.{house_key}",
                {"lord": lordship.get("lord"), "sign": lordship.get("lord_sign")},
            ))
        if condition.get("uccha"):
            factors.append(_topic_factor(
                "lord_exalted",
                f"lordships.{house_key}",
                {"lord": lordship.get("lord"), "sign": lordship.get("lord_sign")},
            ))
        if condition.get("moolatrikona"):
            factors.append(_topic_factor(
                "lord_moolatrikona",
                f"lordships.{house_key}",
                {"lord": lordship.get("lord"), "sign": lordship.get("lord_sign")},
            ))

    for planet in evidence["planets"]:
        dignity = planet.get("dignity", {})
        if dignity.get("essential") in {"exalted", "own_sign", "moolatrikona", "friendly"}:
            factors.append(_topic_factor(
                "planet_supportive_dignity",
                f"planets.{planet['name']}",
                {"essential": dignity.get("essential"), "house": planet.get("house")},
            ))

    active_path = evidence["active_dasha"].get("path") or []
    planet_names = {planet["name"] for planet in evidence["planets"]}
    active_relevant = [lord for lord in active_path if lord in planet_names]
    if active_relevant:
        factors.append(_topic_factor(
            "active_dasha_relevant",
            "dashas.vimshottari.active.path",
            {"lords": active_relevant},
        ))

    return factors


def _topic_challenging_factors(evidence):
    factors = []

    for house_key, lordship in evidence["lordships"].items():
        condition = lordship.get("condition", {})
        if condition.get("neecha"):
            factors.append(_topic_factor(
                "lord_debilitated",
                f"lordships.{house_key}",
                {"lord": lordship.get("lord"), "sign": lordship.get("lord_sign")},
            ))
        if condition.get("combust"):
            factors.append(_topic_factor(
                "lord_combust",
                f"lordships.{house_key}",
                {"lord": lordship.get("lord")},
            ))

    for planet in evidence["planets"]:
        dignity = planet.get("dignity", {})
        combustion = planet.get("combustion", {})
        war = planet.get("war", {})
        if dignity.get("neecha") or dignity.get("essential") == "debilitated":
            factors.append(_topic_factor(
                "planet_debilitated",
                f"planets.{planet['name']}",
                {"house": planet.get("house"), "sign": planet.get("sign")},
            ))
        if combustion.get("is_combust"):
            factors.append(_topic_factor(
                "planet_combust",
                f"planets.{planet['name']}",
                {"severity": combustion.get("severity")},
            ))
        if war.get("in_graha_yuddha"):
            factors.append(_topic_factor(
                "planet_graha_yuddha",
                f"planets.{planet['name']}",
                {"opponent": war.get("opponent"), "orb": war.get("orb")},
            ))

    return factors


def _topic_mixed_factors(evidence):
    factors = []

    for planet in evidence["planets"]:
        dignity = planet.get("dignity", {})
        combustion = planet.get("combustion", {})
        if (
            dignity.get("essential") in {"exalted", "own_sign", "moolatrikona", "friendly"}
            and combustion.get("is_combust")
        ):
            factors.append(_topic_factor(
                "supportive_dignity_with_combustion",
                f"planets.{planet['name']}",
                {
                    "essential": dignity.get("essential"),
                    "combustion": combustion.get("severity"),
                },
            ))

    for house in evidence["houses"]:
        if house["occupants"] and house["aspected_by"]:
            factors.append(_topic_factor(
                "occupied_and_aspected_house",
                f"houses.{house['house']}",
                {
                    "occupants": house["occupants"],
                    "aspected_by": house["aspected_by"],
                },
            ))

    return factors


def _topic_missing_factors(config, evidence, missing):
    missing_keys = _topic_missing_keys(missing)
    factors = []

    if "aspects.rashi_drishti" in missing_keys:
        factors.append(_topic_factor(
            "rashi_drishti_unavailable",
            "missing.aspects.rashi_drishti",
            {"impact": "sign-based aspect evidence absent"},
        ))
    if "yogas" in missing_keys:
        factors.append(_topic_factor(
            "classic_yogas_unavailable",
            "missing.yogas",
            {"impact": "classic yoga matching absent"},
        ))
    for division in config["vargas"]:
        if division not in evidence["vargas"]:
            factors.append(_topic_factor(
                "required_varga_unavailable",
                f"vargas.{division}",
                {"division": division},
            ))

    return factors


def _topic_yoga_refs(yogas, topic):
    refs = []
    for match in yogas.get("matches", []):
        if match.get("topic") not in {topic, "general"}:
            continue
        refs.append({
            "id": match["id"],
            "name": match["name"],
            "topic": match["topic"],
            "effect_type": match["effect_type"],
            "strength": match["strength"],
            "confidence": match["confidence"],
        })
    return refs


def _topic_promise_level(supporting, challenging, mixed, required_but_missing):
    if required_but_missing:
        return "insufficient_data"
    if supporting and challenging:
        return "mixed"
    if supporting:
        return "supported_by_evidence"
    if challenging:
        return "challenged_by_evidence"
    if mixed:
        return "mixed"
    return "not_assessed"


def _topic_confidence(evidence, required_but_missing):
    if required_but_missing:
        return "low"
    if evidence["houses"] and evidence["lordships"] and evidence["planets"] and evidence["vargas"]:
        return "medium"
    return "low"


def _build_topic_packets(planets, houses, lordships, vargas, dashas, yogas, missing):
    packets = {}
    for key, config in TOPIC_PACKET_CONFIG.items():
        evidence = {
            "houses": _topic_house_evidence(houses, config["houses"]),
            "lordships": _topic_lordship_evidence(lordships, config["lordships"]),
            "planets": _topic_planet_evidence(planets, config["planets"]),
            "vargas": _topic_varga_evidence(vargas, config["vargas"]),
            "active_dasha": _topic_active_dasha_evidence(dashas),
            "yogas": _topic_yoga_refs(yogas, key),
            "missing": missing,
        }
        supporting = _topic_supporting_factors(evidence)
        challenging = _topic_challenging_factors(evidence)
        mixed = _topic_mixed_factors(evidence)
        missing_factors = _topic_missing_factors(config, evidence, missing)
        required_but_missing = _topic_required_but_missing(config, evidence, missing)
        packets[key] = {
            "topic": key,
            "promise_level": _topic_promise_level(
                supporting,
                challenging,
                mixed,
                required_but_missing,
            ),
            "supporting_factors": supporting,
            "challenging_factors": challenging,
            "mixed_factors": mixed,
            "missing_factors": missing_factors,
            "required_but_missing": required_but_missing,
            "confidence": _topic_confidence(evidence, required_but_missing),
            "evidence": evidence,
        }
    return packets


def _analysis_layer_available(layer_name, layers):
    value = layers.get(layer_name)
    if value is None:
        return False
    if isinstance(value, dict):
        status = value.get("status")
        if status in {"not_available", "not_implemented", "missing"}:
            return False
        return bool(value)
    return bool(value)


def _analysis_available_data(config, vargas, layers):
    available = []
    for division in config.get("required_vargas", []) + config.get("supporting_vargas", []):
        if division in vargas and division not in available:
            available.append(division)
    for layer_name in config.get("helper_layers", []):
        if _analysis_layer_available(layer_name, layers):
            available.append(layer_name)
    if config.get("houses") and _analysis_layer_available("houses", layers):
        available.append("houses")
    if config.get("lordships") and _analysis_layer_available("lordships", layers):
        available.append("lordships")
    if config.get("planets") and _analysis_layer_available("planets", layers):
        available.append("planets")
    return list(dict.fromkeys(available))


def _analysis_missing_data(config, vargas, layers):
    missing = []
    for division in config.get("required_vargas", []) + config.get("supporting_vargas", []):
        if division not in vargas:
            missing.append(f"vargas.{division}")
    for layer_name in config.get("helper_layers", []):
        if not _analysis_layer_available(layer_name, layers):
            missing.append(layer_name)
    if config.get("requires_context"):
        missing.extend(config.get("context_requirements", []))
    missing.extend(config.get("explicit_missing", []))
    return list(dict.fromkeys(missing))


def _analysis_evidence_refs(config, vargas, layers):
    refs = []
    if _analysis_layer_available("houses", layers):
        refs.extend(f"houses.{house}" for house in config.get("houses", []))
    if _analysis_layer_available("lordships", layers):
        refs.extend(f"lordships.{house}" for house in config.get("lordships", []))
    if _analysis_layer_available("planets", layers):
        refs.extend(
            f"planets.{planet_name}"
            for planet_name in config.get("planets", [])
        )
    refs.extend(
        f"vargas.{division}"
        for division in config.get("required_vargas", []) + config.get("supporting_vargas", [])
        if division in vargas
    )
    refs.extend(
        layer_name
        for layer_name in config.get("helper_layers", [])
        if _analysis_layer_available(layer_name, layers)
    )
    return list(dict.fromkeys(refs))


def _analysis_limited_quality_reasons(config, vargas):
    reasons = []
    for division in config.get("required_vargas", []) + config.get("supporting_vargas", []):
        varga = vargas.get(division) or {}
        confidence = varga.get("confidence")
        if confidence in {"low", "very_low"}:
            reasons.append(f"vargas.{division}.confidence_{confidence}")
    return list(dict.fromkeys(reasons))


def _analysis_status(config, missing_data, vargas):
    if config.get("requires_context"):
        return "requires_context"
    if missing_data:
        return "partial"
    if _analysis_limited_quality_reasons(config, vargas):
        return "limited"
    return "ready"


def _analysis_varga_confidence(config, vargas, confidence):
    required = config.get("required_vargas", [])
    supporting = config.get("supporting_vargas", [])
    for division in required:
        if (vargas.get(division) or {}).get("confidence") in {"low", "very_low"}:
            return "low"
    for division in supporting:
        if (vargas.get(division) or {}).get("confidence") == "very_low":
            return "low"
    for division in supporting:
        if (vargas.get(division) or {}).get("confidence") == "low":
            return "medium" if confidence == "high" else confidence
    return confidence


def _analysis_confidence(config, vargas, status, missing_data):
    if status == "requires_context":
        return "none"
    required_missing = {
        f"vargas.{division}"
        for division in config.get("required_vargas", [])
        if division not in vargas
    }
    if required_missing:
        return "low"
    if missing_data:
        return _analysis_varga_confidence(config, vargas, "medium")
    return _analysis_varga_confidence(config, vargas, "high")


def _analysis_reason(config, status, missing_data):
    if status == "requires_context":
        return "Bu modül natal haritadan tek başına hesaplanmaz; ayrı soru/olay zamanı ve yer bağlamı gerekir."
    if status == "limited":
        return "Teknik veri mevcut; ancak bazı zorunlu veya destek vargalar düşük güvenli olduğu için sınırlı kanıt olarak kullanılmalıdır."
    if missing_data:
        return "Bazı klasik veri katmanları henüz hesap motorunda güvenli şekilde üretilmediği için paket kısmi döner."
    return "Gerekli teknik veri katmanları mevcut; paket yine yorum değil kanıt listesi döndürür."


def _build_analysis_module_packet(key, config, vargas, layers):
    missing_data = _analysis_missing_data(config, vargas, layers)
    status = _analysis_status(config, missing_data, vargas)
    safety_notes = list(config.get("safety_notes", ["technical_evidence_only"]))
    if status == "limited":
        safety_notes.append("limited_by_low_confidence_varga")
    return {
        "module": key,
        "label": config["label"],
        "status": status,
        "confidence": _analysis_confidence(config, vargas, status, missing_data),
        "reason": _analysis_reason(config, status, missing_data),
        "available_data": _analysis_available_data(config, vargas, layers),
        "missing_data": missing_data,
        "evidence_refs": _analysis_evidence_refs(config, vargas, layers),
        "required_vargas": config.get("required_vargas", []),
        "supporting_vargas": config.get("supporting_vargas", []),
        "safety_notes": list(dict.fromkeys(safety_notes)),
    }


def _build_analysis_modules(vargas, layers):
    return {
        key: _build_analysis_module_packet(
            key,
            ANALYSIS_MODULE_CONFIG[key],
            vargas,
            layers,
        )
        for key in ANALYSIS_MODULE_CONFIG
    }


