def _decision_score(status, confidence):
    if status in {"not_implemented", "requires_context", "not_available"}:
        return 0
    if status == "ready":
        return {"high": 85, "medium": 72, "low": 58}.get(confidence, 60)
    if status == "limited":
        return {"high": 60, "medium": 52, "low": 42}.get(confidence, 40)
    if status == "partial":
        return {"high": 50, "medium": 42, "low": 32}.get(confidence, 35)
    return 0


def _decision_from_analysis_module(module):
    status = module.get("status", "not_available")
    confidence = module.get("confidence", "none")
    warnings = []
    if status == "requires_context":
        warnings.append("requires_separate_context_before_decision")
    if status == "limited":
        warnings.append("limited_by_low_confidence_or_pending_validation")
    if status == "partial":
        warnings.append("incomplete_technical_basis")
    return {
        "status": status,
        "score": _decision_score(status, confidence),
        "confidence": confidence,
        "decision": "technical_only",
        "reasons": [module.get("reason")] if module.get("reason") else [],
        "warnings": warnings,
        "missing_data": module.get("missing_data", []),
        "evidence_refs": module.get("evidence_refs", []),
        "safety_notes": list(dict.fromkeys([
            *module.get("safety_notes", []),
            "no_prediction_generated",
        ])),
    }


def _decision_panchanga_tithi(panchanga):
    tithi = panchanga.get("tithi") or {}
    paksha = panchanga.get("paksha") or {}
    rule = TITHI_DECISION_RULES.get(tithi.get("name"), {})
    if not tithi:
        return {
            "status": "not_available",
            "score": 0,
            "confidence": "none",
            "decision": "technical_only",
            "reasons": ["panchanga.tithi missing"],
            "warnings": ["do_not_infer_tithi"],
            "missing_data": ["panchanga.tithi"],
            "evidence_refs": [],
            "safety_notes": ["technical_evidence_only", "no_prediction_generated"],
        }
    warnings = []
    if rule.get("warning"):
        warnings.append(rule["warning"])
    return {
        "status": "ready",
        "score": 70 if not warnings else 55,
        "confidence": "medium",
        "decision": "technical_only",
        "reasons": [
            f"tithi.{tithi.get('name')}",
            f"paksha.{paksha.get('name')}",
            "generic_tithi_quality_only",
        ],
        "warnings": warnings,
        "missing_data": [],
        "evidence_refs": [
            "panchanga.tithi",
            "panchanga.paksha",
            "panchanga.yoga",
            "panchanga.karana",
            "panchanga.moon_nakshatra",
        ],
        "technical_packet": {
            "tithi_name": tithi.get("name"),
            "tithi_number": tithi.get("number"),
            "paksha": paksha.get("name"),
            "paksha_phase": paksha.get("phase"),
            "classification": rule.get("classification", "unclassified"),
            "general_quality": rule.get("general_quality", "review_required"),
            "elapsed_degrees": tithi.get("elapsed_degrees"),
            "remaining_degrees": tithi.get("remaining_degrees"),
        },
        "safety_notes": [
            "technical_evidence_only",
            "generic_panchanga_meaning_not_event_specific_muhurta",
            "no_prediction_generated",
        ],
    }


def _decision_not_implemented(key, missing_key):
    return {
        "status": "not_implemented",
        "score": 0,
        "confidence": "none",
        "decision": "technical_only",
        "reasons": [f"{missing_key} is not calculated by the current engine"],
        "warnings": ["do_not_infer_missing_dasha"],
        "missing_data": [missing_key],
        "evidence_refs": [],
        "safety_notes": [
            "technical_evidence_only",
            "no_prediction_generated",
            f"{key}_requires_dedicated_rules_before_use",
        ],
    }


def _decision_chara_dasha(chara):
    if not chara or not chara.get("maha"):
        return _decision_not_implemented("chara_dasha", "dashas.chara")

    active = chara.get("current_active") or chara.get("active") or {}
    return {
        "status": "limited",
        "score": 45,
        "confidence": chara.get("confidence", "low"),
        "decision": "technical_only",
        "reasons": [
            "dashas.chara.maha and dashas.chara.antara are calculated as a starter technical table",
            "Chara parampara-specific variants are not implemented in v1",
        ],
        "warnings": [
            "starter_chara_rule_review_required_before_strong_interpretation",
            "do_not_use_chara_antara_as_final_prediction",
            "do_not_generate_predictions_from_single_dasha",
        ],
        "missing_data": ["dashas.chara.parampara_specific_variants"],
        "evidence_refs": [
            "dashas.chara.maha",
            "dashas.chara.current_active.maha",
            "dashas.chara.antara",
            "dashas.chara.current_active.antara",
        ],
        "technical_packet": {
            "method": chara.get("method"),
            "source_rule": chara.get("source_rule"),
            "active_path": active.get("path", []),
        },
        "safety_notes": [
            "technical_evidence_only",
            "no_prediction_generated",
            "chara_dasha_v1_is_starter_maha_and_antara_only",
        ],
    }


