def _parse_hhmm(value, field_name):
    try:
        parts = str(value).split(":")
        if len(parts) not in {2, 3}:
            raise ValueError
        hour_text, minute_text = parts[:2]
        second_text = parts[2] if len(parts) == 3 else "0"
        hour = int(hour_text)
        minute = int(minute_text)
        second = int(second_text)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field_name} HH:MM veya HH:MM:SS formatında olmalı") from exc

    if not (0 <= hour <= 23 and 0 <= minute <= 59 and 0 <= second <= 59):
        raise ValueError(f"{field_name} geçersiz saat içeriyor")
    return hour, minute


def _minutes_from_hhmm(value, field_name):
    hour, minute = _parse_hhmm(value, field_name)
    return hour * 60 + minute


def _seconds_from_hhmm(value, field_name):
    try:
        parts = str(value).split(":")
        if len(parts) not in {2, 3}:
            raise ValueError
        hour_text, minute_text = parts[:2]
        second_text = parts[2] if len(parts) == 3 else "0"
        hour = int(hour_text)
        minute = int(minute_text)
        second = int(second_text)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field_name} HH:MM veya HH:MM:SS formatında olmalı") from exc

    if not (0 <= hour <= 23 and 0 <= minute <= 59 and 0 <= second <= 59):
        raise ValueError(f"{field_name} geçersiz saat içeriyor")
    return hour * 3600 + minute * 60 + second


def _parse_event_components(event):
    date_text = str(event.get("date") or "").strip()
    if not date_text:
        raise ValueError("event.date boş olamaz")
    try:
        year_text, month_text, day_text = date_text.split("-", 2)
        year = int(year_text)
        month = int(month_text)
        day = int(day_text)
        hour, minute = _parse_hhmm(event.get("time") or "12:00", "event.time")
        _validate_birth_fields(year, month, day, hour, minute, 0.0, 0.0)
    except ValueError as exc:
        raise ValueError("event.date YYYY-MM-DD, event.time HH:MM formatında olmalı") from exc

    return year, month, day, hour, minute


def _parse_event_jd(event, tz_offset):
    year, month, day, hour, minute = _parse_event_components(event)
    return date_to_jd(year, month, day, hour, minute, tz_offset)


def _parse_event_datetime_utc(event, tz_offset):
    year, month, day, hour, minute = _parse_event_components(event)
    local_dt = datetime(year, month, day, hour, minute)
    return (local_dt - timedelta(hours=tz_offset)).replace(tzinfo=timezone.utc)


def _parse_rectification_date(value, field_name):
    text = str(value or "").strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    raise ValueError(f"{field_name} YYYY-MM-DD veya GG.AA.YYYY formatında olmalı")


def _rectification_time_confidence(value):
    key = str(value or "unknown").strip().lower()
    aliases = {
        "known": "high",
        "bilinen": "high",
        "biliniyor": "high",
        "kesin": "high",
        "exact": "high",
        "high": "high",
        "rectified": "rectified",
        "rektifiye": "rectified",
        "rektifiye edilmiş": "rectified",
        "rektifiye edilmis": "rectified",
        "approx": "medium",
        "yaklaşık": "medium",
        "yaklasik": "medium",
        "medium": "medium",
        "low": "low",
        "düşük": "low",
        "dusuk": "low",
        "unknown": "unknown",
        "bilinmiyor": "unknown",
    }
    return aliases.get(key, key or "unknown")


def _rectification_bool(value, default=False):
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in {"1", "true", "yes", "evet", "var", "documented"}


def _normalize_rectification_source_quality(value):
    key = str(value or "").strip().lower()
    aliases = {
        "official": "gold",
        "resmi": "gold",
        "hospital": "gold",
        "hastane": "gold",
        "birth_certificate": "gold",
        "high": "silver",
        "yüksek": "silver",
        "yuksek": "silver",
        "family": "weak",
        "aile": "weak",
        "memory": "weak",
        "low": "weak",
        "düşük": "weak",
        "dusuk": "weak",
    }
    key = aliases.get(key, key)
    return key if key in {"gold", "silver", "weak", "unknown"} else "unknown"


def _normalize_rectification_source_doc(doc, index):
    doc_type = str(doc.get("type") or doc.get("source_type") or f"source_{index + 1}").strip().lower()
    normalized = {
        "type": doc_type,
        "exists": _rectification_bool(doc.get("exists"), default=True),
        "quality": _normalize_rectification_source_quality(doc.get("quality") or doc.get("source_quality")),
    }
    if doc.get("uncertainty_min") not in {None, ""}:
        normalized["uncertainty_min"] = int(doc.get("uncertainty_min"))
    if doc.get("documented") is not None:
        normalized["documented"] = _rectification_bool(doc.get("documented"))
    if doc.get("note"):
        normalized["note"] = str(doc.get("note")).strip()
    return normalized


def _normalize_rectification_source_docs(value):
    docs = value or []
    if isinstance(docs, dict):
        docs = [docs]
    return [
        _normalize_rectification_source_doc(doc, index)
        for index, doc in enumerate(docs)
        if isinstance(doc, dict)
    ]


def _derive_rectification_source_quality(source_docs, time_confidence):
    existing_docs = [doc for doc in source_docs if doc.get("exists")]
    if any(doc.get("quality") == "gold" for doc in existing_docs):
        return "gold"
    if len(existing_docs) >= 2 or _rectification_time_confidence(time_confidence) in {"high", "rectified"}:
        return "silver"
    if existing_docs:
        return "weak"
    return "unknown"


def _normalize_rectification_event_type(value):
    key = str(value or "").strip().lower()
    aliases = {
        "kariyer": "career",
        "iş": "career",
        "is": "career",
        "aile": "family",
        "ev": "family",
        "ebeveyn": "family",
        "anne": "family",
        "baba": "family",
        "evlilik": "marriage",
        "ilişki": "marriage",
        "iliski": "marriage",
        "boşanma": "divorce",
        "bosanma": "divorce",
        "çocuk": "childbirth",
        "cocuk": "childbirth",
        "taşınma": "relocation",
        "tasinma": "relocation",
        "sağlık": "health",
        "saglik": "health",
        "hukuk": "legal",
        "mahkeme": "legal",
        "gözaltı": "legal",
        "gozalti": "legal",
        "cezaevi": "legal",
        "beraat": "legal",
    }
    key = aliases.get(key, key)
    return _rectification_event_rule_key(key) or _rectification_event_topic(key) or key


def _rectification_event_date_value(event):
    if event.get("date"):
        return event.get("date")
    for key in ("time_start_local", "start_local", "time_end_local", "end_local"):
        value = str(event.get(key) or "").strip()
        if value:
            return value[:10]
    return None


def _normalize_rectification_event(event, index, default_timezone_id=None):
    date_value = _rectification_event_date_value(event)
    event_date = _parse_rectification_date(date_value, f"events[{index}].date")
    event_type = _normalize_rectification_event_type(event.get("type") or event.get("event_type") or event.get("topic"))
    if not event_type:
        raise ValueError(f"events[{index}].type boş olamaz")

    event_time = str(event.get("time") or "").strip()
    if event_time:
        _minutes_from_hhmm(event_time, f"events[{index}].time")
    start_local = event.get("time_start_local") or event.get("start_local")
    end_local = event.get("time_end_local") or event.get("end_local")
    if not start_local:
        start_local = f"{event_date.isoformat()}T{event_time or '00:00'}"
    if not end_local:
        end_local = f"{event_date.isoformat()}T{event_time or '23:59'}"

    normalized = {
        "date": event_date.isoformat(),
        "type": event_type,
        "event_type": event_type,
        "label": event.get("label") or event.get("title") or event.get("type") or event_type,
        "confidence": str(event.get("confidence") or "medium").strip().lower(),
        "certainty": str(event.get("certainty") or event.get("date_certainty") or "day_exact").strip().lower(),
        "time_start_local": str(start_local),
        "time_end_local": str(end_local),
        "timezone_id": event.get("timezone_id") or default_timezone_id,
        "documented": _rectification_bool(event.get("documented"), default=False),
        "source_type": str(event.get("source_type") or "unspecified").strip().lower(),
        "importance": str(event.get("importance") or "medium").strip().lower(),
    }
    if event_time:
        normalized["time"] = event_time
    if event.get("tz_offset") not in {None, ""}:
        normalized["tz_offset"] = event.get("tz_offset")
    if event.get("note"):
        normalized["note"] = str(event.get("note")).strip()
    rule_key, rule = _rectification_event_rule(event_type)
    normalized["supported"] = bool(rule)
    normalized["topic"] = rule["topic"] if rule else _rectification_event_topic(event_type)
    return normalized


def _normalize_rectification_birth_window(data, birth_base, search_window, source_docs):
    birth_window = dict(data.get("birth_window") or {})
    timezone_id = birth_window.get("timezone_id") or birth_base.get("timezone_id")
    birth_date = f"{birth_base['year']:04d}-{birth_base['month']:02d}-{birth_base['day']:02d}"
    start_local = str(
        birth_window.get("start_local")
        or f"{birth_date}T{search_window.get('start_time', '00:00:00')}"
    )
    end_local = str(
        birth_window.get("end_local")
        or f"{birth_date}T{search_window.get('end_time', '23:59:00')}"
    )
    start_date, start_time = start_local.split("T", 1)
    end_date, end_time = end_local.split("T", 1)
    birth_window["start_local"] = (
        f"{start_date}T"
        f"{_rectification_normalize_time_label(start_time, 'birth_window.start_local')}"
    )
    birth_window["end_local"] = (
        f"{end_date}T"
        f"{_rectification_normalize_time_label(end_time, 'birth_window.end_local')}"
    )
    birth_window["timezone_id"] = timezone_id
    birth_window["calendar"] = birth_window.get("calendar") or "gregorian"
    birth_window["source_quality"] = _normalize_rectification_source_quality(
        birth_window.get("source_quality")
    )
    if birth_window["source_quality"] == "unknown":
        birth_window["source_quality"] = _derive_rectification_source_quality(
            source_docs,
            birth_base.get("time_confidence"),
        )
    return birth_window


def _rectification_save_path(group_name, person_name):
    root = _vault_astrology_root()
    path = root / "Rektifikasyon" / group_name / person_name / f"{person_name}-Rectification-Events.md"
    _ensure_path_inside(root, path)
    return path


def _rectification_payload_from_save_data(data):
    person_input = data.get("person") or {}
    person_name = _safe_vault_segment(person_input.get("name") or data.get("name"), "person.name")
    group_name = _safe_vault_segment(person_input.get("group") or data.get("group") or "Grup-01", "group")
    birth = data["birth"]

    if birth.get("date"):
        birth_date = _parse_rectification_date(birth.get("date"), "birth.date")
        year, month, day = birth_date.year, birth_date.month, birth_date.day
    else:
        year = _require_int(birth, "year")
        month = _require_int(birth, "month")
        day = _require_int(birth, "day")

    if birth.get("time"):
        hour, minute, second = _parse_life_time_with_second(birth.get("time"))
    else:
        hour = _require_int(birth, "hour")
        minute = _require_int(birth, "minute")
        second = _optional_second(birth)

    lat = _require_float(birth, "lat")
    lon = _require_float(birth, "lon")
    _validate_birth_fields(year, month, day, hour, minute, lat, lon, second)
    tz_offset, timezone_id = _resolve_timezone_offset(birth, year, month, day, hour, minute, second)

    search_window = data.get("search_window") or {}
    if not search_window:
        birth_minutes = hour * 60 + minute
        search_window = {
            "start_time": _rectification_time_label(max(0, birth_minutes - 60)),
            "end_time": _rectification_time_label(min(23 * 60 + 59, birth_minutes + 60)),
            "step_minutes": 5,
            "step_seconds": 0,
        }
    else:
        search_window = dict(search_window)
        search_window["start_time"] = _rectification_normalize_time_label(
            search_window.get("start_time", "00:00:00"),
            "search_window.start_time",
        )
        search_window["end_time"] = _rectification_normalize_time_label(
            search_window.get("end_time", "23:59:00"),
            "search_window.end_time",
        )
    _rectification_candidate_seconds(search_window)

    birth_base = {
        "year": year,
        "month": month,
        "day": day,
        "hour": hour,
        "minute": minute,
        "second": second,
        "tz_offset": tz_offset,
        "timezone_id": timezone_id,
        "lat": lat,
        "lon": lon,
        "place": birth.get("place"),
        "time_confidence": _rectification_time_confidence(birth.get("time_confidence")),
    }
    if birth.get("birth_sex"):
        birth_base["birth_sex"] = birth.get("birth_sex")

    source_docs = _normalize_rectification_source_docs(data.get("source_docs") or birth.get("source_docs"))
    birth_window = _normalize_rectification_birth_window(data, birth_base, search_window, source_docs)

    events = data.get("events") or []
    normalized_events = [
        _normalize_rectification_event(event, index, birth_window.get("timezone_id"))
        for index, event in enumerate(events)
    ]

    return {
        "person": {
            "id": person_input.get("id") or person_name,
            "name": person_name,
            "group": group_name,
        },
        "analysis_profile": _expert_analysis_profile(data),
        "birth_base": birth_base,
        "birth_window": birth_window,
        "source_docs": source_docs,
        "search_window": search_window,
        "events": normalized_events,
    }


