        "",
        "## Doğum Bilgisi",
        "",
        f"- Tarih: {birth['day']:02d}.{birth['month']:02d}.{birth['year']} {birth['hour']:02d}:{birth['minute']:02d}:{birth.get('second', 0):02d}",
        f"- Saat dilimi: {birth.get('timezone_id') or f'UTC{birth.get('tz_offset'):+g}'}",
        f"- Koordinatlar: {birth.get('lat')}, {birth.get('lon')}",
        f"- Yer: {birth.get('place') or ''}",
        f"- Saat güveni: {birth.get('time_confidence')}",
