def _judgement_chart_from_input(judgement, fallback_tz_offset):
    if not judgement:
        return None
    try:
        date_text = str(judgement.get("date") or "").strip()
        time_text = str(judgement.get("time") or "").strip() or "12:00"
        if not date_text:
            return None
        year_text, month_text, day_text = date_text.split("-", 2)
        hour, minute = _parse_hhmm(time_text, "judgement.time")
        year = int(year_text)
        month = int(month_text)
        day = int(day_text)
        lat = _require_float(judgement, "lat")
        lon = _require_float(judgement, "lon")
        timezone_id = str(judgement.get("timezone_id") or "").strip() or None
        if timezone_id:
            tz_offset, timezone_id = _resolve_timezone_offset(
                {"timezone_id": timezone_id, "lat": lat, "lon": lon},
                year,
                month,
                day,
                hour,
                minute,
            )
        else:
            tz_offset = float(judgement.get("tz_offset", fallback_tz_offset))
        _validate_birth_fields(year, month, day, hour, minute, lat, lon)
    except (TypeError, ValueError, KeyError):
        return None

    chart = calculate_chart(year, month, day, hour, minute, tz_offset, lat, lon)
    jd = date_to_jd(year, month, day, hour, minute, tz_offset)
    return chart, jd, {
        "date": date_text,
        "time": time_text,
        "tz_offset": tz_offset,
        "timezone_id": timezone_id,
        "lat": lat,
        "lon": lon,
        "source": judgement.get("source") or "user_supplied",
    }


def _build_rectification_kp_evidence(candidates, judgement, fallback_tz_offset):
    judgement_context = _judgement_chart_from_input(judgement, fallback_tz_offset)
    if judgement_context is None:
        return {
            "status": "not_available",
            "reason": "judgement_datetime_or_location_missing",
            "method": "kp_ruling_planets_against_candidate_lagna_star_sub",
            "candidate_scores": [],
        }

    judgement_chart, judgement_jd, judgement_input = judgement_context
    judgement_kp = _build_kp(judgement_chart, judgement_jd)
    ruling = judgement_kp.get("ruling_planets", {})
    ruling_set = set(ruling.get("unique_planets", []))
    candidate_scores = []

    for candidate in candidates:
        lagna_sign_lord = SIGN_LORDS[candidate["lagna"]["sign_index"]]
        cusp = candidate["kp_lagna_cusp"]
        checks = [
            ("lagna_sign_lord", lagna_sign_lord, 2.0),
            ("lagna_star_lord", cusp.get("star_lord"), 3.0),
            ("lagna_sub_lord", cusp.get("sub_lord"), 5.0),
            ("lagna_sub_sub_lord", cusp.get("sub_sub_lord"), 4.0),
        ]
        score = 0.0
        matches = []
        for role, planet, weight in checks:
            is_match = planet in ruling_set
            if is_match:
                score += weight
            matches.append({
                "role": role,
                "planet": planet,
                "matches_judgement_ruling_planets": is_match,
                "weight": weight,
            })
        candidate_scores.append({
            "time": candidate["time"],
            "score": round(score, 2),
            "matches": matches,
        })
        candidate["kp_evidence_score"] = round(score, 2)

    return {
        "status": "implemented",
        "method": "kp_ruling_planets_against_candidate_lagna_star_sub",
        "source_rule": "Judgement-time ruling planets are compared with each candidate ascendant sign lord, star lord, sub lord and sub-sub lord",
        "assumptions": [
            "judgement_context_is_supplied_by_user"
            if judgement_input.get("source") == "user_supplied"
            else "judgement_context_auto_generated_from_analysis_time_and_birth_location",
            "node_substitution_and_kp_rejection_rules_are_not_applied",
        ],
        "excluded_rules": [
            "kp_horary_yes_no_judgement",
            "manual_ruling_planet_rejection",
            "node_representative_substitution",
        ],
        "judgement": judgement_input,
        "ruling_planets": ruling,
        "candidate_scores": candidate_scores,
    }


def _rectification_auto_judgement(data, birth_base, tz_offset, timezone_id):
    judgement = data.get("judgement")
    if isinstance(judgement, dict) and judgement.get("date"):
        return judgement
    if not _parse_bool_param(data.get("auto_judgement"), True):
        return judgement or {}

    try:
        if timezone_id:
            now = datetime.now(ZoneInfo(timezone_id))
            judgement_tz_offset = now.utcoffset().total_seconds() / 3600.0
        else:
            now = datetime.now(timezone(timedelta(hours=tz_offset)))
            judgement_tz_offset = tz_offset
        return {
            "date": now.date().isoformat(),
            "time": now.strftime("%H:%M"),
            "timezone_id": timezone_id,
            "tz_offset": judgement_tz_offset,
            "lat": birth_base.get("lat"),
            "lon": birth_base.get("lon"),
            "source": "auto_generated_analysis_time_birth_location",
        }
    except Exception:
        return judgement or {}


def _normalize_birth_sex(value):
    text = str(value or "").strip().lower()
    if text in {"male", "m", "erkek"}:
        return "male"
    if text in {"female", "f", "kadın", "kadin"}:
        return "female"
    return None


def _tattwa_from_elapsed_ghatis(elapsed_ghatis):
    cycle_position = (elapsed_ghatis % 30.0) * 2.0
    cursor = 0.0
    for tattwa, sex_polarity, duration in TATTWA_SEQUENCE:
        cursor += duration
        if cycle_position <= cursor:
            return {
                "tattwa": tattwa,
                "sex_polarity": sex_polarity,
                "cycle_position": round(cycle_position, 4),
            }
    tattwa, sex_polarity, _ = TATTWA_SEQUENCE[-1]
    return {
        "tattwa": tattwa,
        "sex_polarity": sex_polarity,
        "cycle_position": round(cycle_position, 4),
    }


def _build_rectification_tattwa_evidence(candidates, birth_base, tz_offset):
    birth_sex = _normalize_birth_sex(birth_base.get("birth_sex"))
    if not birth_sex:
        return {
            "status": "not_applicable_missing_input",
            "reason": "birth_base.birth_sex_missing",
            "method": "sunrise_based_tattwa_shodhana_technical_check",
            "candidate_scores": [],
        }

    sunrise_jd = _birth_day_sunrise_jd(birth_base, tz_offset)
    if sunrise_jd is None:
        return {
            "status": "not_available",
            "reason": "sunrise_unavailable_for_birth_location",
            "method": "sunrise_based_tattwa_shodhana_technical_check",
            "candidate_scores": [],
        }

    rows = []
    for candidate in candidates:
        birth_jd = candidate["birth_jd"]
        elapsed_ghatis = _elapsed_ghatis_since_sunrise(birth_jd, sunrise_jd)
        tattwa = _tattwa_from_elapsed_ghatis(elapsed_ghatis)
        sex_match = tattwa["sex_polarity"] in {birth_sex, "neutral"}
        rashi_type = _rashi_type(candidate["lagna"]["sign_index"])
        score = (3.0 if sex_match else 0.0) + (1.0 if rashi_type in {"movable", "fixed", "dual"} else 0.0)
        row = {
            "time": candidate["time"],
            "score": round(score, 2),
            "birth_sex": birth_sex,
            "elapsed_ghatis_since_sunrise": round(elapsed_ghatis, 4),
            "tattwa": tattwa["tattwa"],
            "sex_polarity": tattwa["sex_polarity"],
            "sex_match": sex_match,
            "lagna_rashi_type": rashi_type,
        }
        rows.append(row)
        candidate["tattwa_evidence_score"] = row["score"]

    return {
        "status": "implemented_technical_variant",
        "method": "sunrise_based_tattwa_shodhana_technical_check",
        "source_rule": "Candidate birth time is measured from local sunrise and mapped into a repeating tattwa sequence; birth sex polarity is exposed as a technical check",
        "assumptions": [
            "uses_30_ghati_repeating_cycle_scaled_to_60_units",
            "akasha_is_treated_as_neutral",
            "this_is_a_technical_filter_not_final_classical_verdict",
        ],
        "excluded_rules": [
            "alternate_tattwa_sequence_variants",
            "manual_caste_or_tradition_filters",
            "full_shodhana_table_variants",
        ],
        "sunrise_jd": round(sunrise_jd, 6),
        "candidate_scores": rows,
    }


def _build_rectification_event_evidence_matrix(candidates, events):
    rows = []
    for index, event in enumerate(events):
        rows.append({
            "event_index": index,
            "event_type": event.get("type"),
            "date": event.get("date"),
            "confidence": event.get("confidence", "medium"),
            "certainty": event.get("certainty") or event.get("date_certainty") or "day_exact",
            "candidate_scores": [
                {
                    "time": candidate["time"],
                    "score": candidate["event_scores"][index]["score"],
                    "raw_score": candidate["event_scores"][index].get("raw_score"),
                    "factor_count": candidate["event_scores"][index].get("factor_count"),
                    "topic": candidate["event_scores"][index].get("topic"),
                    "prana_lord": (
                        (candidate["event_scores"][index].get("prana_evidence") or {}).get("lord")
                    ),
                }
                for candidate in candidates
                if index < len(candidate.get("event_scores", []))
            ],
        })
    return {
        "status": "implemented",
        "method": "event_by_candidate_weighted_score_matrix",
        "rows": rows,
    }


def _build_rectification_candidate_windows(ranked):
    if not ranked:
        return []
    score_key = "ranking_score" if "ranking_score" in ranked[0] else "total_score"
    top_score = ranked[0][score_key]
    threshold = max(top_score * 0.9, top_score - 5.0)
    strong = sorted(
        [candidate for candidate in ranked if candidate[score_key] >= threshold],
        key=lambda item: (item["hour"], item["minute"], item.get("second", 0)),
    )
    windows = []
    current = []
    for candidate in strong:
        if not current:
            current = [candidate]
            continue
        previous = current[-1]
        delta = (candidate["hour"] * 60 + candidate["minute"]) - (previous["hour"] * 60 + previous["minute"])
        if delta <= 10:
            current.append(candidate)
        else:
            windows.append(current)
            current = [candidate]
    if current:
        windows.append(current)

    return [
        {
            "start_time": window[0]["time"],
            "end_time": window[-1]["time"],
            "candidate_count": len(window),
            "max_score": max(item[score_key] for item in window),
            "min_score": min(item[score_key] for item in window),
            "times": [item["time"] for item in window],
        }
        for window in windows
    ]


RECTIFICATION_AYANAMSA_SCAN_SPECS = [
    ("Lahiri", swe.SIDM_LAHIRI),
    ("Raman", swe.SIDM_RAMAN),
    ("Krishnamurti", swe.SIDM_KRISHNAMURTI),
]


def _rectification_lagna_for_ayanamsa(year, month, day, hour, minute, tz_offset, lat, lon, sid_mode, second=0):
    swe.set_sid_mode(sid_mode)
    flags = swe.FLG_SIDEREAL | swe.FLG_SPEED
    jd = date_to_jd(year, month, day, hour, minute, tz_offset, second)
    _cusps, ascmc = swe.houses_ex(jd, lat, lon, b'W', flags)
    longitude = ascmc[0] % 360.0
    sign_index = int(longitude / 30.0)
    return {
        "longitude": round(longitude, 6),
        "ayanamsa_value": round(swe.get_ayanamsa_ut(jd), 6),
        "sign_index": sign_index,
        "sign": SIGNS_EN[sign_index],
        "sign_tr": _sign_tr(SIGNS_TR[sign_index]),
        "degree": round(longitude % 30.0, 6),
        "degree_str": dms_str(longitude % 30.0),
    }


def _build_rectification_ayanamsa_scan(candidates, birth_base, tz_offset, lat, lon):
    rows = []
    try:
        for candidate in candidates:
            variants = []
            signs = set()
            for name, sid_mode in RECTIFICATION_AYANAMSA_SCAN_SPECS:
                lagna = _rectification_lagna_for_ayanamsa(
                    birth_base["year"],
                    birth_base["month"],
                    birth_base["day"],
                    candidate["hour"],
                    candidate["minute"],
                    tz_offset,
                    lat,
                    lon,
                    sid_mode,
                    candidate.get("second", 0),
                )
                variants.append({"ayanamsa": name, "lagna": lagna})
                signs.add(lagna["sign_index"])
            rows.append({
                "time": candidate["time"],
                "same_lagna_across_ayanamsas": len(signs) == 1,
                "variants": variants,
            })
    finally:
        swe.set_sid_mode(swe.SIDM_LAHIRI)

    unstable = [row for row in rows if not row["same_lagna_across_ayanamsas"]]
    return {
        "status": "implemented_technical_ayanamsa_lagna_scan",
        "method": "candidate_lagna_recomputed_for_lahiri_raman_krishnamurti",
        "source_rule": "Ayanamsa scan exposes whether candidate Lagna sign changes under selected sidereal ayanamsas",
        "assumptions": [
            "scan_is_lagna_sensitivity_only",
            "main_chart_engine_remains_lahiri",
            "no_probability_is_assigned_to_ayanamsa_variants",
        ],
        "excluded_rules": [
            "full_planetary_recalculation_payload_per_ayanamsa",
            "statistical_ayanamsa_selection",
            "manual_parampara_preference",
        ],
        "ayanamsas": [name for name, _mode in RECTIFICATION_AYANAMSA_SCAN_SPECS],
        "unstable_candidate_count": len(unstable),
        "rows": rows,
    }


