def _score_varshaphala_for_event(varshaphala, event):
    _rule_key, rule = _rectification_event_rule(event.get("type"))
    if not rule:
        return {
            "score": 0.0,
            "factors": [],
            "reason": "event_rule_not_supported_for_varshaphala",
        }

    relevant_houses = set(rule.get("houses", []))
    relevant_planets = set(rule.get("planets", []))
    score = 0.0
    factors = []

    muntha_house = (varshaphala.get("muntha") or {}).get("house_from_varsha_lagna")
    if muntha_house in relevant_houses:
        score += 3.0
        factors.append({
            "type": "muntha_in_relevant_annual_house",
            "house": muntha_house,
            "weight": 3.0,
        })

    year_lord = ((varshaphala.get("year_lord") or {}).get("selected") or {})
    if year_lord.get("annual_house") in relevant_houses:
        score += 2.0
        factors.append({
            "type": "year_lord_in_relevant_annual_house",
            "planet": year_lord.get("planet"),
            "house": year_lord.get("annual_house"),
            "weight": 2.0,
        })
    if year_lord.get("planet") in relevant_planets:
        score += 1.5
        factors.append({
            "type": "year_lord_matches_event_karaka",
            "planet": year_lord.get("planet"),
            "weight": 1.5,
        })

    active_mudda = ((varshaphala.get("mudda_dasha") or {}).get("active") or {})
    if active_mudda.get("lord") in relevant_planets:
        score += 1.0
        factors.append({
            "type": "active_mudda_lord_matches_event_karaka",
            "lord": active_mudda.get("lord"),
            "weight": 1.0,
        })

    return {
        "score": round(score, 2),
        "factors": factors,
    }


