def _build_rectification_report(data):
    analysis = _build_rectification_analysis(data)
    person = data.get("person") or {}
    return {
        "status": "rectification_technical_report_ready",
        "report_type": "astrogpt_rectification_technical_package",
        "person": person,
        "birth_window": analysis["input"].get("birth_window"),
        "source_docs": analysis["input"].get("source_docs", []),
        "data_quality": analysis.get("data_quality", {}),
        "data_readiness": analysis.get("data_readiness", {}),
        "calibration_readiness": analysis.get("calibration_readiness", {}),
        "method_status": analysis.get("method_status", {}),
        "rectification_score_v1": analysis.get("rectification_score_v1", {}),
        "rectification_v1_status": analysis.get("rectification_v1_status", {}),
        "candidate_windows": analysis.get("candidate_windows", []),
        "candidate_rankings": analysis.get("candidate_rankings", []),
        "top_candidates": analysis.get("top_candidates", []),
        "event_evidence_matrix": analysis.get("event_evidence_matrix", {}),
        "kp_evidence": analysis.get("kp_evidence", {}),
        "tattwa_evidence": analysis.get("tattwa_evidence", {}),
        "varga_evidence": analysis.get("varga_evidence", {}),
        "ayanamsa_scan": analysis.get("ayanamsa_scan", {}),
        "varshaphala_tajika_evidence": analysis.get("varshaphala_tajika_evidence", {}),
        "varshaphala_tajika_readiness": analysis.get("varshaphala_tajika_readiness", {}),
        "prasna_evidence": analysis.get("prasna_evidence", {}),
        "nasta_jataka_reconstruction": analysis.get("nasta_jataka_reconstruction", {}),
        "statistical_model": analysis.get("statistical_model", {}),
        "missing_requirements": analysis.get("missing_requirements", []),
        "analysis": analysis,
        "astrogpt_markdown": _rectification_report_markdown(analysis, person),
        "technical_notes": [
            "No interpretive sentences are generated by this endpoint.",
            "selected_time is not returned; the report ranks candidate times and windows.",
            "source_docs and birth_window are used as data quality inputs.",
            "Ayanamsa, Varshaphala/Tajika, Prasna and Nasta Jataka layers are technical evidence layers only.",
            "Prana Dasha is exposed inside rectification event evidence as evidence only; it does not change candidate scores in this phase.",
            "Machine-learning probability, Bayesian optimization and conformal intervals are not implemented in this phase.",
        ],
    }


def _vault_astrology_root():
    return Path(app.config["VAULT_ASTROLOGY_ROOT"])


def _safe_vault_segment(value, field_name):
    text = str(value or "").strip()
    if not text:
        raise ValueError(f"{field_name} boş olamaz")

    text = text.replace("/", "-").replace("\\", "-")
    text = re.sub(r"[^\w\s.\-ğüşöçıİĞÜŞÖÇ]", "-", text, flags=re.UNICODE)
    text = re.sub(r"\s+", " ", text).strip(" .")
    text = re.sub(r"-+", "-", text)

    if not text or text in {".", ".."}:
        raise ValueError(f"{field_name} geçersiz")

    return text


def _ensure_path_inside(base_path, target_path):
    base_resolved = base_path.resolve()
    target_resolved = target_path.resolve()
    if target_resolved != base_resolved and base_resolved not in target_resolved.parents:
        raise ValueError("Vault yolu güvenli kökün dışında kalıyor")


def _markdown_value(value):
    if value is None:
        return ""
    return str(value).replace("|", "\\|").replace("\n", " ")


def _markdown_table(headers, rows):
    header = "| " + " | ".join(headers) + " |"
    separator = "| " + " | ".join(["---"] * len(headers)) + " |"
    body = [
        "| " + " | ".join(_markdown_value(value) for value in row) + " |"
        for row in rows
    ]
    return "\n".join([header, separator, *body])


def _frontmatter(title, person_name, group_name, chart, note_type, modified_at=None):
    birth = chart.get("birth", {})
    generated_at = modified_at or datetime.now().astimezone().isoformat(timespec="seconds")
    lines = [
        "---",
        f'title: "{title}"',
        f'type: "{note_type}"',
        f'person: "{person_name}"',
        f'group: "{group_name}"',
        f'birth_date: "{birth.get("date", "")}"',
        f'birth_time: "{birth.get("time", "")}"',
        f'timezone: "{birth.get("timezone_label") or birth.get("timezone", "")}"',
        f'created: "{generated_at}"',
    ]
    if modified_at:
        lines.append(f'modified: "{modified_at}"')
    lines.extend([
        f'api_version: "{chart.get("meta", {}).get("api_version", "")}"',
        f'engine_version: "{chart.get("meta", {}).get("engine_version", "")}"',
        "---",
        "",
    ])
    return "\n".join(lines)


def _wiki_link(note_name, label=None):
    if label and label != note_name:
        return f"{label} ({note_name})"
    return str(note_name)


def _display_file_name(path_value):
    if path_value in {None, ""}:
        return ""
    return Path(str(path_value)).name


def _vault_link_rows(person_name):
    return {
        "person": _wiki_link(person_name, "Kişi Dosyası"),
        "natal": _wiki_link(person_name, "Natal"),
        "dashas": _wiki_link(person_name, "Dashas"),
        "comments": _wiki_link(f"{person_name}-Yorumlar", "Yorumlar"),
    }


def _planet_rows(chart):
    rows = []
    for planet in chart.get("planets", []):
        varga_status = planet.get("varga_status", {})
        combustion = planet.get("combustion", {})
        war = planet.get("war", {})
        motion = planet.get("motion", {})
        dignity = planet.get("dignity", {})
        rows.append([
            planet.get("name"),
            f'{planet.get("sign_tr")} ({planet.get("sign")})',
            planet.get("house"),
            planet.get("degree_str"),
            planet.get("nakshatra", {}).get("name"),
            varga_status.get("D9", {}).get("sign"),
            dignity.get("essential"),
            combustion.get("severity"),
            war.get("status"),
            "evet" if varga_status.get("vargottama") else "hayır",
            "R" if motion.get("retrograde") else "",
        ])
    return rows


def _varga_rows(chart, division):
    varga = chart.get("vargas", {}).get(division, {})
    rows = [[
        "Lagna",
        varga.get("lagna", {}).get("sign_tr"),
        varga.get("lagna", {}).get("sign"),
        varga.get("lagna", {}).get("degree_str"),
    ]]
    for planet in varga.get("planets", []):
        rows.append([
            planet.get("name"),
            planet.get("sign_tr"),
            planet.get("sign"),
            planet.get("degree_str"),
        ])
    return rows


def _jaimini_rows(chart):
    chara = chart.get("jaimini", {}).get("chara_karakas", {})
    rows = []
    for role in ["AK", "AmK", "BK", "MK", "PK", "GK", "DK"]:
        karaka = chara.get(role, {})
        rows.append([
            role,
            karaka.get("planet"),
            karaka.get("sign"),
            karaka.get("degree_str"),
            karaka.get("nakshatra"),
        ])
    return rows


def _maha_dasha_rows(chart):
    maha_periods = chart.get("dashas", {}).get("vimshottari", {}).get("maha", [])
    return [
        [
            period.get("lord"),
            period.get("effective_years"),
            period.get("start"),
            period.get("end"),
            "evet" if period.get("is_birth_dasha") else "",
        ]
        for period in maha_periods
    ]


def _active_dasha_rows(chart):
    vimshottari = chart.get("dashas", {}).get("vimshottari", {})
    active = vimshottari.get("current_active") or vimshottari.get("active", {})
    rows = []
    for level in DASHA_LEVELS:
        period = active.get(level)
        if not period:
            continue
        rows.append([
            level,
            period.get("lord"),
            period.get("start"),
            period.get("end"),
            period.get("effective_years"),
        ])
    return rows


def _markdown_sign(item):
    if not item:
        return ""
    sign_tr = item.get("sign_tr")
    sign = item.get("sign")
    if sign_tr and sign:
        return f"{sign_tr} ({sign})"
    return sign_tr or sign or ""


def _expert_shadbala_rows(chart):
    rows = []
    for planet in chart.get("shadbala", {}).get("planets", []):
        components = planet.get("components", {})
        professional_total = planet.get("professional_total") or {}
        component_summary = professional_total.get("component_breakdown_summary") or {}
        rows.append([
            planet.get("planet"),
            planet.get("total_score"),
            professional_total.get("total_rupa"),
            professional_total.get("required_rupa"),
            professional_total.get("strength_ratio"),
            professional_total.get("professional_status"),
            component_summary.get("strongest_component"),
            component_summary.get("weakest_component"),
            components.get("yuddha_bala", {}).get("score_adjustment"),
        ])
    return rows


def _expert_shadbala_summary_rows(chart):
    summary = (chart.get("shadbala") or {}).get("summary") or {}
    strongest = summary.get("strongest_planet") or {}
    weakest = summary.get("weakest_planet") or {}
    return [
        ["Gezegen sayısı", summary.get("planet_count", "")],
        ["En guclu gezegen", strongest.get("planet", "")],
        ["En guclu oran", strongest.get("strength_ratio", "")],
        ["En zayif gezegen", weakest.get("planet", "")],
        ["En zayif oran", weakest.get("strength_ratio", "")],
        ["Dikkat isteyenler", ", ".join(summary.get("needs_attention") or [])],
    ]


def _expert_shadbala_component_label(component_name):
    labels = {
        "sthana_bala": "Sthana",
        "dig_bala": "Dig",
        "cheshta_bala": "Cheshta",
        "kala_bala": "Kala",
        "drik_bala": "Drik",
        "naisargika_bala": "Naisargika",
        "yuddha_bala_adjustment": "Yuddha adj.",
    }
    return labels.get(component_name, component_name or "")


def _expert_shadbala_note(planet):
    professional_total = planet.get("professional_total") or {}
    component_summary = professional_total.get("component_breakdown_summary") or {}
    strongest = _expert_shadbala_component_label(
        component_summary.get("strongest_component")
    )
    weakest = _expert_shadbala_component_label(
        component_summary.get("weakest_component")
    )
    status = professional_total.get("professional_status")
    ratio = professional_total.get("strength_ratio")

    if status == "sufficient":
        margin = professional_total.get("excess_rupa")
        if ratio is not None and ratio >= 1.25:
            return (
                f"Minimumu net gecer; ana destek {strongest}, "
                f"zayif halka {weakest}, marj {margin} rupa."
            )
        return (
            f"Minimumu gecer; ana destek {strongest}, "
            f"izlenecek alan {weakest}, marj {margin} rupa."
        )

    if status == "near_minimum":
        deficit = professional_total.get("deficit_rupa")
        return (
            f"Sinira yakin; ana destek {strongest}, "
            f"zayif halka {weakest}, eksik {deficit} rupa."
        )

    deficit = professional_total.get("deficit_rupa")
    return (
        f"Minimumun altinda; ana destek {strongest}, "
        f"zayif halka {weakest}, acik {deficit} rupa."
    )


def _expert_shadbala_note_rows(chart):
    return [
        [planet.get("planet"), _expert_shadbala_note(planet)]
        for planet in chart.get("shadbala", {}).get("planets", [])
    ]


