def _expert_varga_full_markdown_sections(chart, divisions):
    vargas = chart.get("vargas", {})
    lines = []
    for division in divisions:
        varga = vargas.get(division)
        if not varga:
            continue
        validation = _varga_calculation_validation(varga, division)
        lines.extend([
            f"## {division} {varga.get('name', '')} Full Tablo",
            "",
            f"- Güven: {varga.get('confidence', '')}",
            f"- Source rule: {varga.get('source_rule', '')}",
            f"- Dış doğrulama: {validation.get('status', '')}",
            "",
            _markdown_table(["Nokta", f"{division} Burç", f"{division} Derece"], _expert_varga_rows(chart, division)),
            "",
        ])
    return lines


def _expert_sav_rows(chart):
    rows = chart.get("ashtakavarga", {}).get("sarva", {}).get("by_sign", [])
    return [
        [row.get("house"), _markdown_sign(row), row.get("bindus")]
        for row in sorted(rows, key=lambda item: item.get("house") or 99)
    ]


def _expert_bav_headers(chart):
    ashtakavarga = chart.get("ashtakavarga", {})
    return ashtakavarga.get("ruleset", {}).get("target_planets") or list(
        ashtakavarga.get("bhinna", {}).keys()
    )


def _expert_bav_rows(chart):
    ashtakavarga = chart.get("ashtakavarga", {})
    sav_rows = ashtakavarga.get("sarva", {}).get("by_sign", [])
    planets = _expert_bav_headers(chart)
    rows = []
    for sav_row in sorted(sav_rows, key=lambda item: item.get("house") or 99):
        sign_index = sav_row.get("sign_index")
        row = [sav_row.get("house"), _markdown_sign(sav_row)]
        for planet in planets:
            bav_row = next(
                (
                    item
                    for item in ashtakavarga.get("bhinna", {}).get(planet, {}).get("by_sign", [])
                    if item.get("sign_index") == sign_index
                ),
                {},
            )
            row.append(bav_row.get("bindus", ""))
        rows.append(row)
    return rows


def _expert_join(items):
    return ", ".join(str(item) for item in items if item) if items else ""


def _expert_bhava_bala_rows(chart):
    bhava_bala = chart.get("bhava_bala") or {}
    rows = []
    for house in bhava_bala.get("houses", []):
        lordship = house.get("lordship") or {}
        condition = lordship.get("condition") or {}
        ashtakavarga = house.get("ashtakavarga") or {}
        lord_shadbala = house.get("lord_shadbala") or {}
        bhava_chalit = house.get("bhava_chalit") or {}
        changed_planets = [
            item.get("planet")
            for item in bhava_chalit.get("changed_planets_touching_house", [])
            if item.get("planet")
        ]
        rows.append([
            house.get("house", ""),
            house.get("sign", ""),
            house.get("lord", ""),
            _expert_join(house.get("occupants")),
            _expert_join(house.get("graha_aspected_by")),
            _expert_join(house.get("rashi_aspected_by")),
            ashtakavarga.get("sav", ""),
            ashtakavarga.get("lord_bav", ""),
            lord_shadbala.get("total_score", ""),
            lord_shadbala.get("grade", ""),
            condition.get("dignity", ""),
            "yes" if condition.get("combust") else "no",
            bhava_chalit.get("cusp_sign", ""),
            _expert_join(changed_planets),
            house.get("score_status", ""),
        ])
    return rows or [["status", "not_available", "", "", "", "", "", "", "", "", "", "", "", "", ""]]


