def _expert_generic_active_dasha_rows(dasha_layer):
    if not dasha_layer:
        return [["status", "not_available", "", "", "API response içinde aktif periyot yok"]]

    active = dasha_layer.get("current_active") or dasha_layer.get("active") or {}
    rows = []
    if isinstance(active, dict):
        for level in DASHA_LEVELS:
            period = active.get(level)
            if not isinstance(period, dict):
                continue
            rows.append([
                level,
                period.get("yogini") or period.get("lord") or period.get("rashi") or period.get("sign"),
                period.get("start"),
                period.get("end"),
                period.get("effective_years") or period.get("years") or "",
            ])
        if not rows and active:
            rows.append([
                "active",
                active.get("yogini") or active.get("lord") or active.get("rashi") or active.get("sign") or active.get("path"),
                active.get("start"),
                active.get("end"),
                active.get("effective_years") or active.get("years") or "",
            ])

    return rows or [["status", "not_available", "", "", "API response içinde aktif periyot yok"]]


