def _expert_graha_yuddha_rows(chart):
    rows = []
    for planet in chart.get("planets", []):
        war = planet.get("war", {})
        if war.get("status") == "not_applicable":
            result = "Graha Yuddha kapsam dışı"
        elif war.get("in_graha_yuddha"):
            result = "Graha Yuddha var; kazanan/kaybeden hesaplanmıyor"
        else:
            result = "Graha Yuddha yok"
        rows.append([
            planet.get("name"),
            war.get("status"),
            "evet" if war.get("in_graha_yuddha") else "hayır",
            war.get("opponent"),
            war.get("orb"),
            result,
        ])
    return rows


