def _expert_life_career_event_ranking_rows(life_period):
    timing = life_period.get("career_timing_evidence_v2", {})
    rows = []
    for event_type in CAREER_EVENT_TYPE_KEYS:
        for rank, row in enumerate(
            (timing.get("event_type_rankings") or {}).get(event_type, [])[:6],
            start=1,
        ):
            rows.append([
                event_type,
                rank,
                row.get("start_date"),
                row.get("end_date"),
                row.get("age_start"),
                " > ".join(row.get("dasha_path", [])),
                row.get("support_score"),
                row.get("counter_score"),
                row.get("net_score"),
                row.get("status"),
                row.get("interpretation_limit"),
                "; ".join(
                    item.get("code", "")
                    for item in row.get("evidence", [])[:3]
                ),
                "; ".join(
                    item.get("code", "")
                    for item in row.get("counter_evidence", [])[:3]
                ),
            ])
    return rows


