def _expert_varshaphala_summary_rows(chart):
    varsha = chart.get("varshaphala") or {}
    year = varsha.get("year") or {}
    lagna = varsha.get("varsha_lagna") or {}
    muntha = varsha.get("muntha") or {}
    selected = (varsha.get("year_lord") or {}).get("selected") or {}
    mudda = varsha.get("mudda_dasha") or {}
    active_mudda = mudda.get("active") or {}
    return [
        ["Status", varsha.get("status", "not_available")],
        ["Yıl", year.get("varsha_start_year", "")],
        ["Solar Return Başlangıç", year.get("start_local", "")],
        ["Solar Return Bitiş", year.get("end_utc", "")],
        ["Varsha Lagna", f"{_markdown_sign(lagna)} {lagna.get('degree_str', '')}".strip()],
        ["Muntha", f"{_markdown_sign(muntha)} / Ev {muntha.get('house_from_varsha_lagna', '')} / Lord {muntha.get('lord', '')}"],
        ["Varshesha", f"{selected.get('planet', '')} / Rol {selected.get('role', '')} / Skor {selected.get('score', '')}"],
        ["Aktif Mudda", f"{active_mudda.get('lord', '')} / {active_mudda.get('start_utc', '')} → {active_mudda.get('end_utc', '')}"],
    ]


