def _expert_topic_career_summary(chart):
    d10_lagna = _topic_varga_lagna(chart, "D10")
    d10_lagna_lord = SIGN_LORDS.get(d10_lagna.get("sign_index")) if d10_lagna else None
    d10_lord_planet = _topic_varga_planet(chart, "D10", d10_lagna_lord) if d10_lagna_lord else None
    flags = []
    maha_lord = _topic_active_dasha_lords(chart)[0][1]
    maha_planet = _topic_planet(chart, maha_lord) if maha_lord else None
    if maha_planet and maha_planet.get("house") in {6, 8, 12}:
        flags.append("Maha lord dusthana evde -> kariyer dönemi yavaş ve dönüşüm odaklı")
    sav_10 = _topic_sav(chart, 10)
    if isinstance(sav_10, (int, float)) and sav_10 < 25:
        flags.append(f"10. ev SAV düşük ({sav_10}) -> kariyer ev yapısal olarak zayıf")
    ak_name = _topic_karaka_name(chart, "AK")
    if ak_name and _topic_debilitated(chart, ak_name):
        flags.append("Atmakaraka neecha -> temel yönelimde iç çatışma teması")

    lines = [
        "### Kariyer / Meslek Özeti",
        "",
        "- Bu özet API tarafından üretilmiştir; yorum içermez.",
        f"- D10 Lagna: {_markdown_sign(d10_lagna) or 'veri yok'} | Lord: {_topic_value(d10_lagna_lord)} | D10'daki konumu: {_topic_sign_house_text(d10_lord_planet, _topic_house_from_varga_lagna(chart, 'D10', (d10_lord_planet or {}).get('sign_index')))}",
        "- Dasha lordlarının D10 konumu:",
    ]
    for level, lord in _topic_active_dasha_lords(chart):
        lines.append(f"  - {level}: {_topic_value(lord)} -> {_topic_planet_varga_text(chart, 'D10', lord) if lord else 'veri yok'}")
    lines.extend([
        _topic_karaka_line(chart, "AmK", "Amatyakaraka", "D10"),
        _topic_karaka_line(chart, "AK", "Atmakaraka", "D10"),
        "- BAV Kariyer Evleri:",
        _topic_bav_house_line(chart, 6, ["Sun", "Saturn", "Mercury"]),
        _topic_bav_house_line(chart, 10, ["Sun", "Saturn", "Mercury"]),
        _topic_bav_house_line(chart, 11, ["Sun", "Saturn", "Mercury"]),
        f"- Maha lord natal konumu: {_topic_planet_d1_text(chart, maha_lord) if maha_lord else 'veri yok'}",
    ])
    _topic_append_flags(lines, flags)
    return lines


