def _expert_copy_person_context(chart, request_data=None):
    request_data = request_data or {}
    person = request_data.get("person") or chart.get("birth", {}).get("person") or {}
    birth_person = chart.get("birth", {}).get("person") or {}
    person_name = str(
        person.get("name")
        or birth_person.get("name")
        or request_data.get("name")
        or "Danışan"
    ).strip()
    group_name = str(
        person.get("group")
        or birth_person.get("group")
        or request_data.get("group")
        or ""
    ).strip()
    return person_name or "Danışan", group_name


def _attach_expert_copy_package(chart, request_data=None):
    request_data = request_data or {}
    if request_data.get("analysis_profile"):
        chart["analysis_profile"] = _expert_analysis_profile(request_data)
    elif not chart.get("analysis_profile"):
        chart["analysis_profile"] = _expert_analysis_profile(chart)

    person_name, group_name = _expert_copy_person_context(chart, request_data)
    expert_package = {
        "source": "backend_generator",
        "generator": "_build_expert_copy_markdown",
        "analysis_profile": _expert_analysis_profile(chart),
        "markdown": _build_expert_copy_markdown(chart, person_name, group_name),
    }
    copy_packages = dict(chart.get("copy_packages") or {})
    copy_packages["expert"] = expert_package
    chart["copy_packages"] = copy_packages
    return expert_package


def _expert_copy_payload(chart, person_name, group_name):
    expert_package = _attach_expert_copy_package(
        chart,
        {
            "person": {
                "name": person_name,
                "group": group_name,
            },
        },
    )
    return {
        "copy_packages": {
            "expert": expert_package,
        },
    }


