def _vault_person_path(group_name, person_name):
    root = _vault_astrology_root()
    charts_dir = root / "Haritalar" / group_name / person_name
    person_path = charts_dir / f"{person_name}.md"

    _ensure_path_inside(root, person_path)

    return person_path


def _analysis_data_package_path(group_name, person_name, package_name, extension="md"):
    root = _vault_astrology_root()
    safe_group = _safe_vault_segment(group_name, "group")
    safe_person = _safe_vault_segment(person_name, "person.name")
    safe_package = _safe_vault_segment(package_name, "analysis_package")
    safe_extension = str(extension).strip().lower()
    if safe_extension not in {"md", "txt"}:
        raise ValueError("analysis_package extension geçersiz")
    package_path = (
        root
        / "Analiz Veri Paketleri"
        / safe_group
        / safe_person
        / f"{safe_package}.{safe_extension}"
    )
    _ensure_path_inside(root, package_path)
    return package_path


def _person_analysis_package_path(group_name, person_name, package_name):
    root = _vault_astrology_root()
    safe_package = _safe_vault_segment(package_name, "analysis_package")
    package_path = _vault_person_path(group_name, person_name).parent / f"{safe_package}.md"
    _ensure_path_inside(root, package_path)
    return package_path


def _active_transit_source_markdown(transit_pack):
    period = (transit_pack or {}).get("period") or {}
    period_type = period.get("type")
    lines = [
        "## Aktif Transit Veri Kaynağı",
        "",
        "- Bu bölüm yalnız bu paket üretilirken kullanılan günlük transit dosyasını tanımlar.",
        "- Mevcut tarihsel konu sıralamalarının dasha tarihlerini veya aktivasyon puanlarını değiştirmez.",
        "- Seçili özel aralık ile otomatik üç aylık paket birleştirilmez.",
        "",
    ]
    if not period_type:
        lines.extend([
            "- Durum: active_transit_not_provided",
            "- Bu üretimde seçili özel aralık veya otomatik üç aylık transit kaynağı aktarılmadı.",
        ])
        return "\n".join(lines)

    source_mode = {
        "range": "selected_range",
        "three_month": "automatic_three_month",
    }.get(period_type, period_type)
    lines.extend([
        f"- Kaynak modu: {source_mode}",
        f"- Paket türü: {period_type}",
        (
            f"- Tarih aralığı: {period.get('range_start')} → "
            f"{period.get('range_end')}"
        ),
        f"- Günlük kayıt sayısı: {period.get('day_count', '')}",
    ])
    if transit_pack.get("_source_path"):
        lines.append(
            "- Kaynak transit dosyası: "
            f"{_display_file_name(transit_pack['_source_path'])}"
        )
    lines.extend([
        "- Yalnız bu tarih aralığındaki günlük transit kayıtları ayrıntılı zamanlama katmanı olarak kullanılabilir.",
        "- Bu ilk entegrasyon adımı konuya özel günlük pencere sıralaması üretmez.",
    ])
    return "\n".join(lines)


def _career_selected_transit_coverage_rows(life_period, transit_pack):
    period = (transit_pack or {}).get("period") or {}
    if period.get("type") != "range":
        return []

    transit_start = _parse_life_date(period.get("range_start"), "range_start")
    transit_end = _parse_life_date(period.get("range_end"), "range_end")
    candidates = (
        (life_period.get("career_timing_evidence_v2") or {})
        .get("early_career_candidates")
        or []
    )
    rows = []
    for rank, candidate in enumerate(candidates, start=1):
        candidate_start = _parse_life_date(
            candidate.get("start_date"),
            "career_candidate_start_date",
        )
        candidate_end = _parse_life_date(
            candidate.get("end_date"),
            "career_candidate_end_date",
        )
        overlap_start = max(candidate_start, transit_start)
        overlap_end = min(candidate_end, transit_end)

        if overlap_start > overlap_end:
            coverage_status = "kapsam_dışı"
            overlap_label = ""
            uncovered_label = (
                f"{candidate_start.isoformat()} → {candidate_end.isoformat()}"
            )
        else:
            full_coverage = (
                transit_start <= candidate_start
                and transit_end >= candidate_end
            )
            coverage_status = "tam_kapsam" if full_coverage else "kısmi_kapsam"
            overlap_label = (
                f"{overlap_start.isoformat()} → {overlap_end.isoformat()}"
            )
            uncovered = []
            if candidate_start < overlap_start:
                uncovered.append(
                    f"{candidate_start.isoformat()} → "
                    f"{(overlap_start - timedelta(days=1)).isoformat()}"
                )
            if overlap_end < candidate_end:
                uncovered.append(
                    f"{(overlap_end + timedelta(days=1)).isoformat()} → "
                    f"{candidate_end.isoformat()}"
                )
            uncovered_label = "; ".join(uncovered)

        rows.append([
            rank,
            candidate_start.isoformat(),
            candidate_end.isoformat(),
            " > ".join(candidate.get("dasha_path", [])),
            f"{transit_start.isoformat()} → {transit_end.isoformat()}",
            overlap_label,
            coverage_status,
            uncovered_label,
        ])
    return rows


def _career_selected_transit_coverage_markdown(life_period, transit_pack):
    period = (transit_pack or {}).get("period") or {}
    lines = [
        "## Seçili Transit Aralığı - Erken Kariyer Aday Kapsamı",
        "",
        "- Bu tablo dasha veya kariyer adayı tarihlerini değiştirmez.",
        "- Seçili transit aralığı yalnız aday penceresinin hangi bölümünde günlük transit verisi bulunduğunu gösterir.",
        "- `tam_kapsam` adayın tamamının, `kısmi_kapsam` yalnız ortak tarihlerin, `kapsam_dışı` ise hiçbir günün transit dosyasında bulunmadığını gösterir.",
        "- Yalnız ortak tarih aralığı transit kanıtıyla değerlendirilebilir.",
        "",
    ]
    if period.get("type") != "range":
        lines.extend([
            "- Durum: selected_transit_range_not_provided",
            "- Otomatik günlük/aylık/3 aylık transit paketi, kullanıcı tarafından seçilmiş tarih aralığı yerine kullanılmaz.",
        ])
        return "\n".join(lines)

    rows = _career_selected_transit_coverage_rows(life_period, transit_pack)
    lines.extend([
        f"- Seçili transit aralığı: {period.get('range_start')} → {period.get('range_end')}",
        *(
            [
                "- Kaynak transit dosyası: "
                f"{_display_file_name(transit_pack.get('_source_path'))}"
            ]
            if transit_pack.get("_source_path")
            else []
        ),
        "",
        _markdown_table(
            [
                "Sıra",
                "Aday Başlangıç",
                "Aday Bitiş",
                "Dasha Yolu",
                "Transit Dosyası",
                "Ortak Aralık",
                "Kapsam",
                "Kapsanmayan Aday Günleri",
            ],
            rows,
        ),
    ])
    return "\n".join(lines)


