        _markdown_table(
            ["Varga", "Ad", "Güven", "Lagna", "Source Rule", "Dış Doğrulama"],
            _health_varga_status_rows(chart),
        ),
        "",
        "### D6 Full Tablo",
        "",
        _markdown_table(["Nokta", "Burç", "Derece"], _expert_varga_rows(chart, "D6")),
        "",
        "### D12 Full Tablo",
        "",
        _markdown_table(["Nokta", "Burç", "Derece"], _expert_varga_rows(chart, "D12")),
        "",
