def _family_lord_rows(chart):
    rows = []
    for house in FAMILY_ANALYSIS_HOUSES:
        lordship = _topic_lordship(chart, house)
        lord = lordship.get("lord")
        planet = _topic_planet(chart, lord)
        rows.append([
            house,
            _topic_value(lord),
            _topic_sign_house_text(planet),
            (planet or {}).get("degree_str", ""),
            _career_nakshatra_text(planet),
            _topic_value(((planet or {}).get("dignity") or {}).get("essential")),
            _topic_planet_varga_text(chart, "D7", lord),
            _topic_planet_varga_text(chart, "D12", lord),
            _topic_planet_varga_text(chart, "D4", lord),
        ])
    return rows


def _family_planet_rows(chart):
    rows = []
    for planet_name in FAMILY_ANALYSIS_PLANETS:
        planet = _topic_planet(chart, planet_name)
        shadbala = _topic_shadbala(chart, planet_name)
        rows.append([
            planet_name,
            _topic_sign_house_text(planet),
            (planet or {}).get("degree_str", ""),
            _career_nakshatra_text(planet),
            _topic_value(((planet or {}).get("dignity") or {}).get("essential")),
            _topic_value(shadbala.get("total_score")),
            _topic_value(shadbala.get("grade")),
            _topic_planet_varga_text(chart, "D7", planet_name),
            _topic_planet_varga_text(chart, "D12", planet_name),
        ])
    return rows


def _family_varga_status_rows(chart):
    rows = []
    for division in ["D1", "D7", "D12", "D9", "D4", "D60"]:
        varga = (chart.get("vargas") or {}).get(division) or {}
        rows.append([
            division,
            varga.get("name", ""),
            varga.get("confidence", "not_available"),
            _markdown_sign(varga.get("lagna") or {}) or "veri yok",
            varga.get("source_rule", ""),
            _varga_calculation_validation(varga, division).get("status", ""),
        ])
    return rows


def _family_active_dasha_rows(chart):
    return [
        [
            level,
            _topic_value(lord),
            _topic_sign_house_text(_topic_planet(chart, lord)),
            _career_lordship_houses(chart, lord),
            _topic_planet_varga_text(chart, "D7", lord),
            _topic_planet_varga_text(chart, "D12", lord),
        ]
        for level, lord in _topic_active_dasha_lords(chart)
    ]


def _family_timing_rows(life_period, event_type):
    timing = life_period.get("family_timing_evidence_v1", {})
    return [
        [
            rank,
            row.get("start_date"),
            row.get("end_date"),
            " > ".join(row.get("dasha_path", [])),
            row.get("activation_score"),
            ", ".join(row.get("independent_layers", [])),
            "; ".join(
                item.get("code", "")
                for item in row.get("evidence", [])[:5]
            ),
            row.get("status"),
            row.get("interpretation_limit"),
        ]
        for rank, row in enumerate(
            (timing.get("rankings") or {}).get(event_type, []),
            start=1,
        )
    ]


def _family_timing_markdown(life_period):
    timing = life_period.get("family_timing_evidence_v1", {})
    if not timing:
        return "\n".join([
            "## Aile Olay Zamanlama Kanıtı v1",
            "",
            "- Durum: not_available",
            "- Not: family_timing_evidence_v1 teknik tablosu üretilemedi.",
        ])

    labels = {
        "family_expansion_parenthood": "Aile Genişlemesi ve Ebeveynlik Bağlamı",
        "childbirth_context": "Çocuk Doğumu Bağlamı",
        "family_restructuring": "Ev / Aile Düzeninde Yeniden Yapılanma",
        "parental_care_responsibility": "Ebeveyn Sorumluluğu ve Bakım Yükü",
        "family_separation_distance": "Aileden Ayrışma veya Uzaklaşma",
        "family_loss_grief_context": "Aile Kaybı / Yas Bağlamı",
    }
    sections = [
        "## Aile Olay Zamanlama Kanıtı v1",
        "",
        "- Bu bölüm gerçekleşmiş veya gerçekleşecek aile olayı hükmü üretmez.",
        "- Gerçek yaşam olayları hesaplama girdisi olarak kullanılmamıştır.",
        "- Altı olay türü birbirinden bağımsız puanlanır.",
        "- Kayıp/yas bağlamı ölüm, kişi veya ölüm tarihi tahmini değildir.",
        "- Çocuk doğumu bağlamı gebelik, doğum, çocuk sayısı veya cinsiyeti kanıtlamaz.",
        f"- Method: {timing.get('method', '')}",
        f"- Yetişkin sıralama alt sınırı: {timing.get('ranking_min_age', '')} yaş",
        "- D7 ve D12 ana; D9, D4 ve D60 destekleyici vargalardır. Yorum güvenleri doğum saati beyanı politikasından gelir.",
    ]
    for event_type in FAMILY_EVENT_TYPE_CONFIG:
        sections.extend([
            "",
            f"### {labels[event_type]}",
            "",
            _markdown_table(
                [
                    "Sıra",
                    "Başlangıç",
                    "Bitiş",
                    "Dasha Yolu",
                    "Aktivasyon",
                    "Katmanlar",
                    "İlk Kanıtlar",
                    "Durum",
                    "Yorum Sınırı",
                ],
                _family_timing_rows(life_period, event_type),
            ),
        ])
    return "\n".join(sections)


def _build_family_analysis_data_package_markdown(
    chart,
    person_name,
    group_name,
    transit_pack=None,
):
    file_modified_at = datetime.now().astimezone().isoformat(timespec="seconds")
    title = f"{person_name} - Aile ve Ebeveynlik Analizi Veri Paketi"
    data_quality = chart.get("data_quality") or {}
    life_period = chart.get("life_period_analysis") or {}
    if not life_period.get("family_timing_evidence_v1"):
        life_period = _build_life_period_analysis_for_chart(chart)
    return "\n".join([
        "---",
        f'title: "{title}"',
        'type: "analysis_data_package"',
        'topic: "family_parenthood_loss_context"',
        f'person: "{person_name}"',
        f'group: "{group_name}"',
        'source: "api_v2_family_package"',
        'usage: "GPT sohbetine ekle"',
        f'modified: "{file_modified_at}"',
        "---",
        "",
        f"# {title}",
        "",
        "Sohbete ekle.",
        "",
        package_contract_markdown("P06-CHI"),
        "",
        package_data_gate_markdown(chart, "P06-CHI"),
        "",
        package_surface_audit_markdown(chart, "P06-CHI"),
        "",
        package_counter_evidence_markdown(chart, "P06-CHI"),
        "",
        "## Kullanım Sınırı",
        "",
        "- Bu paket teknik astrolojik kanıt içerir; aile olayı veya kayıp tahmini üretmez.",
        "- Ölüm, ölecek kişi, ölüm tarihi, gebelik, doğum sonucu, çocuk sayısı veya cinsiyeti çıkarılamaz.",
        "- Aile kaybı/yas göstergeleri taşınma, ayrışma ve aile düzeni değişimiyle karışabilir.",
        f"- Lagna/ev yorum güveni: {data_quality.get('house_interpretation_confidence', '')}",
        f"- Saat politikası: {data_quality.get('interpretation_policy', '')}",
        "",
        "## Hesap Bilgileri",
        "",
        _markdown_table(
            ["Alan", "Değer"],
            _career_identity_rows(chart, person_name, group_name),
        ),
        "",
        _active_transit_source_markdown(transit_pack),
        "",
        "## D1 Aile ve Ebeveynlik Evleri",
        "",
        _markdown_table(
            ["Ev", "Burç", "Lord", "Gezegenler", "Graha Drishti", "Rashi Drishti", "SAV"],
            _family_house_rows(chart),
        ),
        "",
        "## D1 Aile Ev Lordları",
        "",
        _markdown_table(
            ["Ev", "Lord", "D1 Konum", "Derece", "Nakshatra", "Dignity", "D7", "D12", "D4"],
            _family_lord_rows(chart),
        ),
        "",
        "## Aile Göstergesi Gezegenler",
        "",
        _markdown_table(
            ["Gezegen", "D1 Konum", "Derece", "Nakshatra", "Dignity", "Shadbala", "Seviye", "D7", "D12"],
            _family_planet_rows(chart),
        ),
        "",
        "## Aile Varga Durumu",
        "",
        _markdown_table(
            ["Varga", "Ad", "Güven", "Lagna", "Source Rule", "Dış Doğrulama"],
            _family_varga_status_rows(chart),
        ),
        "",
        "### D7 Saptamsha Full Tablo",
        "",
        _markdown_table(["Nokta", "Burç", "Derece"], _expert_varga_rows(chart, "D7")),
        "",
        "### D12 Dwadashamsha Full Tablo",
        "",
        _markdown_table(["Nokta", "Burç", "Derece"], _expert_varga_rows(chart, "D12")),
        "",
        "### D4 Chaturthamsha Destek Tablosu",
        "",
        _markdown_table(["Nokta", "Burç", "Derece"], _expert_varga_rows(chart, "D4")),
        "",
        "### D9 Navamsha Genel Teyit Tablosu",
        "",
        "- D9 aile için ana varga değildir; D7/D12 ile çelişirse D7/D12 esas alınır.",
        "- Haritanın genel dayanıklılığını teyit amaçlı okunur.",
        "- Çocuk sayısı, cinsiyeti veya gebelik sonucu bu tablodan çıkarılamaz.",
        "",
        _markdown_table(["Nokta", "Burç", "Derece"], _expert_varga_rows(chart, "D9")),
        "",
        "## Aktif Vimshottari Aile Bağlantısı",
        "",
        _markdown_table(
            ["Seviye", "Lord", "D1 Konum", "Yönettiği Evler", "D7", "D12"],
            _family_active_dasha_rows(chart),
        ),
        "",
        _family_timing_markdown(life_period),
        "",
    ])


def _save_family_analysis_data_package(
    chart,
    person_name,
    group_name,
    transit_pack=None,
):
    path = _person_analysis_package_path(
        group_name,
        person_name,
        "Aile ve Ebeveynlik Analizi Veri Paketi",
    )
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        _build_family_analysis_data_package_markdown(
            chart,
            person_name,
            group_name,
            transit_pack=transit_pack,
        ),
        encoding="utf-8",
    )
    return path


