def _varshaphala_domain_rows(chart):
    varsha = chart.get("varshaphala") or {}
    annual_planets = {
        row.get("name"): row
        for row in varsha.get("planets", [])
    }
    muntha_house = (
        (varsha.get("muntha") or {}).get("house_from_varsha_lagna")
    )
    selected = (varsha.get("year_lord") or {}).get("selected") or {}
    active_mudda = (varsha.get("mudda_dasha") or {}).get("active") or {}
    rows = []
    for key, config in VARSHA_DOMAIN_CONFIG.items():
        houses = set(config["houses"])
        indicators = set(config["planets"])
        evidence = []
        score = 0.0
        placements = []
        for planet_name in config["planets"]:
            planet = annual_planets.get(planet_name) or {}
            house = planet.get("house")
            if house not in houses:
                continue
            placements.append(f"{planet_name}:ev {house}")
            score += 0.75
            evidence.append(f"annual_{planet_name}_house_{house}")
        if muntha_house in houses:
            score += 0.8
            evidence.append(f"muntha_house_{muntha_house}")
        year_lord = selected.get("planet")
        if year_lord in indicators:
            score += 0.6
            evidence.append(f"year_lord_{year_lord}")
        if selected.get("annual_house") in houses:
            score += 0.45
            evidence.append(
                f"year_lord_house_{selected.get('annual_house')}"
            )
        mudda_lord = active_mudda.get("lord")
        if mudda_lord in indicators:
            score += 0.4
            evidence.append(f"active_mudda_{mudda_lord}")
        rows.append([
            config["label"],
            ", ".join(str(house) for house in config["houses"]),
            ", ".join(placements) or "doğrudan yerleşim yok",
            muntha_house if muntha_house in houses else "",
            year_lord if year_lord in indicators else "",
            mudda_lord if mudda_lord in indicators else "",
            round(score, 2),
            "; ".join(evidence) or "teknik eşleşme yok",
            config["interpretation_limit"],
        ])
    return rows


