def _legal_module_rows(chart):
    module = (
        (chart.get("analysis_modules") or {}).get("property_legal")
        or {}
    )
    return [
        ["Durum", module.get("status", "not_available")],
        ["Güven", module.get("confidence", "none")],
        ["Mevcut veri", ", ".join(module.get("available_data", []))],
        ["Eksik veri", ", ".join(module.get("missing_data", []))],
        ["Kanıt referansları", ", ".join(module.get("evidence_refs", []))],
        ["Güvenlik notları", ", ".join(module.get("safety_notes", []))],
    ]


def _legal_timing_rows(life_period, event_type):
    timing = life_period.get("legal_timing_evidence_v1", {})
    return [[
        rank,
        row.get("start_date"),
        row.get("end_date"),
        " > ".join(row.get("dasha_path", [])),
        row.get("activation_score"),
        ", ".join(row.get("independent_layers", [])),
        "; ".join(
            item.get("code", "")
            for item in row.get("evidence", [])[:5]
        ),
        row.get("interpretation_limit"),
    ] for rank, row in enumerate(
        (timing.get("rankings") or {}).get(event_type, []),
        start=1,
    )]


def _legal_timing_markdown(life_period):
    timing = life_period.get("legal_timing_evidence_v1", {})
    labels = {
        "contract_partnership": "Sözleşme ve Resmi Ortaklık Bağlamı",
        "dispute_litigation_context": "Uyuşmazlık ve Hukuki Süreç Bağlamı",
        "debt_liability_obligation": "Borç, Yükümlülük ve Sorumluluk Bağlamı",
        "inheritance_shared_assets": "Miras ve Paylaşılan Varlık Bağlamı",
        "official_institution_process": "Resmi Kurum ve Belgelendirme Süreci",
        "settlement_restructuring": "Uzlaşma ve Yükümlülük Yeniden Yapılanması",
    }
    sections = [
        "## Hukuki Süreç Zamanlama Kanıtı v1",
        "",
        "- Gerçek yaşam hukuki olayları hesaplama girdisi olarak kullanılmamıştır.",
        "- Altı hukuki bağlam birbirinden bağımsız puanlanır.",
        "- Aktivasyon puanı hukuki risk, kusur, kazanma/kaybetme veya sonuç ölçümü değildir.",
        "- Bu bölüm hukuki, finansal, vergi veya profesyonel tavsiye değildir.",
        f"- Method: {timing.get('method', '')}",
        "- D4 ve D30 destekleyici vargalardır. Yorum güvenleri doğum saati beyanı politikasından gelir.",
    ]
    for event_type in LEGAL_EVENT_TYPE_CONFIG:
        sections.extend([
            "",
            f"### {labels[event_type]}",
            "",
            _markdown_table(
                [
                    "Sıra",
                    "Başlangıç",
                    "Bitiş",
                    "Dasha Yolu",
                    "Aktivasyon",
                    "Katmanlar",
                    "İlk Kanıtlar",
                    "Yorum Sınırı",
                ],
                _legal_timing_rows(life_period, event_type),
            ),
        ])
    return "\n".join(sections)


