def _planet_role_rows(chart, planet_name):
    rows = []
    houses_by_number = {
        row.get("house"): row
        for row in chart.get("houses", [])
    }

    for house_key, lordship in (chart.get("lordships") or {}).items():
        if lordship.get("lord") != planet_name:
            continue
        house_number = int(house_key)
        house = houses_by_number.get(house_number) or {}
        rows.append([
            "birincil",
            "ev yöneticiliği",
            f"{house_number}. ev / {_markdown_sign(house)}",
            f"lordships.{house_key}",
        ])

    natural_karaka_houses = [
        house
        for house, karakas in HOUSE_KARAKAS.items()
        if planet_name in karakas
    ]
    if natural_karaka_houses:
        rows.append([
            "birincil",
            "doğal karaka",
            ", ".join(f"{house}. ev" for house in natural_karaka_houses),
            "houses[].karakas",
        ])

    chara_karakas = (chart.get("jaimini") or {}).get("chara_karakas") or {}
    for role in ["AK", "AmK", "BK", "MK", "PK", "GK", "DK"]:
        if (chara_karakas.get(role) or {}).get("planet") == planet_name:
            rows.append([
                "sistem özel",
                "Jaimini Chara Karaka",
                role,
                f"jaimini.chara_karakas.{role}",
            ])

    active = (
        (chart.get("dashas") or {})
        .get("vimshottari", {})
        .get("current_active")
        or {}
    )
    direct_levels = [
        level
        for level in DASHA_LEVELS
        if (active.get(level) or {}).get("lord") == planet_name
    ]
    if direct_levels:
        rows.append([
            "dönemsel",
            "aktif Vimshottari lordu",
            ", ".join(direct_levels),
            "dashas.vimshottari.current_active",
        ])

    return rows or [[
        "bağlamsal",
        "tanımlı rol",
        "Bu gezegen için seçili katmanlarda doğrudan rol bulunamadı.",
        "not_available",
    ]]


def _planet_package_name_matches(actual_name, planet_name):
    return _planet_name_matches(actual_name, planet_name)


def _planet_package_point(chart, planet_name):
    return next(
        (
            planet
            for planet in chart.get("planets", [])
            if _planet_package_name_matches(planet.get("name"), planet_name)
        ),
        None,
    )


def _planet_package_varga_point(chart, division, planet_name):
    return next(
        (
            planet
            for planet in (chart.get("vargas") or {}).get(division, {}).get("planets", [])
            if _planet_package_name_matches(planet.get("name"), planet_name)
        ),
        None,
    )


def _planet_natal_condition_rows(chart, planet_name):
    planet = _planet_package_point(chart, planet_name) or {}
    dignity = planet.get("dignity") or {}
    motion = planet.get("motion") or {}
    combustion = planet.get("combustion") or {}
    war = planet.get("war") or {}
    nakshatra = planet.get("nakshatra") or {}
    return [
        ["D1 konum", _topic_sign_house_text(planet), "planets[]"],
        ["Derece", planet.get("degree_str", ""), "planets[].degree_str"],
        [
            "Nakshatra",
            _career_nakshatra_text(planet),
            "planets[].nakshatra",
        ],
        ["Dignity", dignity.get("essential", ""), "planets[].dignity"],
        [
            "Hareket",
            "retrograde" if motion.get("retrograde") else motion.get("speed_status", "direct"),
            "planets[].motion",
        ],
        ["Combustion", combustion.get("severity", ""), "planets[].combustion"],
        ["Graha Yuddha", war.get("status", ""), "planets[].war"],
        [
            "Shadbala",
            _planet_role_shadbala_display(chart, planet_name),
            "shadbala.planets[]",
        ],
        [
            "Nakshatra lordu",
            nakshatra.get("lord", ""),
            "planets[].nakshatra.lord",
        ],
    ]


def _planet_role_shadbala_label(ratio):
    if ratio is None:
        return "veri yok"
    if ratio >= PLANET_ROLE_SHADBALA_RATIO_THRESHOLDS["strong"]:
        return "strong"
    if ratio >= PLANET_ROLE_SHADBALA_RATIO_THRESHOLDS["moderate"]:
        return "moderate"
    return "weak"


def _planet_role_shadbala_display(chart, planet_name):
    if _planet_package_name_matches(planet_name, "Rahu") or _planet_package_name_matches(
        planet_name,
        "Ketu",
    ):
        return "hesaplanmaz (gölge gezegen)"

    shadbala = _topic_shadbala(chart, planet_name)
    professional_total = shadbala.get("professional_total") or {}
    raw_total = shadbala.get("total_score")
    ratio = professional_total.get("strength_ratio")
    if raw_total is None or ratio is None:
        return "veri yok"
    return (
        f"{_topic_value(raw_total)} ham / "
        f"{float(ratio):.4f} oran / "
        f"{_planet_role_shadbala_label(float(ratio))}"
    )


def _planet_own_connection_rows(chart, planet_name):
    planet = _planet_package_point(chart, planet_name) or {}
    sign_lord = SIGN_LORDS.get(planet.get("sign_index"))
    nakshatra_lord = (planet.get("nakshatra") or {}).get("lord")
    sign_lord_planet = _planet_package_point(chart, sign_lord) or {}
    nakshatra_lord_planet = _planet_package_point(chart, nakshatra_lord) or {}
    return [
        [
            "burç dispozitörü",
            _planet_package_label(sign_lord),
            _topic_sign_house_text(sign_lord_planet),
            "SIGN_LORDS + planets[]",
        ],
        [
            "nakshatra lordu",
            _planet_package_label(nakshatra_lord),
            _topic_sign_house_text(nakshatra_lord_planet),
            "planets[].nakshatra.lord + planets[]",
        ],
    ]


def _planet_dispositor_rows(chart, planet_name):
    rows = []
    for planet in chart.get("planets", []):
        subject = planet.get("name")
        if _planet_package_name_matches(subject, planet_name):
            continue
        if SIGN_LORDS.get(planet.get("sign_index")) == planet_name:
            rows.append([
                subject,
                "burç dispozitörü",
                _topic_sign_house_text(planet),
                f"planets.{planet.get('id')}.sign",
            ])
        if (planet.get("nakshatra") or {}).get("lord") == planet_name:
            rows.append([
                subject,
                "nakshatra lordu",
                _career_nakshatra_text(planet),
                f"planets.{planet.get('id')}.nakshatra",
            ])
    return rows or [[
        "",
        "bağlantı yok",
        "Bu haritada doğrudan dispozitör veya nakshatra lordluğu bağlantısı yok.",
        "not_available",
    ]]


def _planet_aspect_rows(chart, planet_name):
    rows = []
    aspect_layers = [
        ("Graha Drishti", "graha_drishti"),
        ("Rashi Drishti", "rashi_drishti"),
    ]
    for layer_label, layer_key in aspect_layers:
        aspects = (chart.get("aspects") or {}).get(layer_key) or []
        for index, aspect in enumerate(aspects):
            if aspect.get("from") == planet_name:
                rows.append([
                    layer_label,
                    "yaptığı",
                    f"{aspect.get('to_house')}. ev / {aspect.get('to_sign')}",
                    ", ".join(aspect.get("to_planets") or []),
                    aspect.get("aspect_type", ""),
                    f"aspects.{layer_key}.{index}",
                ])
            elif any(
                _planet_package_name_matches(target, planet_name)
                for target in (aspect.get("to_planets") or [])
            ):
                rows.append([
                    layer_label,
                    "aldığı",
                    f"{aspect.get('from_house')}. ev / {aspect.get('from_sign')}",
                    aspect.get("from", ""),
                    aspect.get("aspect_type", ""),
                    f"aspects.{layer_key}.{index}",
                ])
    return rows or [[
        "açı yok",
        "",
        "",
        "",
        "",
        "not_available",
    ]]


def _planet_varga_rows(chart, planet_name):
    rows = []
    for division, _varga in sorted(
        (chart.get("vargas") or {}).items(),
        key=lambda item: int(item[0][1:]) if item[0][1:].isdigit() else 999,
    ):
        planet = _planet_package_varga_point(chart, division, planet_name)
        if not planet:
            continue
        house = _topic_house_from_varga_lagna(
            chart,
            division,
            planet.get("sign_index"),
        )
        rows.append([
            division,
            _markdown_sign(planet),
            house,
            planet.get("degree_str", ""),
            f"vargas.{division}.planets.{planet.get('id')}",
        ])
    return rows


def _planet_dasha_activation_rows(chart, planet_name):
    active = (
        (chart.get("dashas") or {})
        .get("vimshottari", {})
        .get("current_active")
        or {}
    )
    rows = []
    for level in DASHA_LEVELS:
        period = active.get(level) or {}
        if isinstance(period, str):
            period = {"lord": period, "path": [period]}
        path = period.get("path") or []
        if planet_name not in path:
            continue
        rows.append([
            level,
            period.get("lord", ""),
            "doğrudan lord" if period.get("lord") == planet_name else "üst dönem zinciri",
            period.get("start", ""),
            period.get("end", ""),
            " > ".join(path),
            f"dashas.vimshottari.current_active.{level}",
        ])
    return rows or [[
        "",
        "",
        "aktif zincirde değil",
        "",
        "",
        "",
        "dashas.vimshottari.current_active",
    ]]


def _planet_kp_rows(chart, planet_name):
    significator = next(
        (
            row
            for row in (
                (chart.get("kp") or {})
                .get("significators", {})
                .get("planet_significators", [])
            )
            if row.get("planet") == planet_name
        ),
        {},
    )
    return [
        [
            row.get("house"),
            row.get("score"),
            ", ".join(
                source.get("source", "")
                for source in row.get("sources", [])
            ),
            "kp.significators.planet_significators",
        ]
        for row in significator.get("ranked_houses", [])
    ] or [[
        "",
        "",
        "KP göstergesi yok",
        "not_available",
    ]]


def _planet_package_label(planet_name):
    return next(
        (
            planet_label
            for package_name, planet_label in PLANET_ROLE_PACKAGE_ORDER
            if _planet_package_name_matches(package_name, planet_name)
        ),
        planet_name,
    )


def _planet_house_role_text(chart, planet_name):
    role_rows = [
        row
        for row in _planet_role_rows(chart, planet_name)
        if row[3] != "not_available"
    ]
    return "; ".join(
        f"{row[1]}: {row[2]}"
        for row in role_rows
    ) or "seçili katmanlarda doğrudan rol yok"


def _planet_chara_role_text(chart, planet_name):
    chara_karakas = (chart.get("jaimini") or {}).get("chara_karakas") or {}
    roles = []
    for role, karaka in chara_karakas.items():
        karaka_planet = (
            (karaka or {}).get("planet")
            if isinstance(karaka, dict)
            else karaka
        )
        if _planet_package_name_matches(karaka_planet, planet_name):
            roles.append(role)
    return ", ".join(roles) or "Jaimini karaka rolü yok"


def _planet_drishti_summary(chart, planet_name, layer_key):
    aspects = (chart.get("aspects") or {}).get(layer_key) or []
    given = []
    received = []
    for aspect in aspects:
        if aspect.get("from") == planet_name:
            targets = []
            to_house = aspect.get("to_house")
            to_sign = aspect.get("to_sign")
            if to_house:
                targets.append(f"{to_house}. ev / {to_sign}")
            target_planets = aspect.get("to_planets") or []
            if target_planets:
                targets.append(
                    "gezegen: " + ", ".join(
                        _planet_package_label(target)
                        for target in target_planets
                    )
                )
            given.append(
                f"{aspect.get('aspect_type', '')} -> "
                + "; ".join(targets)
            )
        elif any(
            _planet_package_name_matches(target, planet_name)
            for target in (aspect.get("to_planets") or [])
        ):
            received.append(
                f"{_planet_package_label(aspect.get('from'))} "
                f"({aspect.get('from_house')}. ev / {aspect.get('from_sign')}, "
                f"{aspect.get('aspect_type', '')})"
            )
    return given, received


def _planet_top_kp_house_text(chart, planet_name, limit=4):
    rows = [
        row
        for row in _planet_kp_rows(chart, planet_name)
        if row[0] not in {"", None}
    ][:limit]
    return "; ".join(
        f"{row[0]}. ev skor {_topic_value(row[1])}"
        for row in rows
    ) or "KP ev göstergesi yok"


def _planet_owned_house_numbers(chart, planet_name):
    houses = []
    for house_key, lordship in (chart.get("lordships") or {}).items():
        if lordship.get("lord") != planet_name:
            continue
        try:
            houses.append(int(house_key))
        except (TypeError, ValueError):
            continue
    return sorted(houses)


def _house_list_text(houses):
    clean_houses = [
        str(house)
        for house in houses
        if house not in {None, ""}
    ]
    return ", ".join(f"{house}. ev" for house in clean_houses) or "belirgin ev yok"


def _planet_drishti_house_numbers(chart, planet_name, layer_key):
    houses = []
    for aspect in (chart.get("aspects") or {}).get(layer_key) or []:
        if aspect.get("from") != planet_name:
            continue
        house = aspect.get("to_house")
        if house not in {None, ""}:
            houses.append(house)
    return houses


def _planet_activation_note(chart, planet_name):
    activation_rows = [
        row
        for row in _planet_dasha_activation_rows(chart, planet_name)
        if row[0]
    ]
    if not activation_rows:
        return (
            "Bu zincir natal/Jaimini omurga kanıtıdır; gezegen güncel "
            "Vimshottari zincirinde doğrudan görünmediği için tek başına "
            "güncel dönem aktivasyonu sayılmaz."
        )
    direct_rows = [
        row
        for row in activation_rows
        if row[2] == "doğrudan lord"
    ]
    if direct_rows:
        levels = ", ".join(row[0] for row in direct_rows)
        return (
            f"Bu zincir güncel Vimshottari içinde doğrudan aktiftir "
            f"({levels}). Natal rol ile dönemsel aktivasyon birlikte okunur."
        )
    levels = ", ".join(row[0] for row in activation_rows)
    return (
        f"Bu zincir güncel Vimshottari yolunda üst dönem bağıyla görünür "
        f"({levels}); doğrudan lordluk kadar güçlü değil, ama dönem bağlamına "
        "destek sinyali verir."
    )


def _planet_readable_chain_lines(chart, planet_name, planet_label):
    planet = _planet_package_point(chart, planet_name) or {}
    nakshatra = planet.get("nakshatra") or {}
    nakshatra_lord = nakshatra.get("lord")
    nakshatra_lord_planet = (
        _planet_package_point(chart, nakshatra_lord)
        if nakshatra_lord
        else None
    ) or {}
    sign_lord = SIGN_LORDS.get(planet.get("sign_index"))
    sign_lord_planet = (
        _planet_package_point(chart, sign_lord)
        if sign_lord
        else None
    ) or {}
    graha_given, graha_received = _planet_drishti_summary(
        chart,
        planet_name,
        "graha_drishti",
    )
    rashi_given, rashi_received = _planet_drishti_summary(
        chart,
        planet_name,
        "rashi_drishti",
    )
    owned_houses = _planet_owned_house_numbers(chart, planet_name)
    graha_houses = _planet_drishti_house_numbers(
        chart,
        planet_name,
        "graha_drishti",
    )
    rashi_houses = _planet_drishti_house_numbers(
        chart,
        planet_name,
        "rashi_drishti",
    )
    linked_houses = []
    for house in [
        *owned_houses,
        planet.get("house"),
        nakshatra_lord_planet.get("house"),
        sign_lord_planet.get("house"),
        *graha_houses,
        *rashi_houses,
    ]:
        if house not in {None, ""} and house not in linked_houses:
            linked_houses.append(house)

    activation_note = _planet_activation_note(chart, planet_name)
    graha_text = (
        "yaptığı: "
        + ("; ".join(graha_given) if graha_given else "yok")
        + "; aldığı: "
        + ("; ".join(graha_received) if graha_received else "yok")
    )
    rashi_text = (
        "yaptığı: "
        + ("; ".join(rashi_given) if rashi_given else "yok")
        + "; aldığı: "
        + ("; ".join(rashi_received) if rashi_received else "yok")
    )
    nakshatra_name = nakshatra.get("name") or "nakshatra verisi yok"
    nakshatra_lord_label = _planet_package_label(nakshatra_lord)
    sign_lord_label = _planet_package_label(sign_lord)

    return [
        f"- {planet_label} = {_planet_house_role_text(chart, planet_name)}.",
        f"- {planet_label} D1'de {_topic_sign_house_text(planet)}.",
        (
            f"- {planet_label}'in nakshatrası {nakshatra_name}; "
            f"nakshatra lordu {nakshatra_lord_label}."
        ),
        (
            f"- Nakshatra lordu {nakshatra_lord_label} D1'de "
            f"{_topic_sign_house_text(nakshatra_lord_planet)}; "
            f"Jaimini rolü: {_planet_chara_role_text(chart, nakshatra_lord)}."
        ),
        (
            f"- Burç dispozitörü {sign_lord_label}; D1 konumu "
            f"{_topic_sign_house_text(sign_lord_planet)}; "
            f"Jaimini rolü: {_planet_chara_role_text(chart, sign_lord)}."
        ),
        f"- Graha drishti: {graha_text}.",
        f"- Rashi drishti: {rashi_text}.",
        (
            f"- Kısa yorum: Bu zincir {planet_label} temasını "
            f"{_house_list_text(linked_houses)} hattına bağlar. "
            "Nakshatra lordu gezegenin çalışma kapısını, dispozitör ise "
            "sonuç üretme filtresini gösterir."
        ),
        f"- Aktivasyon notu: {activation_note}",
    ]


