def _save_planet_role_activation_package(
    chart,
    person_name,
    group_name,
    transit_pack=None,
):
    planets_path = _person_analysis_package_path(
        group_name,
        person_name,
        "Gezegen Rol ve Aktivasyon Veri Paketi",
    )
    planets_path.parent.mkdir(parents=True, exist_ok=True)
    planets_path.write_text(
        _build_planet_role_activation_package_markdown(
            chart,
            person_name,
            group_name,
            transit_pack=transit_pack,
        ),
        encoding="utf-8",
    )

    legacy_paths = [
        _analysis_data_package_path(
            group_name,
            person_name,
            "Gezegen Rol ve Aktivasyon Veri Paketi",
            extension="txt",
        ),
        _analysis_data_package_path(
            group_name,
            person_name,
            "Gezegen Rol ve Aktivasyon Veri Paketi",
        ),
        _analysis_data_package_path(
            group_name,
            person_name,
            "Satürn Rol ve Aktivasyon Veri Paketi",
        ),
    ]
    for legacy_path in legacy_paths:
        if legacy_path.exists():
            legacy_path.unlink()

    return planets_path


