def _session_transit_change_rows(transit_pack):
    days = (transit_pack or {}).get("days") or []
    if not days:
        return [["", "Transit değişim özeti mevcut değil", "", "", ""]]

    rows = []
    previous = days[0]
    previous_path = previous.get("active_dasha_path") or []
    slow_planets = ["Saturn", "Jupiter", "Rahu (True)", "Ketu"]

    for day in days[1:]:
        current_path = day.get("active_dasha_path") or []
        if current_path != previous_path:
            rows.append([
                day.get("date"),
                "Vimshottari yolu",
                " > ".join(previous_path),
                " > ".join(current_path),
                "transit_pack.days[].active_dasha_path",
            ])

        for planet_name in slow_planets:
            previous_planet = _transit_pack_planet(previous, planet_name)
            current_planet = _transit_pack_planet(day, planet_name)
            if not previous_planet or not current_planet:
                continue
            previous_state = (
                previous_planet.get("sign"),
                bool(previous_planet.get("retrograde")),
            )
            current_state = (
                current_planet.get("sign"),
                bool(current_planet.get("retrograde")),
            )
            if current_state == previous_state:
                continue
            old_label = (
                f"{previous_planet.get('sign')}"
                f"{' R' if previous_planet.get('retrograde') else ''}"
            )
            new_label = (
                f"{current_planet.get('sign')}"
                f"{' R' if current_planet.get('retrograde') else ''}"
            )
            rows.append([
                day.get("date"),
                planet_name,
                old_label,
                new_label,
                "transit_pack.days[].planets[]",
            ])

        previous = day
        previous_path = current_path

    return rows or [[
        days[0].get("date"),
        "Teknik değişim",
        "",
        "Bu transit aralığında seçili değişim türü bulunmadı.",
        "transit_pack.days[]",
    ]]


