def _rectification_session_review_flags(rectification_record):
    if not rectification_record:
        return []

    flags = []
    search_window = rectification_record.get("search_window") or {}
    start_time = search_window.get("start_time")
    end_time = search_window.get("end_time")
    if start_time and end_time and str(start_time) == str(end_time):
        flags.append("single_candidate_window_no_real_scan")

    source_docs = rectification_record.get("source_docs") or []
    if not source_docs:
        flags.append("source_docs_missing")

    events = rectification_record.get("events") or []
    documented_count = sum(1 for event in events if event.get("documented"))
    if documented_count < 3:
        flags.append("documented_events_below_threshold")

    birth_window = rectification_record.get("birth_window") or {}
    source_quality = birth_window.get("source_quality")
    if source_quality and source_quality not in {"gold", "silver"}:
        flags.append("birth_window_source_quality_low_or_unknown")

    return flags


def _session_rectification_status_label(chart, rectification_record):
    birth = chart.get("birth") or {}
    explicit_status = birth.get("rectification_status")
    if not rectification_record:
        return explicit_status or "kayıt yok"

    v1_status = (
        rectification_record.get("rectification_v1_status")
        or (
            (rectification_record.get("rectification_decision") or {})
            .get("product_status")
        )
        or {}
    )
    v1_code = v1_status.get("code")
    if v1_code:
        return {
            "review_candidate_available": "aday saat incelemede",
            "candidate_window_available": "aday pencere var",
            "ambiguous_candidates": "adaylar yakın",
            "insufficient_data": "inceleme gerekli",
            "final_selection_blocked": "seçim kapalı",
        }.get(v1_code, v1_status.get("label_tr") or "inceleme gerekli")

    review_flags = _rectification_session_review_flags(rectification_record)
    if review_flags:
        return "inceleme gerekli"

    if explicit_status == "yapıldı" or birth.get("time_confidence") == "rectified":
        return "aday saat incelemede"
    return "aday pencere var"


