def _save_analysis_data_packages(
    chart,
    person_name,
    group_name,
    rectification_record=None,
    transit_pack=None,
):
    active_transit_pack = transit_pack
    if not active_transit_pack:
        active_transit_pack = _latest_saved_transit_pack(
            group_name,
            person_name,
            "three_month",
        )
    # --- hiz yamasi: life_period_analysis tek kez hesaplanir ---
    _lp_yedek = chart.get("life_period_analysis")
    _lp_mevcut = _lp_yedek or {}
    if not _lp_mevcut.get("education_timing_evidence_v1"):
        chart["life_period_analysis"] = _build_life_period_analysis_for_chart(chart)
    # --- hiz yamasi sonu ---
    career_path = _save_career_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    health_path = _save_health_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    family_path = _save_family_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    education_path = _save_education_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    relocation_path = _save_relocation_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    finance_path = _save_finance_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    relationship_path = _save_relationship_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    character_path = _save_character_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    spiritual_path = _save_spiritual_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    varshaphala_path = _save_varshaphala_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    legal_path = _save_legal_analysis_data_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    planets_path = _save_planet_role_activation_package(
        chart,
        person_name,
        group_name,
        transit_pack=active_transit_pack,
    )
    session_path = _save_session_preparation_package(
        chart,
        person_name,
        group_name,
        rectification_record=rectification_record,
        transit_pack=active_transit_pack,
    )
    # --- hiz yamasi: chart eski haline dondurulur ---
    if _lp_yedek is None:
        chart.pop("life_period_analysis", None)
    else:
        chart["life_period_analysis"] = _lp_yedek
    # --- hiz yamasi sonu ---
    return {
        "career": career_path,
        "health": health_path,
        "family": family_path,
        "education": education_path,
        "relocation": relocation_path,
        "finance": finance_path,
        "relationship": relationship_path,
        "character": character_path,
        "spiritual": spiritual_path,
        "varshaphala": varshaphala_path,
        "legal": legal_path,
        "planets": planets_path,
        "session": session_path,
    }


