def _delete_rectification_record(person_name, group_name):
    root = _vault_astrology_root()
    person_path = _vault_person_path(group_name, person_name)
    legacy_path = _rectification_save_path(group_name, person_name)
    deleted = []

    if person_path.exists():
        _ensure_path_inside(root, person_path)
        text = person_path.read_text(encoding="utf-8")
        updated = _remove_rectification_embedded_section(text)
        if updated != text:
            person_path.write_text(updated, encoding="utf-8")
            deleted.append(f"{person_path}#life-events")

    _ensure_path_inside(root, legacy_path)
    if legacy_path.exists():
        legacy_path.unlink()
        deleted.append(str(legacy_path))

    if not deleted:
        return {
            "ok": False,
            "status": 404,
            "error": "Rektifikasyon kaydı bulunamadı",
            "deleted": [],
            "removed_dirs": [],
        }

    return {
        "ok": True,
        "status": 200,
        "deleted": deleted,
        "removed_dirs": _remove_empty_vault_dirs([person_path, legacy_path]),
    }


