def _life_character_transit_evidence(
    context,
    period,
    transit_payloads,
    rahu_ketu_timeline,
    dimension,
):
    config = CHARACTER_ACTIVATION_DIMENSION_CONFIG[dimension]
    houses = set(config["houses"])
    indicators = set(config["planets"])
    evidence = {}
    for payload in transit_payloads:
        planet_name = payload["planet"]
        for transit in payload.get("periods", []):
            if not _life_intersection(period, transit):
                continue
            direct_house = transit.get("house_from_lagna")
            if direct_house in houses:
                _life_health_add_evidence(
                    evidence,
                    f"transit_{planet_name}_direct_character_house_{direct_house}",
                    f"transit.{planet_name.lower()}",
                    0.55 if planet_name == "Saturn" else 0.45,
                    (
                        f"{planet_name} transits dimension-relevant D1 house "
                        f"{direct_house}"
                    ),
                )
            matched_aspects = sorted({
                row.get("house_from_lagna")
                for row in transit.get("vedic_aspects", [])
            } & houses)
            if matched_aspects:
                _life_health_add_evidence(
                    evidence,
                    f"transit_{planet_name}_aspects_character_houses",
                    f"transit.{planet_name.lower()}",
                    min(len(matched_aspects) * 0.2, 0.6),
                    (
                        f"{planet_name} aspects dimension-relevant D1 houses "
                        f"{matched_aspects}"
                    ),
                )
            for contact in transit.get("natal_planet_contacts", []):
                natal_name = contact.get("natal_planet")
                if natal_name not in indicators:
                    continue
                _life_health_add_evidence(
                    evidence,
                    (
                        f"transit_{planet_name}_"
                        f"{contact.get('contact_type')}_{natal_name}_{dimension}"
                    ),
                    f"transit.{planet_name.lower()}",
                    (
                        0.3
                        if contact.get("contact_type") == "same_sign"
                        else 0.15
                    ),
                    (
                        f"{planet_name} {contact.get('contact_type')} "
                        f"natal {natal_name}"
                    ),
                )
    for node_period in rahu_ketu_timeline.get("periods", []):
        if not _life_intersection(period, node_period):
            continue
        matched_houses = sorted({
            node_period.get("rahu_house_from_lagna"),
            node_period.get("ketu_house_from_lagna"),
        } & houses)
        if matched_houses:
            _life_health_add_evidence(
                evidence,
                f"transit_nodes_{dimension}_houses",
                "transit.rahu_ketu",
                min(len(matched_houses) * 0.3, 0.6),
                (
                    "Rahu-Ketu axis includes dimension-relevant D1 houses "
                    f"{matched_houses}"
                ),
            )
    return evidence


