def _life_legal_context(chart):
    context = _life_family_context(chart)
    for division in ["D10", "D30"]:
        lagna = _varga_lagna(chart, division)
        context["varga_planets"][division] = {
            planet["name"]: {
                **planet,
                "house": _house_from_lagna(
                    lagna["sign_index"],
                    planet["sign_index"],
                ),
            }
            for planet in (
                _varga_planet(row, division)
                for row in chart["planets"]
            )
        }
    return context


def _life_legal_path_evidence(context, path_lords, event_type):
    config = LEGAL_EVENT_TYPE_CONFIG[event_type]
    houses = set(config["houses"])
    indicators = set(config["planets"])
    weights = [0.35, 0.7, 1.1]
    varga_weights = {
        "D9": 0.4,
        "D10": 0.4,
        "D4": 0.25,
        "D30": 0.12,
    }
    evidence = {}
    for index, lord in enumerate(path_lords[:3]):
        level = ["maha", "antara", "pratyantar"][index]
        weight = weights[index]
        for house in sorted(
            set(context["owned_houses"].get(lord, [])) & houses
        ):
            _life_health_add_evidence(
                evidence,
                f"dasha_{level}_{lord}_owns_legal_house_{house}",
                f"vimshottari.{level}",
                weight * 0.45,
                f"{lord} owns context-relevant D1 house {house}",
            )
        d1_house = (context["planets"].get(lord) or {}).get("house")
        if d1_house in houses:
            _life_health_add_evidence(
                evidence,
                f"dasha_{level}_{lord}_d1_legal_house_{d1_house}",
                "D1",
                weight * 0.6,
                f"{lord} is placed in context-relevant D1 house {d1_house}",
            )
        if lord in indicators:
            _life_health_add_evidence(
                evidence,
                f"dasha_{level}_{lord}_{event_type}_indicator",
                f"vimshottari.{level}",
                weight * 0.55,
                f"{lord} is a technical indicator for {event_type}",
            )
        for division in config["vargas"]:
            if lord in {"Rahu", "Ketu"}:
                continue
            house = (
                context["varga_planets"]
                .get(division, {})
                .get(lord, {})
                .get("house")
            )
            if house in houses:
                _life_health_add_evidence(
                    evidence,
                    f"dasha_{level}_{lord}_{division.lower()}_legal_house_{house}",
                    division,
                    weight * varga_weights[division],
                    f"{lord} is placed in {division} house {house}",
                )
    return evidence


def _life_legal_timing_evidence(
    chart,
    dasha_timeline,
    transit_payloads,
    rahu_ketu_timeline,
    birth_jd,
):
    context = _life_legal_context(chart)
    rows = dasha_timeline.get("pratyantar", [])
    rankings = {}
    for event_type in LEGAL_EVENT_TYPE_CONFIG:
        scored = []
        for period in rows:
            age_start = _life_age_from_jd(period["start_jd"], birth_jd)
            if age_start < LEGAL_EVENT_RANKING_MIN_AGE:
                continue
            evidence = _life_legal_path_evidence(
                context,
                period.get("path") or [],
                event_type,
            )
            evidence.update(
                _life_family_transit_evidence(
                    context,
                    period,
                    transit_payloads,
                    rahu_ketu_timeline,
                    event_type,
                    event_type_config=LEGAL_EVENT_TYPE_CONFIG,
                )
            )
            ordered = sorted(
                evidence.values(),
                key=lambda item: (-item["contribution"], item["code"]),
            )
            scored.append({
                "start_date": period["start_date"],
                "end_date": period["end_date"],
                "age_start": age_start,
                "age_end": _life_age_from_jd(period["end_jd"], birth_jd),
                "dasha_path": period.get("path") or [],
                "precision": "pratyantar",
                "event_type": event_type,
                "activation_score": round(
                    sum(item["contribution"] for item in ordered),
                    2,
                ),
                "independent_layers": sorted({
                    item["layer"] for item in ordered
                }),
                "evidence": ordered,
                "status": "technical_candidate_not_prediction",
                "meaning": LEGAL_EVENT_TYPE_CONFIG[event_type]["meaning"],
                "interpretation_limit": (
                    LEGAL_EVENT_TYPE_CONFIG[event_type]
                    ["interpretation_limit"]
                ),
            })
        rankings[event_type] = sorted(
            scored,
            key=lambda item: (
                -item["activation_score"],
                -len(item["independent_layers"]),
                item["start_date"],
            ),
        )[:LEGAL_EVENT_RANKING_LIMIT]
    return {
        "status": "technical_evidence_only_not_legal_advice",
        "version": "v1",
        "method": (
            "vimshottari_d1_d9_d10_supporting_vargas_and_slow_transit_ranking"
        ),
        "known_life_events_used": False,
        "event_types": list(LEGAL_EVENT_TYPE_CONFIG),
        "event_type_guidance": LEGAL_EVENT_TYPE_CONFIG,
        "ranking_min_age": LEGAL_EVENT_RANKING_MIN_AGE,
        "rankings_limit_per_type": LEGAL_EVENT_RANKING_LIMIT,
        "precision": "pratyantar",
        "primary_vargas": ["D1", "D9", "D10"],
        "supporting_vargas": ["D4", "D30"],
        "rankings": rankings,
        "safety_notes": [
            "activation_score_is_not_probability_or_legal_risk_measurement",
            "technical_window_is_not_a_confirmed_legal_or_contract_event",
            "not_legal_financial_tax_or_professional_advice",
            "no_crime_fault_lawsuit_verdict_penalty_or_outcome_prediction_is_generated",
            "no_contract_validity_liability_inheritance_or_property_entitlement_is_generated",
            "d4_is_low_confidence_supporting_evidence",
            "d30_is_very_low_confidence_supporting_evidence",
            "rahu_ketu_varga_placements_are_excluded",
            "known_life_events_are_not_used",
        ],
    }


def _life_career_context(chart):
    lordships = _build_lordships(chart)
    vargas = {
        division: {
            "lagna": _varga_lagna(chart, division),
            "planets": [
                _varga_planet(planet, division)
                for planet in chart["planets"]
            ],
        }
        for division in ["D9", "D10", "D30"]
    }
    ranked_grahas = sorted(
        (
            planet for planet in chart["planets"]
            if planet["abbr"] in {"Su", "Mo", "Ma", "Me", "Ju", "Ve", "Sa"}
        ),
        key=lambda planet: (planet["degree"], planet["longitude"]),
        reverse=True,
    )
    amatyakaraka = _planet_name_en(ranked_grahas[1]) if len(ranked_grahas) > 1 else None
    owned_houses = {}
    for house_key, lordship in lordships.items():
        owned_houses.setdefault(lordship["lord"], []).append(int(house_key))

    varga_planets = {}
    for division, payload in vargas.items():
        lagna_sign_index = payload["lagna"]["sign_index"]
        varga_planets[division] = {
            planet["name"]: {
                **planet,
                "house": _house_from_lagna(lagna_sign_index, planet["sign_index"]),
            }
            for planet in payload["planets"]
        }

    return {
        "lordships": lordships,
        "owned_houses": owned_houses,
        "planets": _planet_index_by_name(chart),
        "varga_planets": varga_planets,
        "career_lord": lordships["10"]["lord"],
        "service_lord": lordships["6"]["lord"],
        "fortune_lord": lordships["9"]["lord"],
        "gain_lord": lordships["11"]["lord"],
        "amatyakaraka": amatyakaraka,
    }


def _life_career_neptune_targets(chart, context):
    targets = {}

    def add(layer, key, label, longitude, role):
        if longitude is None:
            return
        target_key = (layer, key)
        if target_key not in targets:
            targets[target_key] = {
                "layer": layer,
                "key": key,
                "label": label,
                "longitude": round(longitude % 360.0, 6),
                "roles": [],
            }
        if role not in targets[target_key]["roles"]:
            targets[target_key]["roles"].append(role)

    d1_lagna_longitude = chart["lagna"]["longitude"]
    add("D1", "lagna", "D1 Lagna", d1_lagna_longitude, "career_axis")
    add(
        "D1",
        "house_10_reference",
        "D1 10th-house reference point",
        d1_lagna_longitude + 270.0,
        "10th_house",
    )
    for planet_name, role in [
        (context["career_lord"], "10th_lord"),
        (context["service_lord"], "6th_lord"),
        (context["amatyakaraka"], "amatyakaraka"),
        ("Moon", "moon"),
        ("Saturn", "saturn"),
    ]:
        planet = context["planets"].get(planet_name)
        if planet:
            add(
                "D1",
                f"planet_{planet_name.lower()}",
                f"D1 {planet_name}",
                planet["longitude"],
                role,
            )

    d10_lagna = _varga_lagna(chart, "D10")
    d10_lagna_longitude = (
        d10_lagna["sign_index"] * 30.0 + d10_lagna["degree"]
    )
    add("D10", "lagna", "D10 Lagna", d10_lagna_longitude, "career_axis")
    add(
        "D10",
        "house_10_reference",
        "D10 10th-house reference point",
        d10_lagna_longitude + 270.0,
        "10th_house",
    )
    d10_tenth_sign = (d10_lagna["sign_index"] + 9) % 12
    d10_tenth_lord = SIGN_LORDS[d10_tenth_sign]
    for planet_name, role in [
        (d10_tenth_lord, "10th_lord"),
        (context["amatyakaraka"], "amatyakaraka"),
        ("Moon", "moon"),
        ("Saturn", "saturn"),
    ]:
        planet = context["varga_planets"]["D10"].get(planet_name)
        if planet:
            add(
                "D10",
                f"planet_{planet_name.lower()}",
                f"D10 {planet_name}",
                planet["sign_index"] * 30.0 + planet["degree"],
                role,
            )

    return sorted(
        targets.values(),
        key=lambda item: (item["layer"], item["key"]),
    )


def _life_career_neptune_evidence(chart, start_jd, end_jd, birth_jd):
    context = _life_career_context(chart)
    targets = _life_career_neptune_targets(chart, context)
    scan_start_jd = max(
        start_jd,
        birth_jd + CAREER_NEPTUNE_MIN_AGE * 365.25,
    )
    if scan_start_jd >= end_jd:
        processes = []
    else:
        active = {}
        segments = []
        probe_jd = scan_start_jd
        while probe_jd <= end_jd:
            position = _life_transit_position(swe.NEPTUNE, probe_jd)
            for target in targets:
                separation = _angular_distance(
                    position["longitude"],
                    target["longitude"],
                )
                for aspect_name, aspect in CAREER_NEPTUNE_ASPECTS.items():
                    orb = abs(separation - aspect["angle"])
                    contact_key = (target["layer"], target["key"], aspect_name)
                    current = active.get(contact_key)
                    if orb <= CAREER_NEPTUNE_ORB:
                        if current is None:
                            active[contact_key] = {
                                "start_jd": probe_jd,
                                "end_jd": probe_jd,
                                "closest_jd": probe_jd,
                                "closest_orb": orb,
                                "closest_retrograde": position["retrograde"],
                                "target": target,
                                "aspect_name": aspect_name,
                                "aspect": aspect,
                            }
                        else:
                            current["end_jd"] = probe_jd
                            if orb < current["closest_orb"]:
                                current["closest_jd"] = probe_jd
                                current["closest_orb"] = orb
                                current["closest_retrograde"] = position["retrograde"]
                    elif current is not None:
                        segments.append(active.pop(contact_key))
            probe_jd += 1.0
        segments.extend(active.values())

        grouped = {}
        for segment in sorted(
            segments,
            key=lambda item: (
                item["target"]["layer"],
                item["target"]["key"],
                item["aspect_name"],
                item["start_jd"],
            ),
        ):
            key = (
                segment["target"]["layer"],
                segment["target"]["key"],
                segment["aspect_name"],
            )
            grouped.setdefault(key, []).append(segment)

        processes = []
        for group in grouped.values():
            merged = []
            for segment in group:
                if (
                    merged
                    and segment["start_jd"] - merged[-1]["end_jd"]
                    <= CAREER_NEPTUNE_PROCESS_MERGE_GAP_DAYS
                ):
                    merged[-1]["end_jd"] = segment["end_jd"]
                    merged[-1]["passes"].append(segment)
                else:
                    merged.append({
                        "start_jd": segment["start_jd"],
                        "end_jd": segment["end_jd"],
                        "target": segment["target"],
                        "aspect_name": segment["aspect_name"],
                        "aspect": segment["aspect"],
                        "passes": [segment],
                    })

            for process in merged:
                closest = min(
                    process["passes"],
                    key=lambda item: item["closest_orb"],
                )
                exact_passes = [
                    {
                        "date": _life_iso_from_jd(item["closest_jd"]),
                        "orb": round(item["closest_orb"], 3),
                        "retrograde": item["closest_retrograde"],
                    }
                    for item in process["passes"]
                ]
                processes.append({
                    "start_date": _life_iso_from_jd(process["start_jd"]),
                    "end_date": _life_iso_from_jd(process["end_jd"]),
                    "age_start": _life_age_from_jd(
                        process["start_jd"],
                        birth_jd,
                    ),
                    "age_end": _life_age_from_jd(
                        process["end_jd"],
                        birth_jd,
                    ),
                    "layer": process["target"]["layer"],
                    "target": process["target"]["label"],
                    "target_roles": process["target"]["roles"],
                    "aspect": process["aspect_name"],
                    "aspect_angle": process["aspect"]["angle"],
                    "evidence_class": process["aspect"]["evidence_class"],
                    "orb_limit": CAREER_NEPTUNE_ORB,
                    "closest_orb": round(closest["closest_orb"], 3),
                    "repeat_count": len(exact_passes),
                    "exact_passes": exact_passes,
                    "status": "experimental_hybrid_evidence",
                    "interpretation_limit": (
                        "does_not_establish_event_type_employment_status_or_cause"
                    ),
                })

    ranked_processes = sorted(
        processes,
        key=lambda item: (
            item["evidence_class"] != "primary",
            -item["repeat_count"],
            item["closest_orb"],
            item["start_date"],
        ),
    )
    return {
        "status": "experimental_hybrid_evidence",
        "version": "v1",
        "method": "lahiri_sidereal_neptune_degree_aspects_to_d1_d10_career_points",
        "known_life_events_used": False,
        "affects_career_event_scores": False,
        "minimum_age": CAREER_NEPTUNE_MIN_AGE,
        "orb_limit": CAREER_NEPTUNE_ORB,
        "process_merge_gap_days": CAREER_NEPTUNE_PROCESS_MERGE_GAP_DAYS,
        "primary_aspects": ["conjunction", "square", "opposition"],
        "helper_aspects": ["sextile", "trine"],
        "targets": targets,
        "processes": sorted(processes, key=lambda item: item["start_date"]),
        "ranked_processes": ranked_processes,
        "safety_notes": [
            "modern_outer_planet_aspects_are_not_a_classical_vedic_layer",
            "d10_degree_aspects_are_experimental_hybrid_evidence",
            "retrograde_repetitions_are_merged_into_one_process",
            "neptune_evidence_does_not_change_career_event_scores",
            "known_life_events_are_not_used",
        ],
    }


def _life_career_direction(support_score, challenge_score):
    difference = round(support_score - challenge_score, 2)
    if (
        abs(difference) < 2.0
        or (support_score >= 2.5 and challenge_score >= 2.5)
    ):
        return {
            "status": "direction_uncertain",
            "lean": "mixed",
            "score_difference": difference,
        }
    if difference > 0:
        return {
            "status": "direction_leaning_not_event_prediction",
            "lean": "support",
            "score_difference": difference,
        }
    return {
        "status": "direction_leaning_not_event_prediction",
        "lean": "challenge",
        "score_difference": difference,
    }


def _life_career_event_candidates(activated_houses, path_lords, direction):
    houses = set(activated_houses)
    candidates = []
    if houses & {6, 10}:
        candidates.append("career_entry_or_work_activation")
    if houses & {3, 9} or set(path_lords) & {"Mercury", "Jupiter"}:
        candidates.append("specialization_or_training")
    if 10 in houses and (11 in houses or set(path_lords) & {"Sun", "Saturn"}):
        candidates.append("status_or_responsibility_change")
    if houses & {8, 12}:
        candidates.append("interruption_or_withdrawal")
    if direction["status"] == "direction_uncertain" or (
        houses & {6, 10, 11} and houses & {8, 12}
    ):
        candidates.append("career_restructuring")
    return list(dict.fromkeys(candidates)) or ["career_theme_activation"]


