def _life_career_event_factor_weights(code):
    weights = {key: 0.0 for key in CAREER_EVENT_TYPE_KEYS}

    if "_owns_6" in code or "_d1_house_6" in code or "_d10_house_6" in code:
        weights["career_entry"] += 1.0
        weights["specialization"] += 0.35
    if "_owns_10" in code or "_d1_house_10" in code or "_d10_house_10" in code:
        weights["career_entry"] += 0.8
        weights["status_change"] += 1.0
    if "_owns_11" in code or "_d1_house_11" in code or "_d10_house_11" in code:
        weights["status_change"] += 1.0
    if "_owns_9" in code or "_d1_house_9" in code or "_d9_house_9" in code or "_d10_house_9" in code:
        weights["specialization"] += 1.0
    if "_owns_3" in code or "_d1_house_3" in code:
        weights["specialization"] += 0.65
    if "_owns_1" in code or "_d1_house_1" in code or "_d10_house_1" in code:
        weights["career_entry"] += 0.35
        weights["status_change"] += 0.55
    if "_owns_2" in code or "_d1_house_2" in code or "_d10_house_2" in code:
        weights["status_change"] += 0.45
    if any(marker in code for marker in ["_owns_8", "_owns_12", "_d1_house_8", "_d1_house_12", "_d9_house_8", "_d9_house_12", "_d10_house_8", "_d10_house_12", "_d30_house_8", "_d30_house_12"]):
        weights["interruption"] += 1.0
        weights["restructuring"] += 0.8
    if "_d30_house_10" in code:
        weights["status_change"] += 0.4
        weights["restructuring"] += 0.55
    if code.endswith("_career_lord"):
        weights["career_entry"] += 0.75
        weights["status_change"] += 0.85
    if code.endswith("_amatyakaraka"):
        weights["specialization"] += 0.45
        weights["status_change"] += 0.75
    if "_nakshatra_" in code:
        weights["specialization"] += 0.45
    if code.endswith("_career_houses"):
        weights["career_entry"] += 0.65
        weights["status_change"] += 0.65
    if code.endswith("_career_contacts"):
        weights["status_change"] += 0.45
        weights["restructuring"] += 0.35
    if code.endswith("_challenge_houses") or code == "transit_nodes_transition_axis":
        weights["interruption"] += 0.8
        weights["restructuring"] += 0.7
    if code == "transit_nodes_career_axis":
        weights["status_change"] += 0.35
        weights["restructuring"] += 0.45

    return weights


def _life_career_event_type_scores(evidence, counter_evidence, path_lords):
    scores = {
        key: {
            "support_score": 0.0,
            "counter_score": 0.0,
            "evidence": [],
            "counter_evidence": [],
            "layers": set(),
        }
        for key in CAREER_EVENT_TYPE_KEYS
    }

    for item in evidence:
        for event_type, multiplier in _life_career_event_factor_weights(item["code"]).items():
            if multiplier <= 0:
                continue
            contribution = round(item["weight"] * multiplier, 2)
            scores[event_type]["support_score"] += contribution
            scores[event_type]["evidence"].append({
                "code": item["code"],
                "layer": item["layer"],
                "contribution": contribution,
            })
            scores[event_type]["layers"].add(item["layer"])
        for event_type in ["interruption", "restructuring"]:
            contribution = round(item["weight"] * 0.15, 2)
            scores[event_type]["counter_score"] += contribution

    for item in counter_evidence:
        weights = _life_career_event_factor_weights(item["code"])
        for event_type in ["interruption", "restructuring"]:
            multiplier = weights[event_type]
            if multiplier <= 0:
                continue
            contribution = round(item["weight"] * multiplier, 2)
            scores[event_type]["support_score"] += contribution
            scores[event_type]["evidence"].append({
                "code": item["code"],
                "layer": item["layer"],
                "contribution": contribution,
            })
            scores[event_type]["layers"].add(item["layer"])
        for event_type in ["career_entry", "status_change"]:
            contribution = round(item["weight"] * 0.65, 2)
            scores[event_type]["counter_score"] += contribution
            scores[event_type]["counter_evidence"].append({
                "code": item["code"],
                "layer": item["layer"],
                "contribution": contribution,
            })

    path_set = set(path_lords)
    path_rules = {
        "career_entry": ({"Venus", "Mercury", "Saturn"}, 0.6),
        "specialization": ({"Mercury", "Jupiter", "Mars"}, 0.75),
        "status_change": ({"Sun", "Saturn", "Venus"}, 0.7),
        "interruption": ({"Saturn", "Rahu", "Ketu"}, 0.55),
        "restructuring": ({"Saturn", "Rahu", "Ketu", "Mars"}, 0.65),
    }
    for event_type, (lords, weight) in path_rules.items():
        matched = sorted(path_set & lords)
        if not matched:
            continue
        contribution = round(weight * len(matched), 2)
        scores[event_type]["support_score"] += contribution
        scores[event_type]["evidence"].append({
            "code": f"dasha_path_lords_{'_'.join(matched)}",
            "layer": "vimshottari.path",
            "contribution": contribution,
        })
        scores[event_type]["layers"].add("vimshottari.path")

    result = {}
    for event_type, score in scores.items():
        support = round(score["support_score"], 2)
        counter = round(score["counter_score"], 2)
        net = round(support - counter, 2)
        if support < 1.5:
            status = "insufficient_evidence"
        elif counter >= 1.5:
            status = "mixed_evidence"
        else:
            status = "technical_candidate_not_prediction"
        result[event_type] = {
            "support_score": support,
            "counter_score": counter,
            "net_score": net,
            "status": status,
            "independent_layers": sorted(score["layers"]),
            "evidence": sorted(
                score["evidence"],
                key=lambda item: (-item["contribution"], item["code"]),
            ),
            "counter_evidence": sorted(
                score["counter_evidence"],
                key=lambda item: (-item["contribution"], item["code"]),
            ),
        }
    return result


def _life_career_event_rankings(rows):
    rankings = {}
    for event_type in CAREER_EVENT_TYPE_KEYS:
        candidates = [
            {
                "start_date": row["start_date"],
                "end_date": row["end_date"],
                "age_start": row["age_start"],
                "age_end": row["age_end"],
                "dasha_path": row["dasha_path"],
                "meaning": CAREER_EVENT_TYPE_GUIDANCE[event_type]["meaning"],
                "interpretation_limit": (
                    CAREER_EVENT_TYPE_GUIDANCE[event_type]["interpretation_limit"]
                ),
                **row["event_type_scores"][event_type],
            }
            for row in rows
            if (
                row["age_start"] >= CAREER_EVENT_RANKING_MIN_AGE
                and row["event_type_scores"][event_type]["status"]
                != "insufficient_evidence"
            )
        ]
        rankings[event_type] = sorted(
            candidates,
            key=lambda item: (
                -item["net_score"],
                -item["support_score"],
                item["start_date"],
            ),
        )[:6]
    return rankings


def _life_career_early_candidates(rows):
    candidates = []
    for row in rows:
        if not (
            CAREER_EARLY_CANDIDATE_MIN_AGE
            <= row["age_start"]
            < CAREER_EVENT_RANKING_MIN_AGE
        ):
            continue
        career_entry = row["event_type_scores"]["career_entry"]
        status_change = row["event_type_scores"]["status_change"]
        strongest_net = max(
            career_entry["net_score"],
            status_change["net_score"],
        )
        if strongest_net < CAREER_EARLY_CANDIDATE_MIN_NET:
            continue
        candidates.append({
            "start_date": row["start_date"],
            "end_date": row["end_date"],
            "age_start": row["age_start"],
            "age_end": row["age_end"],
            "dasha_path": row["dasha_path"],
            "career_entry_net": career_entry["net_score"],
            "status_change_net": status_change["net_score"],
            "strongest_net": strongest_net,
            "status": "early_career_candidate_not_prediction",
            "interpretation_limit": (
                "early_paid_work_training_service_or_role_activation_requires_"
                "external_validation"
            ),
        })
    return sorted(
        candidates,
        key=lambda item: (
            -item["strongest_net"],
            item["start_date"],
        ),
    )


def _life_career_local_turning_points(rows):
    forward_types = ("career_entry", "specialization", "status_change")
    transition_types = ("interruption", "restructuring")
    scored_rows = []

    for row in rows:
        forward_type = max(
            forward_types,
            key=lambda event_type: (
                row["event_type_scores"][event_type]["net_score"],
                event_type,
            ),
        )
        transition_type = max(
            transition_types,
            key=lambda event_type: (
                row["event_type_scores"][event_type]["net_score"],
                event_type,
            ),
        )
        forward_net = row["event_type_scores"][forward_type]["net_score"]
        transition_net = row["event_type_scores"][transition_type]["net_score"]
        scored_rows.append({
            "row": row,
            "forward_type": forward_type,
            "forward_net": forward_net,
            "transition_type": transition_type,
            "transition_net": transition_net,
            "combined_net": round(forward_net + transition_net, 2),
        })

    turning_points = []
    for index, item in enumerate(scored_rows):
        row = item["row"]
        if row["age_start"] < CAREER_EARLY_CANDIDATE_MIN_AGE:
            continue
        if (
            item["forward_net"] < CAREER_LOCAL_TURNING_POINT_MIN_NET
            or item["transition_net"] < CAREER_LOCAL_TURNING_POINT_MIN_NET
        ):
            continue
        previous_score = (
            scored_rows[index - 1]["combined_net"]
            if index > 0
            else float("-inf")
        )
        next_score = (
            scored_rows[index + 1]["combined_net"]
            if index + 1 < len(scored_rows)
            else float("-inf")
        )
        if item["combined_net"] < max(previous_score, next_score):
            continue
        turning_points.append({
            "start_date": row["start_date"],
            "end_date": row["end_date"],
            "age_start": row["age_start"],
            "age_end": row["age_end"],
            "dasha_path": row["dasha_path"],
            "forward_type": item["forward_type"],
            "forward_net": item["forward_net"],
            "transition_type": item["transition_type"],
            "transition_net": item["transition_net"],
            "combined_net": item["combined_net"],
            "status": "local_mixed_direction_turning_point_not_prediction",
            "interpretation_limit": (
                "a_new_direction_and_an_interruption_or_restructuring_may_coexist"
            ),
        })
    return turning_points


def _life_career_timing_evidence(
    chart,
    dasha_timeline,
    transit_payloads,
    rahu_ketu_timeline,
    birth_jd,
):
    context = _life_career_context(chart)
    support_houses = {1, 2, 6, 9, 10, 11}
    challenge_houses = {8, 12}
    career_planets = {
        context["career_lord"],
        context["service_lord"],
        context["fortune_lord"],
        context["gain_lord"],
        context["amatyakaraka"],
        "Saturn",
        "Mars",
        "Mercury",
    } - {None}
    rows = []

    for period in dasha_timeline.get("pratyantar", []):
        evidence = {}
        counter_evidence = {}
        activated_houses = set()
        layers = set()
        path_lords = period.get("path") or []

        def add(target, code, layer, weight, detail):
            existing = target.get(code)
            if existing and existing["weight"] >= weight:
                return
            target[code] = {
                "code": code,
                "layer": layer,
                "weight": round(weight, 2),
                "detail": detail,
            }
            layers.add(layer)

        for level_index, lord in enumerate(path_lords):
            level = ["maha", "antara", "pratyantar"][min(level_index, 2)]
            level_weight = [0.75, 1.0, 1.5][min(level_index, 2)]
            owned = set(context["owned_houses"].get(lord, []))
            activated_houses.update(owned)
            for house in sorted(owned & support_houses):
                add(
                    evidence,
                    f"dasha_{level}_{lord}_owns_{house}",
                    f"vimshottari.{level}",
                    level_weight,
                    f"{lord} owns career-support house {house}",
                )
            for house in sorted(owned & challenge_houses):
                add(
                    counter_evidence,
                    f"dasha_{level}_{lord}_owns_{house}",
                    f"vimshottari.{level}",
                    level_weight,
                    f"{lord} owns transition/withdrawal house {house}",
                )

            planet = context["planets"].get(lord)
            if planet:
                d1_house = planet["house"]
                activated_houses.add(d1_house)
                if d1_house in support_houses:
                    add(
                        evidence,
                        f"dasha_{level}_{lord}_d1_house_{d1_house}",
                        "D1",
                        level_weight,
                        f"{lord} is placed in D1 house {d1_house}",
                    )
                elif d1_house in challenge_houses:
                    add(
                        counter_evidence,
                        f"dasha_{level}_{lord}_d1_house_{d1_house}",
                        "D1",
                        level_weight,
                        f"{lord} is placed in D1 house {d1_house}",
                    )
                nakshatra_lord = planet.get("nakshatra", {}).get("lord")
                if nakshatra_lord in career_planets:
                    add(
                        evidence,
                        f"dasha_{level}_{lord}_nakshatra_{nakshatra_lord}",
                        "nakshatra",
                        0.5,
                        f"{lord} nakshatra lord is career-relevant {nakshatra_lord}",
                    )

            d10_planet = context["varga_planets"]["D10"].get(lord)
            d9_planet = context["varga_planets"]["D9"].get(lord)
            if d9_planet:
                d9_house = d9_planet["house"]
                if d9_house in {1, 4, 5, 7, 9, 10, 11}:
                    add(
                        evidence,
                        f"dasha_{level}_{lord}_d9_house_{d9_house}",
                        "D9",
                        0.5,
                        f"{lord} is placed in supportive D9 house {d9_house}",
                    )
                elif d9_house in challenge_houses:
                    add(
                        counter_evidence,
                        f"dasha_{level}_{lord}_d9_house_{d9_house}",
                        "D9",
                        0.5,
                        f"{lord} is placed in D9 transition house {d9_house}",
                    )

            if d10_planet:
                d10_house = d10_planet["house"]
                if d10_house in support_houses:
                    add(
                        evidence,
                        f"dasha_{level}_{lord}_d10_house_{d10_house}",
                        "D10",
                        level_weight,
                        f"{lord} is placed in D10 house {d10_house}",
                    )
                elif d10_house in challenge_houses:
                    add(
                        counter_evidence,
                        f"dasha_{level}_{lord}_d10_house_{d10_house}",
                        "D10",
                        level_weight,
                        f"{lord} is placed in D10 house {d10_house}",
                    )

            d30_planet = context["varga_planets"]["D30"].get(lord)
            if d30_planet and d30_planet["house"] in {8, 10, 12}:
                target = evidence if d30_planet["house"] == 10 else counter_evidence
                add(
                    target,
                    f"dasha_{level}_{lord}_d30_house_{d30_planet['house']}",
                    "D30",
                    0.5,
                    f"{lord} is placed in D30 house {d30_planet['house']}",
                )

            if lord == context["career_lord"]:
                add(
                    evidence,
                    f"dasha_{level}_{lord}_career_lord",
                    "lordships",
                    1.5 * level_weight,
                    f"{lord} is the D1 10th-house lord",
                )
            if lord == context["amatyakaraka"]:
                add(
                    evidence,
                    f"dasha_{level}_{lord}_amatyakaraka",
                    "jaimini",
                    1.25 * level_weight,
                    f"{lord} is Amatyakaraka",
                )

        for payload in transit_payloads:
            for transit in payload.get("periods", []):
                if not _life_intersection(period, transit):
                    continue
                transit_houses = {
                    transit.get("house_from_lagna"),
                    *(
                        row.get("house_from_lagna")
                        for row in transit.get("vedic_aspects", [])
                    ),
                } - {None}
                activated_houses.update(transit_houses)
                if transit_houses & {6, 10, 11}:
                    add(
                        evidence,
                        f"transit_{payload['planet']}_career_houses",
                        f"transit.{payload['planet'].lower()}",
                        1.0,
                        f"{payload['planet']} activates career houses {sorted(transit_houses & {6, 10, 11})}",
                    )
                if transit_houses & challenge_houses:
                    add(
                        counter_evidence,
                        f"transit_{payload['planet']}_challenge_houses",
                        f"transit.{payload['planet'].lower()}",
                        0.75,
                        f"{payload['planet']} activates transition houses {sorted(transit_houses & challenge_houses)}",
                    )
                contacted = {
                    contact.get("natal_planet")
                    for contact in transit.get("natal_planet_contacts", [])
                }
                relevant_contacts = sorted(contacted & career_planets)
                if relevant_contacts:
                    add(
                        evidence,
                        f"transit_{payload['planet']}_career_contacts",
                        f"transit.{payload['planet'].lower()}",
                        0.75,
                        f"{payload['planet']} contacts career-relevant natal planets {relevant_contacts}",
                    )

        for node_period in rahu_ketu_timeline.get("periods", []):
            if not _life_intersection(period, node_period):
                continue
            node_houses = {
                node_period.get("rahu_house_from_lagna"),
                node_period.get("ketu_house_from_lagna"),
            } - {None}
            activated_houses.update(node_houses)
            if node_houses & {6, 10, 11}:
                add(
                    evidence,
                    "transit_nodes_career_axis",
                    "transit.rahu_ketu",
                    0.75,
                    f"Rahu-Ketu axis includes career houses {sorted(node_houses & {6, 10, 11})}",
                )
            if node_houses & challenge_houses:
                add(
                    counter_evidence,
                    "transit_nodes_transition_axis",
                    "transit.rahu_ketu",
                    0.75,
                    f"Rahu-Ketu axis includes transition houses {sorted(node_houses & challenge_houses)}",
                )

        support_score = round(sum(item["weight"] for item in evidence.values()), 2)
        challenge_score = round(
            sum(item["weight"] for item in counter_evidence.values()),
            2,
        )
        activation_score = round(support_score + challenge_score, 2)
        direction = _life_career_direction(support_score, challenge_score)
        sorted_evidence = sorted(
            evidence.values(),
            key=lambda item: (-item["weight"], item["code"]),
        )
        sorted_counter_evidence = sorted(
            counter_evidence.values(),
            key=lambda item: (-item["weight"], item["code"]),
        )
        event_type_scores = _life_career_event_type_scores(
            sorted_evidence,
            sorted_counter_evidence,
            path_lords,
        )
        ranked_types = sorted(
            event_type_scores.items(),
            key=lambda item: (
                -item[1]["net_score"],
                -item[1]["support_score"],
                item[0],
            ),
        )
        dominant_event_type = (
            ranked_types[0][0]
            if ranked_types
            and ranked_types[0][1]["status"] != "insufficient_evidence"
            and (
                len(ranked_types) == 1
                or ranked_types[0][1]["net_score"]
                - ranked_types[1][1]["net_score"] >= 1.0
            )
            else "not_distinguished"
        )
        rows.append({
            "start_date": period["start_date"],
            "end_date": period["end_date"],
            "age_start": _life_age_from_jd(period["start_jd"], birth_jd),
            "age_end": _life_age_from_jd(period["end_jd"], birth_jd),
            "dasha_path": path_lords,
            "precision": "pratyantar_window",
            "activation_score": activation_score,
            "support_score": support_score,
            "challenge_score": challenge_score,
            "direction": direction,
            "event_type_candidates": _life_career_event_candidates(
                activated_houses,
                path_lords,
                direction,
            ),
            "event_type_scores": event_type_scores,
            "dominant_event_type": dominant_event_type,
            "activated_houses": sorted(activated_houses),
            "independent_layers": sorted(layers),
            "evidence": sorted_evidence,
            "counter_evidence": sorted_counter_evidence,
        })

    event_type_rankings = _life_career_event_rankings(rows)
    early_career_candidates = _life_career_early_candidates(rows)
    local_turning_points = _life_career_local_turning_points(rows)
    for row in rows:
        row["event_type_scores"] = {
            event_type: {
                key: value
                for key, value in score.items()
                if key in {
                    "support_score",
                    "counter_score",
                    "net_score",
                    "status",
                    "independent_layers",
                }
            }
            for event_type, score in row["event_type_scores"].items()
        }

    ranked = sorted(
        rows,
        key=lambda row: (-row["activation_score"], row["start_date"]),
    )
    selected = ranked[:36]
    chronological = sorted(rows, key=lambda row: row["start_date"])
    return {
        "status": "technical_evidence_only",
        "version": "v2",
        "method": "pratyantar_natal_varga_and_slow_transit_evidence_ranking",
        "scope": "career_activation_windows_not_event_predictions",
        "known_life_events_used": False,
        "primary_vargas": ["D1", "D9", "D10", "D30"],
        "primary_houses": [1, 6, 8, 9, 10, 11, 12],
        "window_precision": "pratyantar",
        "direction_rule": (
            "direction_uncertain_when_support_and_challenge_are_both_substantive"
        ),
        "total_window_count": len(rows),
        "selected_window_count": len(selected),
        "selection_rule": "top_36_by_total_activation_score",
        "event_type_scoring": {
            "version": "v2",
            "types": CAREER_EVENT_TYPE_KEYS,
            "rule": "each_event_type_has_independent_support_counter_and_net_scores",
            "rankings_limit_per_type": 6,
            "ranking_min_age": CAREER_EVENT_RANKING_MIN_AGE,
            "rankings_scope": "adult_career_windows_only",
            "interpretation_guidance": CAREER_EVENT_TYPE_GUIDANCE,
            "external_realization_rule": (
                "technical_activation_does_not_establish_paid_work_clients_income_"
                "formal_status_or_real_world_event_completion"
            ),
            "early_career_candidate_rule": {
                "min_age": CAREER_EARLY_CANDIDATE_MIN_AGE,
                "max_age_exclusive": CAREER_EVENT_RANKING_MIN_AGE,
                "min_career_entry_or_status_change_net": (
                    CAREER_EARLY_CANDIDATE_MIN_NET
                ),
            },
            "local_turning_point_rule": {
                "min_forward_net": CAREER_LOCAL_TURNING_POINT_MIN_NET,
                "min_transition_net": CAREER_LOCAL_TURNING_POINT_MIN_NET,
                "rule": (
                    "combined_forward_and_transition_net_is_not_lower_than_"
                    "adjacent_pratyantar_windows"
                ),
            },
        },
        "career_context": {
            "career_lord": context["career_lord"],
            "service_lord": context["service_lord"],
            "fortune_lord": context["fortune_lord"],
            "gain_lord": context["gain_lord"],
            "amatyakaraka": context["amatyakaraka"],
        },
        "windows": chronological,
        "ranked_windows": selected,
        "event_type_rankings": event_type_rankings,
        "early_career_candidates": early_career_candidates,
        "local_transition_turning_points": local_turning_points,
        "safety_notes": [
            "activation_score_is_not_probability",
            "event_type_candidates_are_not_confirmed_events",
            "event_type_scores_are_not_probabilities",
            "event_type_rankings_include_only_age_18_and_later_windows",
            "early_career_candidates_are_separate_from_adult_rankings",
            "local_turning_points_allow_new_direction_and_exit_evidence_to_coexist",
            "technical_activation_does_not_establish_external_realization",
            "dominant_event_type_may_be_not_distinguished",
            "direction_lean_is_not_a_prediction",
            "known_life_events_are_not_used",
            "external_validation_required_before_professional_timing_claim",
        ],
    }


def _build_life_period_analysis(args):
    birth_date = _parse_life_date(args.get("birth_date"), "birth_date")
    hour, minute, second = _parse_life_time_with_second(args.get("birth_time"))
    from_age = int(args.get("from_age", 1))
    if from_age < 0:
        raise ValueError("from_age negatif olamaz")
    to_date = _parse_life_date(args.get("to_date"), "to_date") if args.get("to_date") else datetime.now().date()
    start_date = _life_date_at_age(birth_date, from_age)
    if start_date >= to_date:
        raise ValueError("analysis start tarihi to_date değerinden önce olmalı")

    lat, lon, place_timezone_id = _resolve_life_birth_place(args)
    birth = {
        "year": birth_date.year,
        "month": birth_date.month,
        "day": birth_date.day,
        "hour": hour,
        "minute": minute,
        "second": second,
        "lat": lat,
        "lon": lon,
        "timezone_id": args.get("timezone_id") or place_timezone_id,
        "tz_offset": args.get("tz_offset"),
        "place": args.get("birth_place"),
        "time_confidence": args.get("time_confidence") or "unknown",
    }
    if not birth.get("timezone_id"):
        birth.pop("timezone_id", None)
    if birth.get("tz_offset") in {None, ""}:
        birth.pop("tz_offset", None)

    tz_offset, timezone_id = _resolve_timezone_offset(birth, birth_date.year, birth_date.month, birth_date.day, hour, minute, second)
    _validate_birth_fields(birth_date.year, birth_date.month, birth_date.day, hour, minute, lat, lon, second)
    chart = calculate_chart(birth_date.year, birth_date.month, birth_date.day, hour, minute, tz_offset, lat, lon, second)
    birth_jd = date_to_jd(birth_date.year, birth_date.month, birth_date.day, hour, minute, tz_offset, second)
    start_jd = _life_jd_from_date(start_date, tz_offset, 0, 0)
    end_jd = _life_jd_from_date(to_date, tz_offset, 23, 59)

    requested_planets = {
        item.strip().lower()
        for item in str(args.get("planets") or "saturn,jupiter").split(",")
        if item.strip()
    }
    requested_planets = requested_planets & set(LIFE_TRANSIT_PLANETS.keys())
    if not requested_planets:
        raise ValueError("planets saturn ve/veya jupiter içermeli")

    dasha_timeline = _life_dasha_timeline(chart, birth_jd, start_jd, end_jd)
    transit_payloads_by_key = {
        key: _life_transit_period_payload(chart, key, start_jd, end_jd, birth_jd)
        for key in sorted(requested_planets)
    }
    transit_payloads = list(transit_payloads_by_key.values())
    saturn_periods = transit_payloads_by_key.get("saturn", {}).get("periods", [])
    jupiter_periods = transit_payloads_by_key.get("jupiter", {}).get("periods", [])
    rahu_ketu_timeline = _life_rahu_ketu_transit_timeline(chart, start_jd, end_jd, birth_jd)
    career_timing_evidence = _life_career_timing_evidence(
        chart,
        dasha_timeline,
        transit_payloads,
        rahu_ketu_timeline,
        birth_jd,
    )
    neptune_career_evidence = _life_career_neptune_evidence(
        chart,
        start_jd,
        end_jd,
        birth_jd,
    )
    health_timing_evidence = _life_health_timing_evidence(
        chart,
        dasha_timeline,
        transit_payloads,
        rahu_ketu_timeline,
        birth_jd,
        start_jd,
        end_jd,
    )
    family_timing_evidence = _life_family_timing_evidence(
        chart,
        dasha_timeline,
        transit_payloads,
        rahu_ketu_timeline,
        birth_jd,
    )
    education_timing_evidence = _life_education_timing_evidence(
        chart,
        dasha_timeline,
        transit_payloads,
        rahu_ketu_timeline,
        birth_jd,
    )
    relocation_timing_evidence = _life_relocation_timing_evidence(
        chart,
        dasha_timeline,
        transit_payloads,
        rahu_ketu_timeline,
        birth_jd,
    )
