def _parse_chart_birth_date(value):
    for date_format in ("%d.%m.%Y", "%Y-%m-%d", "%d/%m/%Y"):
        try:
            return datetime.strptime(str(value), date_format).date()
        except (TypeError, ValueError):
            continue
    raise ValueError("chart.birth.date desteklenen formatta değil")


def _life_period_args_from_chart(chart, from_age=1, to_date=None):
    birth = chart.get("birth") or {}
    birth_date = _parse_chart_birth_date(birth.get("date"))
    birth_time = str(birth.get("time") or "00:00:00")
    lat = birth.get("latitude")
    lon = birth.get("longitude_geo")
    if lat in {None, ""} or lon in {None, ""}:
        raise ValueError("chart.birth latitude/longitude eksik")

    person = birth.get("person") or {}
    args = {
        "person_id": person.get("id") or person.get("name"),
        "birth_date": birth_date.isoformat(),
        "birth_time": birth_time,
        "birth_place": f"{lat},{lon}",
        "lat": lat,
        "lon": lon,
        "from_age": str(from_age or 1),
        "to_date": to_date or datetime.now().date().isoformat(),
        "ayanamsa": "Lahiri",
        "zodiac": "sidereal",
        "house_reference": "lagna_and_moon",
        "planets": "saturn,jupiter",
        "include_dasha": "true",
        "include_antardasha": "true",
        "include_pratyantardasha": "false",
        "include_retrograde": "true",
        "include_natal_contacts": "true",
        "include_vedic_aspects": "true",
        "time_confidence": birth.get("time_confidence"),
    }
    if birth.get("timezone_id"):
        args["timezone_id"] = birth.get("timezone_id")
    elif birth.get("tz_offset") not in {None, ""}:
        args["tz_offset"] = birth.get("tz_offset")
    return args


def _life_period_not_available(error):
    return {
        "status": "not_available",
        "error": str(error),
        "technical_notes": [
            "Life period analysis could not be attached to this expert package.",
        ],
    }


def _build_life_period_analysis_for_chart(chart, from_age=1, to_date=None):
    try:
        return _build_life_period_analysis(
            _life_period_args_from_chart(chart, from_age=from_age, to_date=to_date)
        )
    except Exception as exc:
        return _life_period_not_available(exc)


def _attach_life_period_analysis_if_requested(result, options):
    if not _parse_bool_param(options.get("include_life_period_analysis"), False):
        return result
    result["life_period_analysis"] = _build_life_period_analysis_for_chart(
        result,
        from_age=options.get("life_from_age") or 1,
        to_date=options.get("life_to_date"),
    )
    return result


