def _beta_now():
    return datetime.now().astimezone().isoformat(timespec="seconds")


def _beta_day():
    return datetime.now().astimezone().date().isoformat()


def _beta_db_path():
    return Path(app.config["BETA_DB_PATH"])


def _beta_db():
    db_path = _beta_db_path()
    db_path.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    _beta_init_db(conn)
    return conn


def _beta_init_db(conn):
    conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS beta_profiles (
            id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            group_name TEXT NOT NULL,
            birth_json TEXT NOT NULL,
            options_json TEXT NOT NULL,
            chart_id TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS beta_charts (
            id TEXT PRIMARY KEY,
            profile_id TEXT NOT NULL,
            chart_json TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS beta_chat_messages (
            id TEXT PRIMARY KEY,
            profile_id TEXT,
            chart_id TEXT NOT NULL,
            question TEXT NOT NULL,
            response_json TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS beta_feedback (
            id TEXT PRIMARY KEY,
            message_id TEXT,
            profile_id TEXT,
            rating TEXT,
            comment TEXT,
            created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS beta_usage_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            day TEXT NOT NULL,
            action TEXT NOT NULL,
            profile_id TEXT,
            created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS beta_methodology_comparisons (
            id TEXT PRIMARY KEY,
            profile_id TEXT,
            chart_id TEXT NOT NULL,
            question TEXT NOT NULL,
            status TEXT NOT NULL,
            response_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS beta_question_routes (
            id TEXT PRIMARY KEY,
            profile_id TEXT,
            chart_id TEXT NOT NULL,
            owner_user_id TEXT,
            question TEXT NOT NULL,
            mode TEXT NOT NULL,
            status TEXT NOT NULL,
            legacy_json TEXT NOT NULL,
            model_json TEXT,
            selected_json TEXT NOT NULL,
            error_code TEXT,
            created_at TEXT NOT NULL
        );
        """
    )
    for table, column in (
        ("beta_profiles", "owner_user_id"),
        ("beta_charts", "owner_user_id"),
    ):
        existing_columns = {
            row[1]
            for row in conn.execute(f"PRAGMA table_info({table})").fetchall()
        }
        if column not in existing_columns:
            conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} TEXT")
    conn.execute(
        "CREATE INDEX IF NOT EXISTS beta_profiles_owner_user_id_idx ON beta_profiles(owner_user_id)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS beta_charts_owner_user_id_idx ON beta_charts(owner_user_id)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS beta_question_routes_profile_id_idx ON beta_question_routes(profile_id)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS beta_question_routes_owner_user_id_idx ON beta_question_routes(owner_user_id)"
    )
    conn.commit()


def _beta_json(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True)


def _beta_load_json(text):
    return json.loads(text)


def _beta_usage_status(conn, profile_id=None):
    day = _beta_day()
    params = [day]
    profile_filter = ""
    if profile_id:
        profile_filter = " AND profile_id = ?"
        params.append(profile_id)

    chat_count = conn.execute(
        f"SELECT COUNT(*) FROM beta_usage_events WHERE day = ? AND action = 'chat_draft'{profile_filter}",
        params,
    ).fetchone()[0]
    heavy_count = conn.execute(
        f"SELECT COUNT(*) FROM beta_usage_events WHERE day = ? AND action = 'heavy'{profile_filter}",
        params,
    ).fetchone()[0]

    chat_limit = int(app.config["BETA_DAILY_CHAT_LIMIT"])
    heavy_limit = int(app.config["BETA_DAILY_HEAVY_LIMIT"])
    return {
        "day": day,
        "chat": {
            "used": chat_count,
            "limit": chat_limit,
            "remaining": max(chat_limit - chat_count, 0),
        },
        "heavy": {
            "used": heavy_count,
            "limit": heavy_limit,
            "remaining": max(heavy_limit - heavy_count, 0),
        },
        "mode": "closed_personal_beta",
    }


def _beta_record_usage(conn, action, profile_id=None):
    conn.execute(
        "INSERT INTO beta_usage_events (day, action, profile_id, created_at) VALUES (?, ?, ?, ?)",
        (_beta_day(), action, profile_id, _beta_now()),
    )
    conn.commit()


def _account_deletion_user_id(value):
    try:
        parsed = uuid.UUID(str(value or "").strip())
    except (ValueError, AttributeError, TypeError) as exc:
        raise ValueError("Geçerli user_id gerekli") from exc
    if parsed.version != 4:
        raise ValueError("user_id UUID v4 olmalı")
    return str(parsed)


def _account_deletion_request_id(value):
    request_id = str(value or "").strip()
    if not re.fullmatch(r"[0-9A-Za-z._:-]{1,200}", request_id):
        raise ValueError("Geçerli request_id gerekli")
    return request_id


def _delete_beta_user_records(conn, user_id):
    profile_ids = {
        str(row[0])
        for row in conn.execute(
            "SELECT id FROM beta_profiles WHERE id = ? OR owner_user_id = ?",
            (user_id, user_id),
        ).fetchall()
    }
    profile_ids.add(user_id)
    counts = {
        "question_routes": 0,
        "methodology_comparisons": 0,
        "feedback": 0,
        "chat_messages": 0,
        "charts": 0,
        "profiles": 0,
        "usage_events": 0,
    }
    statements = (
        (
            "question_routes",
            "DELETE FROM beta_question_routes WHERE profile_id = ? OR owner_user_id = ?",
            (user_id, user_id),
        ),
        (
            "methodology_comparisons",
            "DELETE FROM beta_methodology_comparisons WHERE profile_id = ?",
            (user_id,),
        ),
        (
            "feedback",
            """
            DELETE FROM beta_feedback
            WHERE profile_id = ?
               OR message_id IN (
                    SELECT id FROM beta_chat_messages WHERE profile_id = ?
               )
            """,
            (user_id, user_id),
        ),
        (
            "chat_messages",
            "DELETE FROM beta_chat_messages WHERE profile_id = ?",
            (user_id,),
        ),
        (
            "charts",
            "DELETE FROM beta_charts WHERE profile_id = ?",
            (user_id,),
        ),
        (
            "profiles",
            "DELETE FROM beta_profiles WHERE id = ?",
            (user_id,),
        ),
        (
            "usage_events",
            "DELETE FROM beta_usage_events WHERE profile_id = ?",
            (user_id,),
        ),
    )
    try:
        for profile_id in profile_ids:
            for key, statement, params in statements:
                scoped_params = tuple(profile_id if value == user_id else value for value in params)
                cursor = conn.execute(statement, scoped_params)
                counts[key] += max(int(cursor.rowcount), 0)
        orphan_charts = conn.execute(
            "DELETE FROM beta_charts WHERE owner_user_id = ?",
            (user_id,),
        )
        counts["charts"] += max(int(orphan_charts.rowcount), 0)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return counts


def _delete_user_data_directory(user_id):
    root = Path(app.config["USER_DATA_ROOT"]).resolve()
    target = (root / user_id).resolve()
    if target.parent != root:
        raise ValueError("Kullanıcı veri yolu güvenli değil")
    if not target.exists():
        return False
    if not target.is_dir():
        raise ValueError("Kullanıcı veri yolu klasör değil")
    shutil.rmtree(target)
    return True


def _pwa_nested_markdown(value):
    """Place an existing technical block below a numbered natal section."""

    lines = str(value or "").strip().splitlines()
    if lines and lines[0].startswith("## "):
        lines = lines[1:]
        while lines and not lines[0].strip():
            lines.pop(0)
    nested = []
    for line in lines:
        if line.startswith("#"):
            hashes = len(line) - len(line.lstrip("#"))
            line = "#" * min(hashes + 1, 6) + line[hashes:]
        nested.append(line)
    return "\n".join(nested).strip()


