def _pwa_artifact_sha256(content):
    if isinstance(content, str):
        content = content.encode("utf-8")
    return hashlib.sha256(content).hexdigest()


def _pwa_artifact_chart_id(value):
    chart_id = str(value or "").strip()
    if not re.fullmatch(r"[0-9A-Za-z._:-]{1,200}", chart_id):
        raise ValueError("Geçerli chart_id gerekli")
    return chart_id


def _pwa_artifact_profile(value=None):
    profile = str(value or PWA_ARTIFACT_DEFAULT_PROFILE).strip()
    if profile not in PWA_ARTIFACT_PROFILE_CODES:
        raise ValueError("Geçerli artifact_profile gerekli")
    return profile


def _pwa_artifact_set_root(owner_user_id, chart_id, artifact_profile=None):
    owner_user_id = _account_deletion_user_id(owner_user_id)
    chart_id = _pwa_artifact_chart_id(chart_id)
    artifact_profile = _pwa_artifact_profile(artifact_profile)
    user_root = Path(app.config["USER_DATA_ROOT"]).resolve()
    schema_root = (user_root / owner_user_id / chart_id / PWA_ARTIFACT_SCHEMA_VERSION).resolve()
    target = (schema_root / artifact_profile).resolve()
    expected_chart_root = (user_root / owner_user_id / chart_id).resolve()
    if (
        target.parent != schema_root
        or schema_root.parent != expected_chart_root
        or expected_chart_root.parent.parent != user_root
    ):
        raise ValueError("Artefakt veri yolu güvenli değil")
    return target


def _pwa_artifact_write(path, content):
    data = content.encode("utf-8") if isinstance(content, str) else content
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    temporary.write_bytes(data)
    os.replace(temporary, path)
    return {
        "byte_size": len(data),
        "sha256": _pwa_artifact_sha256(data),
    }


def _pwa_artifact_existing_manifest(
    root,
    owner_user_id,
    profile_id,
    chart_id,
    chart_sha256,
    artifact_profile,
):
    path = root / "manifest.json"
    if not path.is_file():
        return None
    try:
        manifest = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    if (
        manifest.get("contract_version") != PWA_ARTIFACT_MANIFEST_VERSION
        or manifest.get("schema_version") != PWA_ARTIFACT_SCHEMA_VERSION
        or manifest.get("generator_revision") != PWA_ARTIFACT_GENERATOR_REVISION
        or manifest.get("artifact_profile") != artifact_profile
        or manifest.get("owner_user_id") != owner_user_id
        or manifest.get("profile_id") != profile_id
        or manifest.get("chart_id") != chart_id
        or manifest.get("canonical_snapshot", {}).get("sha256") != chart_sha256
        or manifest.get("artifact_count") != len(PWA_ARTIFACT_PROFILE_CODES[artifact_profile])
        or len(manifest.get("artifacts") or []) != len(PWA_ARTIFACT_PROFILE_CODES[artifact_profile])
        or tuple(item.get("code") for item in manifest.get("artifacts") or [])
        != PWA_ARTIFACT_PROFILE_CODES[artifact_profile]
    ):
        return None
    for item in [manifest.get("canonical_snapshot"), *(manifest.get("artifacts") or [])]:
        if not isinstance(item, dict):
            return None
        artifact_path = root / str(item.get("filename") or "")
        if not artifact_path.is_file():
            return None
        data = artifact_path.read_bytes()
        if len(data) != item.get("byte_size") or _pwa_artifact_sha256(data) != item.get("sha256"):
            return None
    return manifest


PWA_TRANSIT_RUNTIME_CACHE_CONTRACT = "vedic-transit-runtime-cache-v1"


def _pwa_transit_pack(
    chart,
    person_name,
    group_name,
    start_date=None,
    transit_time="12:00",
    period="three_month",
):
    birth = chart.get("birth") or {}
    current_date = datetime.now().date()
    if birth.get("timezone_id"):
        try:
            current_date = datetime.now(ZoneInfo(birth["timezone_id"])).date()
        except ZoneInfoNotFoundError:
            pass
    payload = {
        "person": {"id": person_name, "name": person_name, "group": group_name},
        "birth": _chart_birth_input_for_transit(chart),
        "options": {
            "ayanamsa": "Lahiri",
            "zodiac": "sidereal",
            "house_system": "whole_sign",
            "node_type": "true",
            "language": "tr",
        },
        "period": period,
        "start_date": str(start_date or current_date.isoformat()),
        "transit_time": str(transit_time or "12:00"),
    }
    if birth.get("timezone_id"):
        payload["transit_timezone_id"] = birth.get("timezone_id")
    elif birth.get("tz_offset") not in {None, ""}:
        payload["transit_tz_offset"] = birth.get("tz_offset")
    return _build_transit_pack(payload)


def _pwa_transit_runtime_cache_path(owner_user_id, chart_id, artifact_profile=None):
    root = _pwa_artifact_set_root(owner_user_id, chart_id, artifact_profile)
    return (root / "transit-three-month.runtime.json").resolve()


def _pwa_write_transit_runtime_cache(
    owner_user_id,
    profile_id,
    chart_id,
    artifact_profile,
    chart,
    transit_pack,
):
    path = _pwa_transit_runtime_cache_path(owner_user_id, chart_id, artifact_profile)
    root = _pwa_artifact_set_root(owner_user_id, chart_id, artifact_profile).resolve()
    if path.parent != root or path.name != "transit-three-month.runtime.json":
        raise ValueError("Transit çalışma önbelleği yolu güvenli değil")
    canonical_chart = json.dumps(
        chart,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    payload = {
        "contract_version": PWA_TRANSIT_RUNTIME_CACHE_CONTRACT,
        "generator_revision": PWA_ARTIFACT_GENERATOR_REVISION,
        "owner_user_id": owner_user_id,
        "profile_id": profile_id,
        "chart_id": chart_id,
        "artifact_profile": artifact_profile,
        "canonical_chart_sha256": _pwa_artifact_sha256(canonical_chart),
        "created_at": _beta_now(),
        "pack": transit_pack,
    }
    _pwa_artifact_write(
        path,
        json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
    )
    return payload


def _pwa_read_transit_runtime_cache(
    owner_user_id,
    profile_id,
    chart_id,
    artifact_profile,
    chart,
):
    path = _pwa_transit_runtime_cache_path(owner_user_id, chart_id, artifact_profile)
    if not path.is_file():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    canonical_chart = json.dumps(
        chart,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    if (
        not isinstance(payload, dict)
        or payload.get("contract_version") != PWA_TRANSIT_RUNTIME_CACHE_CONTRACT
        or payload.get("generator_revision") != PWA_ARTIFACT_GENERATOR_REVISION
        or payload.get("owner_user_id") != owner_user_id
        or payload.get("profile_id") != profile_id
        or payload.get("chart_id") != chart_id
        or payload.get("artifact_profile") != artifact_profile
        or payload.get("canonical_chart_sha256") != _pwa_artifact_sha256(canonical_chart)
        or not isinstance(payload.get("pack"), dict)
    ):
        return None
    return payload


def _pwa_transit_pack_covers(transit_pack, range_start, range_end):
    period = (transit_pack or {}).get("period") or {}
    try:
        pack_start = date.fromisoformat(str(period.get("range_start") or ""))
        pack_end = date.fromisoformat(str(period.get("range_end") or ""))
        wanted_start = date.fromisoformat(str(range_start))
        wanted_end = date.fromisoformat(str(range_end))
    except ValueError:
        return False
    return pack_start <= wanted_start <= wanted_end <= pack_end


def _pwa_get_or_create_transit_runtime_cache(
    owner_user_id,
    profile_id,
    chart_id,
    artifact_profile,
    chart,
    person_name,
    range_start,
    range_end,
):
    root = _pwa_artifact_set_root(owner_user_id, chart_id, artifact_profile)
    manifest_path = root / "manifest.json"
    if not manifest_path.is_file():
        raise FileNotFoundError("Transit artefakt manifesti bulunamadı")
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    if (
        manifest.get("owner_user_id") != owner_user_id
        or manifest.get("profile_id") != profile_id
        or manifest.get("chart_id") != chart_id
        or manifest.get("artifact_profile") != artifact_profile
        or "transit_three_month" not in {
            item.get("code") for item in manifest.get("artifacts") or []
        }
    ):
        raise ValueError("Transit artefakt sahipliği doğrulanamadı")

    cached = _pwa_read_transit_runtime_cache(
        owner_user_id,
        profile_id,
        chart_id,
        artifact_profile,
        chart,
    )
    if cached and _pwa_transit_pack_covers(cached["pack"], range_start, range_end):
        return cached["pack"], "stored_runtime_artifact", False

    # A missing, corrupt, stale or out-of-range cache is one of the explicitly
    # allowed regeneration cases. It is generated once, persisted, and reused.
    transit_pack = _pwa_transit_pack(
        chart,
        person_name,
        "PWA",
        start_date=range_start,
    )
    _pwa_write_transit_runtime_cache(
        owner_user_id,
        profile_id,
        chart_id,
        artifact_profile,
        chart,
        transit_pack,
    )
    return transit_pack, "runtime_artifact_regenerated", True


def _generate_pwa_artifact_set(
    owner_user_id,
    profile_id,
    chart_id,
    chart,
    person_name,
    artifact_profile=None,
):
    owner_user_id = _account_deletion_user_id(owner_user_id)
    profile_id = str(profile_id or "").strip()
    chart_id = _pwa_artifact_chart_id(chart_id)
    if not profile_id or not isinstance(chart, dict):
        raise ValueError("Profil ve chart verisi gerekli")

    artifact_profile = _pwa_artifact_profile(artifact_profile)
    root = _pwa_artifact_set_root(owner_user_id, chart_id, artifact_profile)
    canonical_json = json.dumps(chart, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    chart_sha256 = _pwa_artifact_sha256(canonical_json)
    existing = _pwa_artifact_existing_manifest(
        root,
        owner_user_id,
        profile_id,
        chart_id,
        chart_sha256,
        artifact_profile,
    )
    if existing:
        # Old manifests can predate the structured runtime sidecar. Backfill it
        # only during explicit artifact generation, never on normal sign-in.
        runtime_cache = _pwa_read_transit_runtime_cache(
            owner_user_id,
            profile_id,
            chart_id,
            artifact_profile,
            chart,
        )
        if runtime_cache is None:
            transit_pack = _pwa_transit_pack(chart, person_name, "PWA")
            transit_pack["_source_path"] = "transit-three-month.md"
            _pwa_write_transit_runtime_cache(
                owner_user_id,
                profile_id,
                chart_id,
                artifact_profile,
                chart,
                transit_pack,
            )
        manifest_bytes = (root / "manifest.json").read_bytes()
        return existing, _pwa_artifact_sha256(manifest_bytes), True

    chart_for_render = json.loads(canonical_json)
    if not (chart_for_render.get("life_period_analysis") or {}).get("education_timing_evidence_v1"):
        chart_for_render["life_period_analysis"] = _build_life_period_analysis_for_chart(chart_for_render)
    group_name = "PWA"
    transit_pack = _pwa_transit_pack(chart_for_render, person_name, group_name)
    transit_pack["_source_path"] = "transit-three-month.md"
    _pwa_write_transit_runtime_cache(
        owner_user_id,
        profile_id,
        chart_id,
        artifact_profile,
        chart,
        transit_pack,
    )

    artifacts = []
    if artifact_profile == PWA_ARTIFACT_PROFILE_COMPACT:
        natal_content, section_index = _build_natal_interpretation_package_markdown(
            chart_for_render,
            person_name,
            group_name,
            transit_pack=transit_pack,
            rectification_record=None,
        )
        natal_filename = "natal-interpretation.md"
        natal_metadata = _pwa_artifact_write(root / natal_filename, natal_content)
        artifacts.append({
            "code": "natal_interpretation",
            "filename": natal_filename,
            "download_filename": f"{person_name}-Natal-Yorum-Paketi.md",
            "artifact_type": "natal_markdown",
            "content_type": "text/markdown; charset=utf-8",
            "required": True,
            "section_count": len(section_index),
            "sections": section_index,
            **natal_metadata,
        })
    else:
        for code, filename, artifact_type, builder in PWA_ARTIFACT_BUILDERS:
            if code == "session":
                content = builder(
                    chart_for_render,
                    person_name,
                    group_name,
                    rectification_record=None,
                    transit_pack=transit_pack,
                )
            else:
                content = builder(chart_for_render, person_name, group_name, transit_pack)
            metadata = _pwa_artifact_write(root / filename, content)
            artifacts.append({
                "code": code,
                "filename": filename,
                "artifact_type": artifact_type,
                "content_type": "text/markdown; charset=utf-8",
                "required": True,
                **metadata,
            })

    transit_filename = "transit-three-month.md"
    transit_metadata = _pwa_artifact_write(
        root / transit_filename,
        _build_transit_pack_markdown(transit_pack),
    )
    artifacts.append({
        "code": "transit_three_month",
        "filename": transit_filename,
        "artifact_type": "transit_markdown",
        "content_type": "text/markdown; charset=utf-8",
        "required": True,
        **transit_metadata,
    })

    snapshot_filename = "canonical-snapshot.json"
    snapshot_metadata = _pwa_artifact_write(root / snapshot_filename, canonical_json)
    generated_at = _beta_now()
    manifest = {
        "contract_version": PWA_ARTIFACT_MANIFEST_VERSION,
        "schema_version": PWA_ARTIFACT_SCHEMA_VERSION,
        "generator_revision": PWA_ARTIFACT_GENERATOR_REVISION,
        "artifact_profile": artifact_profile,
        "required_codes": list(PWA_ARTIFACT_PROFILE_CODES[artifact_profile]),
        "owner_user_id": owner_user_id,
        "profile_id": profile_id,
        "chart_id": chart_id,
        "generated_at": generated_at,
        "engine": "progresif-vedic-chart",
        "artifact_count": len(artifacts),
        "canonical_snapshot": {
            "code": "canonical_snapshot",
            "filename": snapshot_filename,
            "artifact_type": "canonical_json",
            "content_type": "application/json; charset=utf-8",
            **snapshot_metadata,
        },
        "artifacts": artifacts,
    }
    manifest_text = json.dumps(manifest, ensure_ascii=False, sort_keys=True, indent=2)
    manifest_metadata = _pwa_artifact_write(root / "manifest.json", manifest_text)
    return manifest, manifest_metadata["sha256"], False


def _pwa_artifact_file(owner_user_id, chart_id, artifact_code, artifact_profile=None):
    artifact_profile = _pwa_artifact_profile(artifact_profile)
    root = _pwa_artifact_set_root(owner_user_id, chart_id, artifact_profile)
    manifest_path = root / "manifest.json"
    if not manifest_path.is_file():
        raise FileNotFoundError("Artefakt manifesti bulunamadı")
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    if (
        manifest.get("owner_user_id") != owner_user_id
        or manifest.get("chart_id") != chart_id
        or manifest.get("artifact_profile") != artifact_profile
    ):
        raise ValueError("Artefakt sahipliği doğrulanamadı")
    candidates = [
        manifest.get("canonical_snapshot"),
        {"code": "manifest", "filename": "manifest.json", "content_type": "application/json; charset=utf-8"},
        *(manifest.get("artifacts") or []),
    ]
    item = next((candidate for candidate in candidates if candidate and candidate.get("code") == artifact_code), None)
    if not item:
        raise FileNotFoundError("Artefakt bulunamadı")
    path = (root / item["filename"]).resolve()
    if path.parent != root or not path.is_file():
        raise FileNotFoundError("Artefakt dosyası bulunamadı")
    data = path.read_bytes()
    expected_sha256 = item.get("sha256")
    if artifact_code == "manifest":
        expected_sha256 = _pwa_artifact_sha256(data)
    if expected_sha256 and _pwa_artifact_sha256(data) != expected_sha256:
        raise ValueError("Artefakt bütünlüğü doğrulanamadı")
    return path, item, _pwa_artifact_sha256(data)


def _beta_options(options):
    merged = dict(BETA_DEFAULT_OPTIONS)
    merged.update({key: value for key, value in (options or {}).items() if value is not None})
    _validate_v2_options(merged)
    return merged


def _beta_build_chart(person, birth, options):
    year = _require_int(birth, "year")
    month = _require_int(birth, "month")
    day = _require_int(birth, "day")
    hour = _require_int(birth, "hour")
    minute = _require_int(birth, "minute")
    second = _optional_second(birth)
    lat = _require_float(birth, "lat")
    lon = _require_float(birth, "lon")
    _validate_birth_fields(year, month, day, hour, minute, lat, lon, second)

    normalized_birth = dict(birth)
    if not str(normalized_birth.get("timezone_id") or "").strip():
        normalized_birth.pop("timezone_id", None)
    tz_offset, timezone_id = _resolve_timezone_offset(normalized_birth, year, month, day, hour, minute, second)
    chart = calculate_chart(year, month, day, hour, minute, tz_offset, lat, lon, second)
    return _build_v2_chart(
        chart,
        {
            "person": person,
            "birth": normalized_birth,
            "options": options,
        },
        normalized_birth,
        tz_offset,
        timezone_id,
    )


def _beta_chart_summary(chart):
    lagna = chart.get("lagna", {})
    birth = chart.get("birth", {})
    active = (
        chart.get("dashas", {})
        .get("vimshottari", {})
        .get("current_active")
        or chart.get("dashas", {}).get("vimshottari", {}).get("active")
        or {}
    )
    supported_planets = {
        "Sun", "Moon", "Mars", "Mercury", "Jupiter", "Venus", "Saturn",
        "Rahu (True)", "Ketu",
    }
    planets = [
        {
            "id": planet.get("id"),
            "name": planet.get("name"),
            "name_tr": planet.get("name_tr"),
            "longitude": planet.get("longitude"),
            "sign": planet.get("sign"),
            "sign_tr": planet.get("sign_tr"),
            "house": planet.get("house"),
            "degree": planet.get("degree"),
            "degree_str": planet.get("degree_str"),
            "retrograde": bool((planet.get("motion") or {}).get("retrograde")),
            "nakshatra": (planet.get("nakshatra") or {}).get("name"),
            "nakshatra_pada": (planet.get("nakshatra") or {}).get("pada"),
        }
        for planet in chart.get("planets", [])
        if planet.get("name") in supported_planets
    ]
    vargas = {}
    for division in VARGA_NAMES:
        varga = (chart.get("vargas") or {}).get(division) or {}
        varga_lagna = varga.get("lagna") or {}
        vargas[division] = {
            "confidence": varga.get("confidence"),
            "reference_frame": varga.get("reference_frame") or "birth_lagna",
            "lagna": {
                "longitude": (
                    varga_lagna.get("sign_index", 0) * 30.0
                    + (varga_lagna.get("degree") or 0.0)
                ),
                "sign": varga_lagna.get("sign"),
                "sign_tr": varga_lagna.get("sign_tr"),
                "degree": varga_lagna.get("degree"),
                "degree_str": varga_lagna.get("degree_str"),
            },
            "planets": [
                {
                    "id": planet.get("id"),
                    "longitude": (
                        planet.get("sign_index", 0) * 30.0
                        + (planet.get("degree") or 0.0)
                    ),
                    "sign": planet.get("sign"),
                    "sign_tr": planet.get("sign_tr"),
                    "degree": planet.get("degree"),
                    "degree_str": planet.get("degree_str"),
                }
                for planet in varga.get("planets", [])
                if planet.get("id")
            ],
        }
    active_periods = []
    for level in ("maha", "antara", "pratyantar", "sookshma"):
        period = active.get(level) or {}
        if isinstance(period, str):
            period = {"lord": period}
        if period:
            active_periods.append({
                "level": level,
                "lord": period.get("lord"),
                "start_date": period.get("actual_start") or period.get("start"),
                "end_date": period.get("actual_end") or period.get("end"),
                "actual_start_jd": period.get("actual_start_jd"),
                "actual_end_jd": period.get("actual_end_jd"),
            })
    return {
        "schema_version": "vedic-pwa-chart-summary-v2",
        "display_name": ((birth.get("person") or {}).get("name")),
        "birth": {
            "date": birth.get("date"),
            "time": birth.get("time"),
            "place": birth.get("place"),
            "timezone": birth.get("timezone_label") or birth.get("timezone"),
            "time_confidence": birth.get("time_confidence"),
            "time_confidence_label": birth.get("time_confidence_label"),
            "calculation_reference_time": birth.get("calculation_reference_time"),
            "calculation_reference_only": bool(birth.get("calculation_reference_only")),
        },
        "lagna": {
            "sign": lagna.get("sign"),
            "sign_tr": lagna.get("sign_tr"),
            "longitude": lagna.get("longitude"),
            "degree": lagna.get("degree_str"),
            "reference_frame": lagna.get("reference_frame") or "birth_lagna",
            "is_birth_ascendant": lagna.get("is_birth_ascendant", True),
            "confidence": lagna.get("interpretation_confidence"),
        },
        "ayanamsa": (chart.get("ayanamsa") or {}).get("type") or "Lahiri",
        "planets": planets,
        "vargas": vargas,
        "active_dasha_path": active.get("path"),
        "active_dasha_periods": active_periods,
    }


def _beta_detect_topic(question):
    normalized = str(question or "").casefold()
    if any(keyword.casefold() in normalized for keyword in BETA_TIMING_KEYWORDS):
        return "transit"
    for topic, keywords in BETA_TOPIC_KEYWORDS.items():
        if any(keyword.casefold() in normalized for keyword in keywords):
            return topic
    return "general"


def _beta_is_rectification_question(question):
    normalized = str(question or "").casefold()
    return any(keyword.casefold() in normalized for keyword in BETA_RECTIFICATION_KEYWORDS)


def _beta_detect_subject_topic(question):
    normalized = str(question or "").casefold()
    for topic, keywords in BETA_TOPIC_KEYWORDS.items():
        if topic == "transit":
            continue
        if any(keyword.casefold() in normalized for keyword in keywords):
            return topic
    return "general"


def _beta_legacy_question_route(question):
    """Expose the old keyword decision in the new route shape for comparison."""

    normalized = str(question or "").casefold()
    topic = _beta_detect_topic(question)
    subject_topic = _beta_detect_subject_topic(question) if topic == "transit" else topic
    if any(value in normalized for value in ("tam şu anda", "tam su anda", "şimdi", "simdi")):
        time_scope = "instant"
    elif any(value in normalized for value in ("bugün", "bugun")):
        time_scope = "daily"
    elif topic == "transit":
        time_scope = "range"
    else:
        time_scope = "none"

    today = _beta_day()
    required = ["natal_core", "topic_packet", "active_dasha"]
    if subject_topic == "wellbeing":
        required.append("natal_emotional_core")
    if time_scope != "none":
        required.extend([
            "stored_transit_days",
            "transit_natal_contacts",
            "ashtakavarga",
        ])
    if time_scope in {"instant", "daily"}:
        required.append("moon_and_panchanga")
    if time_scope == "instant":
        required.append("current_transit_snapshot")
    return {
        "contract_version": "vedic-question-route-legacy-v1",
        "interpreted_question": str(question or "").strip(),
        "primary_topic": subject_topic,
        "time_scope": time_scope,
        "timing_required": time_scope != "none",
        "target_start": today if time_scope in {"daily", "range"} else None,
        "target_end": today if time_scope == "daily" else None,
        "target_datetime": "now" if time_scope == "instant" else None,
        "required_evidence": required,
        "sensitivity": (
            "medical" if subject_topic == "health" else "standard"
        ),
        "confidence": "low",
        "clarification_required": False,
        "clarification_question": None,
    }


def _beta_question_now(chart):
    birth = chart.get("birth") or {}
    timezone_id = str(birth.get("timezone_id") or "").strip()
    if timezone_id:
        try:
            return datetime.now(ZoneInfo(timezone_id)).isoformat(timespec="seconds")
        except ZoneInfoNotFoundError:
            pass
    return datetime.now().astimezone().isoformat(timespec="seconds")


def _beta_question_router_mode(owner_user_id=None):
    configured = str(app.config.get("QUESTION_ROUTER_MODE") or "off").strip().lower()
    if configured not in {"off", "shadow", "active", "gemini_only", "bypass"}:
        configured = "off"
    if configured == "bypass":
        return "bypass"
    active_users = app.config.get("QUESTION_ROUTER_ACTIVE_USER_IDS") or set()
    if owner_user_id and owner_user_id in active_users:
        return "gemini_only" if configured == "gemini_only" else "active"
    if configured in {"active", "gemini_only"} and active_users:
        return "shadow"
    return configured


def _beta_question_route(
    question,
    chart,
    request_id,
    owner_user_id=None,
    *,
    mode_override=None,
):
    legacy = _beta_legacy_question_route(question)
    mode = (
        str(mode_override).strip().lower()
        if mode_override is not None
        else _beta_question_router_mode(owner_user_id)
    )
    if mode not in {"off", "shadow", "active", "gemini_only", "bypass"}:
        raise ValueError("Geçerli soru yönlendirici modu gerekli")
    model = None
    error_code = None
    if mode not in {"off", "bypass"}:
        try:
            model = classify_question(
                question,
                f"{request_id}-question-route",
                call_vertex_bridge,
                _beta_question_now(chart),
                apply_server_normalization=mode != "gemini_only",
            )
        except Exception as exc:
            error_code = (
                exc.code
                if isinstance(exc, QuestionClassificationError)
                else getattr(exc, "code", "question_classifier_failed")
            )
            if not str(error_code).startswith(("question_classifier_", "vertex_")):
                error_code = "question_classifier_failed"
    if mode == "gemini_only" and not model:
        # Explicit reversible experiment: never hide a Gemini routing failure
        # by silently selecting the legacy keyword router.
        raise QuestionClassificationError(error_code or "question_classifier_failed")
    bypass = None
    if mode == "bypass":
        # Reversible production experiment: skip the separate classifier and
        # give the main methodology model the full natal evidence surface.
        # No keyword-derived topic or timing decision is allowed to leak in.
        bypass = {
            "contract_version": "vedic-question-route-bypass-v1",
            "interpreted_question": str(question or "").strip(),
            "primary_topic": "general",
            "time_scope": "none",
            "timing_required": False,
            "target_start": None,
            "target_end": None,
            "target_datetime": None,
            "required_evidence": ["natal_core", "active_dasha", "full_natal_sections"],
            "sensitivity": "standard",
            "confidence": "low",
            "clarification_required": False,
            "clarification_question": None,
        }
    selected = (
        bypass
        if bypass is not None
        else model
        if mode in {"active", "gemini_only"} and model
        else legacy
    )
    status = (
        "classifier_bypassed"
        if bypass is not None
        else "model_selected"
        if selected is model and model
        else "model_shadowed"
        if model
        else "fallback_selected"
        if error_code
        else "legacy_selected"
    )
    return {
        "mode": mode,
        "status": status,
        "legacy": legacy,
        "model": model,
        "selected": selected,
        "error_code": error_code,
        "agreement": bool(
            model
            and model.get("primary_topic") == legacy.get("primary_topic")
            and model.get("time_scope") == legacy.get("time_scope")
        ),
    }


def _beta_record_question_route(
    route_id,
    profile_id,
    chart_id,
    owner_user_id,
    question,
    routing,
):
    with closing(_beta_db()) as conn:
        conn.execute(
            """
            INSERT OR REPLACE INTO beta_question_routes
                (id, profile_id, chart_id, owner_user_id, question, mode, status,
                 legacy_json, model_json, selected_json, error_code, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                route_id,
                profile_id,
                chart_id,
                owner_user_id,
                question,
                routing["mode"],
                routing["status"],
                _beta_json(routing["legacy"]),
                _beta_json(routing["model"]) if routing.get("model") else None,
                _beta_json(routing["selected"]),
                routing.get("error_code"),
                _beta_now(),
            ),
        )
        conn.commit()


def _beta_compact_transit_planet(planet):
    if not planet:
        return None
    ashtakavarga = planet.get("ashtakavarga") or {}
    return {
        "name": planet.get("name"),
        "sign": planet.get("sign"),
        "degree": planet.get("degree_str"),
        "house_from_lagna": planet.get("house_from_lagna"),
        "house_from_moon": planet.get("house_from_moon"),
        "retrograde": bool(planet.get("retrograde")),
        "sav": ashtakavarga.get("sav"),
        "bav": ashtakavarga.get("bav"),
    }


def _beta_compact_transit_contact(contact):
    return {
        "transit_planet": contact.get("transit_planet"),
        "natal_planet": contact.get("natal_planet"),
        "contact_type": contact.get("contact_type"),
        "orb": round(contact.get("orb"), 3)
        if isinstance(contact.get("orb"), (int, float))
        else None,
        "sign": contact.get("sign"),
        "house_from_lagna": contact.get("house_from_lagna"),
        "house_from_moon": contact.get("house_from_moon"),
    }


def _beta_full_transit_planet(planet):
    if not planet:
        return None
    ashtakavarga = planet.get("ashtakavarga") or {}
    return {
        "name": planet.get("name"),
        "sign": planet.get("sign"),
        "sign_tr": planet.get("sign_tr"),
        "sign_index": planet.get("sign_index"),
        "degree": planet.get("degree_str"),
        "nakshatra": planet.get("nakshatra"),
        "nakshatra_lord": planet.get("nakshatra_lord"),
        "pada": planet.get("nakshatra_pada"),
        "house_from_lagna": planet.get("house_from_lagna"),
        "house_from_moon": planet.get("house_from_moon"),
        "retrograde": bool(planet.get("retrograde")),
        "speed_status": planet.get("speed_status"),
        "natal_planets_in_sign": planet.get("natal_planets_in_sign") or [],
        "sav": ashtakavarga.get("sav"),
        "bav": ashtakavarga.get("bav"),
        "sav_support_level": ashtakavarga.get("sav_support_level"),
        "bav_support_level": ashtakavarga.get("bav_support_level"),
    }


def _beta_full_transit_day(day):
    return {
        "date": day.get("date"),
        "reference_datetime_utc": day.get("reference_datetime_utc"),
        "requested_time": day.get("requested_time"),
        "requested_tz_offset": day.get("requested_tz_offset"),
        "active_dasha_path": day.get("active_dasha_path") or [],
        "active_dasha": day.get("active_dasha") or [],
        "panchanga": day.get("panchanga") or {},
        "planets": [
            _beta_full_transit_planet(planet)
            for planet in day.get("planets") or []
        ],
        "natal_contacts": [
            _beta_compact_transit_contact(contact)
            for contact in day.get("natal_contacts") or []
        ],
        "dasha_cross_reference": day.get("dasha_cross_reference") or {},
        "special_checks": day.get("special_checks") or {},
    }


def _beta_select_transit_pack(transit_pack, range_start, range_end):
    selected_days = [
        day
        for day in (transit_pack or {}).get("days") or []
        if range_start <= str(day.get("date") or "") <= range_end
    ]
    if not selected_days:
        raise ValueError("İstenen tarih kayıtlı transit artefaktında bulunamadı")
    selected = dict(transit_pack)
    selected["days"] = selected_days
    selected["selection"] = {
        "range_start": range_start,
        "range_end": range_end,
        "day_count": len(selected_days),
    }
    return selected


def _beta_compact_transit_evidence(
    transit_pack,
    *,
    time_scope="range",
    instant_pack=None,
    source="generated",
    regenerated=False,
):
    """Bounded three-month evidence: every day for timing, sparse slow-planet snapshots."""

    days = (transit_pack or {}).get("days") or []
    slow_planets = ("Saturn", "Jupiter", "Rahu (True)", "Ketu", "Mars", "Venus")
    daily_timing = []
    slow_planet_snapshots = []
    previous_states = None
    closest_contacts = {}
    full_daily_records = []

    for index, day in enumerate(days):
        degree_contacts = sorted(
            (
                contact
                for contact in day.get("natal_contacts", [])
                if contact.get("contact_type") == "degree_orb"
            ),
            key=lambda contact: contact.get("orb")
            if isinstance(contact.get("orb"), (int, float))
            else 99,
        )
        selected_contacts = degree_contacts[:3]
        moon = _transit_pack_planet(day, "Moon")
        daily_timing.append({
            "date": day.get("date"),
            "active_dasha_path": day.get("active_dasha_path") or [],
            "moon": {
                "sign": moon.get("sign"),
                "nakshatra": moon.get("nakshatra"),
                "pada": moon.get("nakshatra_pada"),
                "house_from_lagna": moon.get("house_from_lagna"),
                "house_from_moon": moon.get("house_from_moon"),
            },
            "closest_degree_contacts": [
                _beta_compact_transit_contact(contact)
                for contact in selected_contacts
            ],
        })
        if time_scope in {"instant", "daily"}:
            full_daily_records.append(_beta_full_transit_day(day))

        current_states = {
            planet_name: (
                (_transit_pack_planet(day, planet_name) or {}).get("sign"),
                bool((_transit_pack_planet(day, planet_name) or {}).get("retrograde")),
            )
            for planet_name in slow_planets
        }
        is_weekly_snapshot = index % 7 == 0 or index == len(days) - 1
        has_state_change = previous_states is not None and current_states != previous_states
        if is_weekly_snapshot or has_state_change:
            slow_planet_snapshots.append({
                "date": day.get("date"),
                "reason": "state_change" if has_state_change else "weekly_snapshot",
                "planets": [
                    _beta_compact_transit_planet(_transit_pack_planet(day, planet_name))
                    for planet_name in slow_planets
                ],
            })
        previous_states = current_states

        for contact in degree_contacts:
            key = (
                contact.get("transit_planet"),
                contact.get("natal_planet"),
                contact.get("contact_type"),
            )
            previous = closest_contacts.get(key)
            orb = contact.get("orb")
            if previous is None or (
                isinstance(orb, (int, float))
                and orb < previous[0]
            ):
                closest_contacts[key] = (
                    orb if isinstance(orb, (int, float)) else 99,
                    day.get("date"),
                    contact,
                )

    closest_approaches = [
        {
            "date": date,
            **_beta_compact_transit_contact(contact),
        }
        for _, date, contact in sorted(
            closest_contacts.values(),
            key=lambda item: (item[1] or "", item[0]),
        )
    ]
    result = {
        "contract_version": "vedic-compact-transit-evidence-v2",
        "calculation_policy": "api_only_no_model_calculation",
        "time_scope": time_scope,
        "source": source,
        "three_month_recalculated_for_question": bool(regenerated),
        "period": (transit_pack or {}).get("period") or {},
        "selection": (transit_pack or {}).get("selection") or {},
        "natal_reference": (transit_pack or {}).get("natal") or {},
        "daily_timing": daily_timing,
        "daily_records": full_daily_records,
        "slow_planet_snapshots": slow_planet_snapshots,
        "closest_approaches": closest_approaches,
        "interpretation_limits": [
            "daily_timing contains every covered calendar day",
            "slow_planet_snapshots are weekly plus sign or retrograde state changes",
            "closest_approaches are the minimum exact-degree orbs per transit-natal pair",
            "dates are technical evidence, not guaranteed event dates",
        ],
    }
    if instant_pack:
        instant_days = (instant_pack or {}).get("days") or []
        if not instant_days:
            raise ValueError("Anlık transit görüntüsü üretilemedi")
        result["instant_snapshot"] = _beta_full_transit_day(instant_days[0])
    return result


def _beta_missing_for_topic(chart, packet):
    missing = chart.get("missing") or []
    if not packet:
        return [{
            "key": "topic_packets.topic_not_configured",
            "status": "not_configured",
            "reason": "Bu soru tipi için beta chat topic packet kuralı henüz tanımlı değil",
            "impact": "Sohbet katmanı sadece genel chart özeti ve mevcut teknik kanıtları gösterebilir",
        }]
    missing_keys = {
        str(item.get("source") or "").replace("missing.", "")
        for item in packet.get("missing_factors", [])
    }
    missing_keys.update(packet.get("required_but_missing") or [])
    if not missing_keys:
        return []
    return [item for item in missing if item.get("key") in missing_keys]


def _beta_active_dasha_evidence(chart):
    vimshottari = chart.get("dashas", {}).get("vimshottari", {})
    active = vimshottari.get("current_active") or vimshottari.get("active") or {}
    return {
        "status": "available" if active else "missing",
        "path": active.get("path"),
        "maha": active.get("maha"),
        "antara": active.get("antara"),
        "pratyantar": active.get("pratyantar"),
        "sookshma": active.get("sookshma"),
        "prana": active.get("prana"),
    }


