def _beta_shadbala_strength_summary(chart):
    rows = []
    for item in (chart.get("shadbala") or {}).get("planets") or []:
        professional = item.get("professional_total") or {}
        ratio = professional.get("strength_ratio")
        if not isinstance(ratio, (int, float)):
            continue
        rows.append({
            "planet": item.get("planet"),
            "strength_ratio": ratio,
            "total_rupa": professional.get("total_rupa"),
            "required_rupa": professional.get("required_rupa"),
            "legacy_raw_total": item.get("total_score"),
            "ratio_grade": professional.get("grade"),
        })
    rows.sort(key=lambda row: row["strength_ratio"], reverse=True)
    return {
        "comparison_basis": "strength_ratio_only",
        "rule": "Gezegenler arası Shadbala sıralaması ham toplamla değil strength_ratio ile yapılır.",
        "ranking": rows,
        "strongest_planet": rows[0]["planet"] if rows else None,
        "nodes": "Rahu ve Ketu için Shadbala hesaplanmaz (gölge gezegen).",
    }


def _beta_selected_natal_sections(
    chart,
    subject_topic,
    include_all=False,
    timing_mode=False,
):
    render_chart = json.loads(json.dumps(chart))
    active = (
        ((render_chart.get("dashas") or {}).get("vimshottari") or {})
        .get("current_active")
        or {}
    )
    for level in DASHA_LEVELS:
        period = active.get(level)
        if isinstance(period, str):
            active[level] = {"lord": period, "path": [period]}
    person = ((render_chart.get("birth") or {}).get("person") or {})
    sections = _pwa_natal_sections(
        render_chart,
        person.get("name") or person.get("id") or "PWA User",
        "PWA",
        rectification_record=None,
    )
    selected_ids = set(PWA_NATAL_CORE_SECTION_IDS)
    if timing_mode:
        selected_ids.discard("varga_confidence")
        selected_ids.discard("technical_layer_status")
    if include_all:
        selected_ids.update({
            "panchanga", "varga_tables", "shadbala", "vimshopaka_bala",
            "bhava_bala", "ashtakavarga", "avasthas", "bhava_chalit",
            "graha_yuddha", "kp", "jaimini", "yogas", "doshas",
            "planet_quick_read", "house_drishti", "chara_dasha",
            "yogini_dasha", "career_packet", "topic_summaries",
            "life_events",
        })
    elif timing_mode:
        selected_ids.update({"planet_quick_read", "topic_summaries"})
        if subject_topic == "career":
            selected_ids.add("career_packet")
        elif subject_topic == "wellbeing":
            selected_ids.update({"shadbala", "bhava_bala", "avasthas"})
        elif subject_topic in {"marriage", "wealth", "health", "spiritual"}:
            selected_ids.add("varga_tables")
    else:
        selected_ids.update(PWA_NATAL_TOPIC_SECTION_IDS.get(subject_topic, set()))
    return [
        {
            "id": section["id"],
            "title": section["title"],
            "topics": section["topics"],
            "content": section["body"],
        }
        for section in sections
        if section["id"] in selected_ids
    ]


def _beta_route_time_window(route, chart):
    now_value = _beta_question_now(chart)
    now_dt = datetime.fromisoformat(now_value)
    scope = route.get("time_scope") or "none"
    if scope == "instant":
        target = route.get("target_datetime")
        target_dt = now_dt if target in {None, "", "now"} else datetime.fromisoformat(
            str(target).replace("Z", "+00:00")
        )
        target_date = target_dt.date().isoformat()
        return target_date, target_date, target_dt
    if scope == "daily":
        target_date = str(route.get("target_start") or now_dt.date().isoformat())
        return target_date, target_date, None
    if scope == "range":
        range_start = str(route.get("target_start") or now_dt.date().isoformat())
        range_end = str(
            route.get("target_end")
            or (date.fromisoformat(range_start) + timedelta(days=91)).isoformat()
        )
        return range_start, range_end, None
    return None, None, None


def _beta_instant_transit_pack(chart, target_dt):
    person = ((chart.get("birth") or {}).get("person") or {})
    return _pwa_transit_pack(
        chart,
        person.get("name") or person.get("id") or "PWA User",
        "PWA",
        start_date=target_dt.date().isoformat(),
        transit_time=target_dt.strftime("%H:%M"),
        period="daily",
    )


def _beta_topic_packet(chart, subject_topic):
    packet = (chart.get("topic_packets") or {}).get(subject_topic)
    if packet:
        return packet
    if subject_topic not in {"character", "wellbeing", "general"}:
        return None
    selection_rules = {
        "character": "Lagna, Lagna lordu, Ay, Atmakaraka, Shadbala, D9, yoga ve karşı kanıt birlikte okunur.",
        "wellbeing": "Ay, Lagna, Lagna lordu, aktif daşa, duygusal bhavalar ve zaman sorusunda güncel Ay/Panchanga birlikte okunur.",
        "general": "Genel harita sorusunda temel natal göstergeler ve karşı kanıt birlikte okunur.",
    }
    return {
        "contract_version": "vedic-natal-topic-selection-v1",
        "package_code": subject_topic.upper(),
        "topic": subject_topic,
        "source": "selected_natal_sections",
        "confidence": "medium",
        "missing_factors": [],
        "required_but_missing": [],
        "evidence": {"selection_rule": selection_rules[subject_topic]},
    }


def _beta_build_chat_draft(
    question,
    chart,
    *,
    routing=None,
    owner_user_id=None,
    profile_id=None,
    chart_id=None,
):
    selected_route = (routing or {}).get("selected") or _beta_legacy_question_route(question)
    subject_topic = selected_route["primary_topic"]
    topic = "transit" if selected_route["timing_required"] else subject_topic
    packets = chart.get("topic_packets") or {}
    packet = _beta_topic_packet(chart, subject_topic)
    if packet:
        # Stored beta charts created before the current-active correction can
        # contain the birth-time dasha inside topic packets. Normalize at read
        # time as well as at chart creation so existing profiles are safe.
        packet = json.loads(json.dumps(packet))
        packet.setdefault("evidence", {})["active_dasha"] = _topic_active_dasha_evidence(
            chart.get("dashas") or {}
        )
    transits = chart.get("transits")
    transit_trace = None
    if topic == "transit":
        person = ((chart.get("birth") or {}).get("person") or {})
        range_start, range_end, target_dt = _beta_route_time_window(selected_route, chart)
        source = "legacy_generated"
        regenerated = True
        if owner_user_id and profile_id and chart_id:
            transit_pack, source, regenerated = _pwa_get_or_create_transit_runtime_cache(
                owner_user_id,
                profile_id,
                chart_id,
                PWA_ARTIFACT_DEFAULT_PROFILE,
                chart,
                person.get("name") or person.get("id") or "PWA User",
                range_start,
                range_end,
            )
        else:
            transit_pack = _pwa_transit_pack(
                chart,
                person.get("name") or person.get("id") or "PWA User",
                "PWA",
                start_date=range_start,
            )
        selected_pack = _beta_select_transit_pack(transit_pack, range_start, range_end)
        instant_pack = (
            _beta_instant_transit_pack(chart, target_dt)
            if selected_route["time_scope"] == "instant"
            else None
        )
        transits = _beta_compact_transit_evidence(
            selected_pack,
            time_scope=selected_route["time_scope"],
            instant_pack=instant_pack,
            source=source,
            regenerated=regenerated,
        )
        transit_trace = {
            "source": source,
            "three_month_recalculated_for_question": bool(regenerated),
            "range_start": range_start,
            "range_end": range_end,
            "instant_reference_datetime_utc": (
                (transits.get("instant_snapshot") or {}).get("reference_datetime_utc")
            ),
            "instant_requested_time": (
                (transits.get("instant_snapshot") or {}).get("requested_time")
            ),
        }
    evidence = {
        "chart_summary": _beta_chart_summary(chart),
        "active_dasha": _beta_active_dasha_evidence(chart),
        "strength_summary": _beta_shadbala_strength_summary(chart),
        "topic_packet": packet,
        "natal_sections": _beta_selected_natal_sections(
            chart,
            subject_topic,
            include_all=topic == "general",
            timing_mode=topic == "transit",
        ),
        "transits": transits,
        "data_quality": chart.get("data_quality"),
    }
    missing = _beta_missing_for_topic(chart, packet)
    confidence = packet.get("confidence") if packet else "low"
    status = "evidence_ready" if packet or topic == "general" else "topic_not_configured"
    if missing:
        status = "evidence_ready_with_missing_layers"

    return {
        "status": status,
        "question": question,
        "topic": topic,
        "subject_topic": subject_topic,
        "question_route": selected_route,
        "routing_comparison": {
            "mode": (routing or {}).get("mode", "off"),
            "status": (routing or {}).get("status", "legacy_selected"),
            "agreement": (routing or {}).get("agreement"),
            "legacy": (routing or {}).get("legacy"),
            "model": (routing or {}).get("model"),
            "error_code": (routing or {}).get("error_code"),
        },
        "evidence": evidence,
        "missing": missing,
        "confidence": confidence,
        "context_strategy": (
            "full_natal_sections_v1"
            if topic == "general"
            else "topic_selected_natal_sections_v1"
        ),
        "context_trace": {
            "route_contract_version": selected_route.get("contract_version"),
            "primary_topic": subject_topic,
            "time_scope": selected_route.get("time_scope"),
            "required_evidence": selected_route.get("required_evidence") or [],
            "transit": transit_trace,
        },
        "safety_notes": _beta_safety_notes(
            subject_topic,
            selected_route.get("sensitivity"),
        ),
        "next_action": "Bu kanıt paketini yorum katmanına ver; hesap veya eksik katman uydurma.",
    }


def _beta_comparison_id(value):
    comparison_id = str(value or "").strip() or new_comparison_id()
    if not re.fullmatch(r"[0-9A-Za-z._:-]{1,200}", comparison_id):
        raise ValueError("Geçerli comparison_id gerekli")
    return comparison_id


def _beta_existing_comparison(conn, comparison_id, profile_id, chart_id, question):
    row = conn.execute(
        """
        SELECT profile_id, chart_id, question, status, response_json
        FROM beta_methodology_comparisons
        WHERE id = ?
        """,
        (comparison_id,),
    ).fetchone()
    if not row:
        return None
    if (
        str(row["profile_id"] or "") != str(profile_id or "")
        or row["chart_id"] != chart_id
        or row["question"] != question
    ):
        raise ValueError("comparison_id başka bir istek için kullanılmış")
    return row


def _beta_load_chart(conn, chart_id=None, profile_id=None):
    if chart_id:
        row = conn.execute(
            "SELECT id, profile_id, chart_json, owner_user_id FROM beta_charts WHERE id = ?",
            (chart_id,),
        ).fetchone()
    elif profile_id:
        row = conn.execute(
            "SELECT id, profile_id, chart_json, owner_user_id FROM beta_charts WHERE profile_id = ? ORDER BY created_at DESC LIMIT 1",
            (profile_id,),
        ).fetchone()
    else:
        row = None

    if not row:
        raise ValueError("Chart referansı bulunamadı")
    return (
        row["id"],
        row["profile_id"],
        _beta_load_json(row["chart_json"]),
        row["owner_user_id"],
    )


@app.route("/api/v1/places/search", methods=["GET"])
def api_v1_places_search():
    try:
        query = str(request.args.get("q") or "").strip()
        country_code = str(request.args.get("country") or "").strip() or None
        limit = int(request.args.get("limit") or 8)
        places = search_places(
            app.config["PLACES_DB_PATH"],
            query,
            country_code=country_code,
            limit=limit,
        )
        return jsonify({
            "query": query,
            "count": len(places),
            "places": places,
            "source": {
                "name": "GeoNames",
                "dataset": "cities500",
                "license": "CC BY 4.0",
                "attribution_url": "https://www.geonames.org/",
            },
        })
    except (TypeError, ValueError) as exc:
        return jsonify({"error": f"Geçersiz doğum yeri araması: {exc}"}), 400
    except PlaceCatalogUnavailable as exc:
        return jsonify({"error": str(exc)}), 503


