@app.route("/api/v2/transits/pack", methods=["POST"])
def api_v2_transits_pack():
    try:
        data = request.get_json() or {}
        pack = _build_transit_pack(data)
        markdown = _build_transit_pack_markdown(pack)
        save = _parse_bool_param(data.get("save"), True)
        overwrite = _parse_bool_param(data.get("overwrite"), False)
        include_markdown = _parse_bool_param(data.get("include_markdown"), True)

        result = {
            "ok": True,
            "status": "transit_pack_ready",
            "person": pack["person"],
            "period": pack["period"],
            "panchanga_reference": pack["period"].get("panchanga_reference"),
            "day_count": pack["period"]["day_count"],
        }
        http_status = 200

        if save:
            save_result = _save_transit_pack(pack, markdown, overwrite=overwrite)
            http_status = save_result.pop("_http_status", 200)
            result.update(save_result)
            pack["_source_path"] = (
                (save_result.get("paths") or {}).get("transit_pack")
            )
            if http_status < 400 and pack["period"].get("type") == "range":
                result["analysis_packages_sync"] = (
                    _refresh_analysis_packages_for_selected_transit(pack)
                )

        if include_markdown and http_status < 400:
            result["markdown"] = markdown

        return jsonify(result), http_status

    except (KeyError, TypeError, ValueError) as e:
        return jsonify({"error": f"Geçersiz transit paket verisi: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"error": f"Transit paket hatası: {str(e)}"}), 500


@app.route("/api/v2/vault/save", methods=["POST"])
def api_v2_vault_save():
    try:
        data = request.get_json() or {}
        chart = data["chart"]
        if data.get("analysis_profile"):
            chart["analysis_profile"] = _expert_analysis_profile(data)
        person = data.get("person") or chart.get("birth", {}).get("person") or {}
        person_name = _safe_vault_segment(person.get("name"), "person.name")
        group_name = _safe_vault_segment(person.get("group") or data.get("group"), "group")
        overwrite = bool(data.get("overwrite", True))

        if not chart.get("meta") or chart.get("meta", {}).get("api_version") != "v2":
            raise ValueError("chart v2 verisi bekleniyor")
        if not chart.get("life_period_analysis"):
            chart["life_period_analysis"] = (
                _build_life_period_analysis_for_chart(chart)
            )

        save_gate = _vault_save_rectified_time_gate(chart, person_name, group_name)
        if save_gate:
            http_status = save_gate.pop("_http_status", 400)
            return jsonify(save_gate), http_status

        result = _save_vault_files(
            chart,
            person_name,
            group_name,
            overwrite=overwrite,
            transit_range=data.get("transit_range"),
            preserve_existing_analysis_profile=not bool(data.get("analysis_profile")),
        )
        status = result.pop("status")
        return jsonify(result), status

    except (KeyError, TypeError, ValueError) as e:
        return jsonify({"error": f"Geçersiz veri: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"error": f"Vault kayıt hatası: {str(e)}"}), 500


@app.route("/api/v2/vault/load", methods=["POST"])
def api_v2_vault_load():
    try:
        data = request.get_json() or {}
        root = _vault_astrology_root()

        if data.get("path"):
            natal_path = Path(data["path"])
        else:
            person_name = _safe_vault_segment(data.get("name"), "name")
            group_name = _safe_vault_segment(data.get("group") or "Grup-01", "group")
            natal_path = _vault_person_path(group_name, person_name)
            if not natal_path.exists():
                natal_path, _ = _legacy_vault_paths(group_name, person_name)

        _ensure_path_inside(root, natal_path)
        text = natal_path.read_text(encoding="utf-8")
        rectification = _rectification_record_data_from_text(text)
        chart_snapshot = _chart_snapshot_data_from_text(text)
        chart, person = _load_vault_natal_chart(natal_path)
        saved_analysis_mode = ((chart_snapshot.get("analysis_profile") or {}).get("mode"))
        if saved_analysis_mode:
            chart["analysis_profile"] = _expert_analysis_profile({
                "analysis_profile": {"mode": saved_analysis_mode},
            })
        snapshot_comparison = _chart_snapshot_comparison(chart_snapshot, chart)
        copy_package_payload = _expert_copy_payload(
            chart,
            person["name"],
            person["group"],
        )
        expert_package = ((copy_package_payload.get("copy_packages") or {}).get("expert") or {})
        response_payload = {
            "ok": True,
            "load_mode": "recomputed_from_saved_birth_markdown",
            "source_of_truth": {
                "birth": "saved_markdown",
                "chart": "recomputed_from_saved_birth_markdown",
                "saved_snapshot": {
                    "available": bool(chart_snapshot),
                    "schema": chart_snapshot.get("snapshot_schema") if chart_snapshot else None,
                    "reason": (
                        "embedded_minimal_snapshot_present_but_not_used_for_chart_response"
                        if chart_snapshot
                        else "person_markdown_does_not_embed_chart_snapshot"
                    ),
                    "summary": (
                        {
                            "saved_at": chart_snapshot.get("saved_at"),
                            "planet_count": len(chart_snapshot.get("planets") or []),
                            "house_count": len(chart_snapshot.get("houses") or []),
                            "active_dasha_path": chart_snapshot.get("active_dasha_path") or [],
                        }
                        if chart_snapshot
                        else None
                    ),
                    "comparison": snapshot_comparison,
                },
                "expert_copy": "regenerated_from_loaded_chart",
                "expert_copy_details": {
                    "generator": expert_package.get("generator"),
                    "source": expert_package.get("source"),
                    "analysis_mode": ((expert_package.get("analysis_profile") or {}).get("mode")),
                    "saved_analysis_mode": (
                        ((chart_snapshot.get("analysis_profile") or {}).get("mode"))
                        if chart_snapshot
                        else None
                    ),
                    "matches_saved_analysis_mode": (
                        ((chart_snapshot.get("analysis_profile") or {}).get("mode"))
                        == ((expert_package.get("analysis_profile") or {}).get("mode"))
                        if chart_snapshot
                        else None
                    ),
                },
                "life_events": "embedded_record_if_present",
                "analysis_packages": (
                    "regenerated_on_load"
                    if not rectification
                    else "skipped_when_life_events_present"
                ),
                "analysis_packages_details": {
                    "mode": (
                        "regenerated_on_load"
                        if not rectification
                        else "skipped_when_life_events_present"
                    ),
                    "package_count": 0,
                },
                "chart_response_profile": "vault_load_slim_dasha_tree",
            },
            "person": person,
            "chart": _slim_chart_for_vault_load_response(chart),
            "path": str(natal_path),
            "has_life_events": bool(rectification),
            "life_events": rectification,
            "has_rectification": bool(rectification),
            "rectification": rectification,
            **copy_package_payload,
        }
        if not rectification:
            analysis_package_paths = _save_analysis_data_packages(
                chart,
                person["name"],
                person["group"],
            )
            response_payload["source_of_truth"]["analysis_packages_details"]["package_count"] = len(
                analysis_package_paths
            )
            response_payload.update(_analysis_data_package_payload(analysis_package_paths))
        return jsonify(response_payload)

    except (KeyError, TypeError, ValueError) as e:
        return jsonify({"error": f"Geçersiz veri: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"error": f"Vault okuma hatası: {str(e)}"}), 500


