@app.route("/api/v2/beta/profile", methods=["POST"])
def api_v2_beta_profile():
    try:
        data = request.get_json() or {}
        person_input = data.get("person") or {}
        birth = data["birth"]
        options = _beta_options(data.get("options") or {})
        profile_id = str(data.get("profile_id") or uuid.uuid4())
        owner_user_id = data.get("owner_user_id")
        if owner_user_id is not None:
            owner_user_id = _account_deletion_user_id(owner_user_id)
        chart_id = str(data.get("chart_id") or uuid.uuid4()).strip()
        if not re.fullmatch(r"[0-9A-Za-z._:-]{1,200}", chart_id):
            raise ValueError("Geçerli chart_id gerekli")
        person = {
            "id": profile_id,
            "name": str(person_input.get("name") or "Beta Kullanıcı").strip(),
            "group": str(person_input.get("group") or "Beta").strip(),
        }
        if not person["name"]:
            person["name"] = "Beta Kullanıcı"
        if not person["group"]:
            person["group"] = "Beta"

        chart = _beta_build_chart(person, birth, options)
        created_at = _beta_now()
        with closing(_beta_db()) as conn:
            conn.execute(
                """
                INSERT OR REPLACE INTO beta_charts
                    (id, profile_id, chart_json, created_at, owner_user_id)
                VALUES (?, ?, ?, ?, ?)
                """,
                (chart_id, profile_id, _beta_json(chart), created_at, owner_user_id),
            )
            conn.execute(
                """
                INSERT OR REPLACE INTO beta_profiles
                    (id, name, group_name, birth_json, options_json, chart_id, created_at, owner_user_id)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    profile_id,
                    person["name"],
                    person["group"],
                    _beta_json(birth),
                    _beta_json(options),
                    chart_id,
                    created_at,
                    owner_user_id,
                ),
            )
            conn.commit()
            usage = _beta_usage_status(conn, profile_id)

        return jsonify({
            "ok": True,
            "status": "profile_saved",
            "profile_id": profile_id,
            "chart_id": chart_id,
            "profile": {
                "name": person["name"],
                "group": person["group"],
            },
            "chart_summary": _beta_chart_summary(chart),
            "usage": usage,
        })

    except (KeyError, TypeError, ValueError) as e:
        return jsonify({"error": f"Geçersiz beta profil verisi: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"error": f"Beta profil hatası: {str(e)}"}), 500


@app.route("/api/v2/beta/chart/summary", methods=["POST"])
def api_v2_beta_chart_summary():
    """Return only the browser-safe summary for an owned beta chart."""

    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            raise ValueError("Geçerli özet isteği gerekli")
        owner_user_id = _account_deletion_user_id(data.get("owner_user_id"))
        profile_id = str(data.get("profile_id") or "").strip()
        chart_id = str(data.get("chart_id") or "").strip()
        if not profile_id or not re.fullmatch(r"[0-9A-Za-z._:-]{1,200}", chart_id):
            raise ValueError("Geçerli profil ve harita kimliği gerekli")

        with closing(_beta_db()) as conn:
            row = conn.execute(
                """
                SELECT c.chart_json, c.owner_user_id,
                       p.owner_user_id AS profile_owner_user_id
                FROM beta_charts c
                JOIN beta_profiles p ON p.id = c.profile_id
                WHERE c.id = ? AND c.profile_id = ?
                """,
                (chart_id, profile_id),
            ).fetchone()
        if not row:
            return jsonify({
                "ok": False,
                "status": "chart_not_found",
                "error_code": "beta_chart_not_found",
            }), 404
        if row["owner_user_id"] != owner_user_id or row["profile_owner_user_id"] != owner_user_id:
            return jsonify({
                "ok": False,
                "status": "ownership_mismatch",
                "error_code": "beta_chart_ownership_mismatch",
            }), 403

        return jsonify({
            "ok": True,
            "status": "summary_ready",
            "profile_id": profile_id,
            "chart_id": chart_id,
            "chart_summary": _beta_chart_summary(_beta_load_json(row["chart_json"])),
        })

    except (TypeError, ValueError) as e:
        return jsonify({"error": f"Geçersiz beta harita özet verisi: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"error": f"Beta harita özet hatası: {str(e)}"}), 500


@app.route("/api/v2/pwa/artifacts/generate", methods=["POST"])
def api_v2_pwa_artifacts_generate():
    """Generate one immutable, server-selected PWA artifact profile."""

    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            raise ValueError("Geçerli artefakt isteği gerekli")
        owner_user_id = _account_deletion_user_id(data.get("owner_user_id"))
        profile_id = str(data.get("profile_id") or "").strip()
        chart_id = _pwa_artifact_chart_id(data.get("chart_id"))
        requested_profile = data.get("artifact_profile")
        artifact_profile = _pwa_artifact_profile(requested_profile)
        if not profile_id:
            raise ValueError("profile_id gerekli")
        if requested_profile and not app.config.get("TESTING"):
            raise ValueError("artifact_profile yalnız sunucu yapılandırmasından seçilir")

        with closing(_beta_db()) as conn:
            row = conn.execute(
                """
                SELECT c.profile_id, c.chart_json, c.owner_user_id,
                       p.name, p.owner_user_id AS profile_owner_user_id
                FROM beta_charts c
                JOIN beta_profiles p ON p.id = c.profile_id
                WHERE c.id = ? AND c.profile_id = ?
                """,
                (chart_id, profile_id),
            ).fetchone()
        if not row:
            return jsonify({
                "ok": False,
                "status": "chart_not_found",
                "error_code": "pwa_artifact_chart_not_found",
            }), 404
        if row["owner_user_id"] != owner_user_id or row["profile_owner_user_id"] != owner_user_id:
            return jsonify({
                "ok": False,
                "status": "ownership_mismatch",
                "error_code": "pwa_artifact_ownership_mismatch",
            }), 403

        manifest, manifest_sha256, replayed = _generate_pwa_artifact_set(
            owner_user_id,
            profile_id,
            chart_id,
            _beta_load_json(row["chart_json"]),
            str(row["name"] or "Vedik AI Kullanıcısı"),
            artifact_profile=artifact_profile,
        )
        return jsonify({
            "ok": True,
            "status": "artifacts_ready",
            "replayed": replayed,
            "manifest_sha256": manifest_sha256,
            "artifact_profile": artifact_profile,
            "manifest": manifest,
        })
    except (KeyError, TypeError, ValueError) as exc:
        return jsonify({
            "ok": False,
            "status": "invalid_request",
            "error_code": "pwa_artifact_request_invalid",
            "error": str(exc),
        }), 400
    except Exception:
        app.logger.exception("PWA artefakt seti üretilemedi")
        return jsonify({
            "ok": False,
            "status": "artifact_generation_failed",
            "error_code": "pwa_artifact_generation_failed",
        }), 500


@app.route("/api/v2/pwa/artifacts/<owner_user_id>/<chart_id>/<artifact_code>", methods=["GET"])
def api_v2_pwa_artifact_download(owner_user_id, chart_id, artifact_code):
    """Return one integrity-checked artifact to the trusted application backend."""

    try:
        owner_user_id = _account_deletion_user_id(owner_user_id)
        chart_id = _pwa_artifact_chart_id(chart_id)
        artifact_code = str(artifact_code or "").strip()
        artifact_profile = _pwa_artifact_profile(request.args.get("profile"))
        if not re.fullmatch(r"[a-z0-9_]{1,80}", artifact_code):
            raise ValueError("Geçerli artifact_code gerekli")
        path, item, sha256 = _pwa_artifact_file(
            owner_user_id,
            chart_id,
            artifact_code,
            artifact_profile=artifact_profile,
        )
        response = send_file(
            path,
            mimetype=item.get("content_type") or "application/octet-stream",
            as_attachment=True,
            download_name=item.get("download_filename") or item["filename"],
            conditional=False,
        )
        response.headers["X-Artifact-Sha256"] = sha256
        response.headers["Cache-Control"] = "private, no-store"
        return response
    except FileNotFoundError:
        return jsonify({
            "ok": False,
            "status": "artifact_not_found",
            "error_code": "pwa_artifact_not_found",
        }), 404
    except (TypeError, ValueError):
        return jsonify({
            "ok": False,
            "status": "invalid_request",
            "error_code": "pwa_artifact_download_invalid",
        }), 400
    except Exception:
        app.logger.exception("PWA artefakt dosyası indirilemedi")
        return jsonify({
            "ok": False,
            "status": "artifact_download_failed",
            "error_code": "pwa_artifact_download_failed",
        }), 500


@app.route("/api/v2/beta/chat/draft", methods=["POST"])
def api_v2_beta_chat_draft():
    try:
        data = request.get_json() or {}
        question = str(data.get("question") or "").strip()
        if not question:
            raise ValueError("question boş olamaz")
        if _beta_is_rectification_question(question):
            return jsonify({
                "ok": False,
                "status": "rectification_service_separate",
                "error_code": "rectification_not_available_in_customer_api",
                "message": "Rektifikasyon uzman servisi ana müşteri API'sinden ayrıdır.",
            }), 422

        profile_id = data.get("profile_id")
        chart_id = data.get("chart_id")
        owner_user_id = data.get("owner_user_id")
        if owner_user_id is not None:
            owner_user_id = _account_deletion_user_id(owner_user_id)
        with closing(_beta_db()) as conn:
            usage_before = _beta_usage_status(conn, profile_id)
            if usage_before["chat"]["remaining"] <= 0:
                return jsonify({
                    "ok": False,
                    "status": "limit_exceeded",
                    "question": question,
                    "topic": _beta_detect_topic(question),
                    "evidence": {},
                    "missing": [],
                    "confidence": "none",
                    "safety_notes": ["Günlük kapalı beta soru limiti doldu."],
                    "next_action": "Yarın tekrar dene veya beta limitini yapılandır.",
                    "usage": usage_before,
                }), 429

            if data.get("chart"):
                chart = data["chart"]
                chart_id = chart_id or str(uuid.uuid4())
                profile_id = profile_id or chart.get("birth", {}).get("person", {}).get("id")
                conn.execute(
                    """
                    INSERT OR REPLACE INTO beta_charts
                        (id, profile_id, chart_json, created_at, owner_user_id)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (
                        chart_id,
                        profile_id or "inline",
                        _beta_json(chart),
                        _beta_now(),
                        owner_user_id,
                    ),
                )
                conn.commit()
            else:
                chart_id, profile_id, chart, stored_owner_user_id = _beta_load_chart(
                    conn,
                    chart_id,
                    profile_id,
                )
                if owner_user_id and stored_owner_user_id != owner_user_id:
                    return jsonify({
                        "ok": False,
                        "status": "ownership_mismatch",
                        "error_code": "beta_chart_ownership_mismatch",
                    }), 403
                owner_user_id = stored_owner_user_id

            message_id = str(uuid.uuid4())
            routing = _beta_question_route(
                question,
                chart,
                message_id,
                owner_user_id,
            )
            _beta_record_question_route(
                message_id,
                profile_id,
                chart_id,
                owner_user_id,
                question,
                routing,
            )
            if routing["selected"].get("clarification_required"):
                return jsonify({
                    "ok": False,
                    "status": "clarification_required",
                    "error_code": "question_clarification_required",
                    "question": routing["selected"].get("clarification_question"),
                }), 422
            draft = _beta_build_chat_draft(
                question,
                chart,
                routing=routing,
                owner_user_id=owner_user_id,
                profile_id=profile_id,
                chart_id=chart_id,
            )
            conn.execute(
                """
                INSERT INTO beta_chat_messages
                    (id, profile_id, chart_id, question, response_json, created_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (message_id, profile_id, chart_id, question, _beta_json(draft), _beta_now()),
            )
            _beta_record_usage(conn, "chat_draft", profile_id)
            usage = _beta_usage_status(conn, profile_id)

        return jsonify({
            "ok": True,
            "message_id": message_id,
            "profile_id": profile_id,
            "chart_id": chart_id,
            "usage": usage,
            **draft,
        })

    except (KeyError, TypeError, ValueError) as e:
        return jsonify({"error": f"Geçersiz beta sohbet verisi: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"error": f"Beta sohbet hatası: {str(e)}"}), 500


@app.route("/api/v2/beta/chat/compare", methods=["POST"])
def api_v2_beta_chat_compare():
    """Run selected evidence through the single active system methodology."""

    comparison_id = None
    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            raise ValueError("Geçerli karşılaştırma isteği gerekli")
        question = str(data.get("question") or "").strip()
        if not question:
            raise ValueError("question boş olamaz")
        if len(question) > 2_000:
            raise ValueError("question çok uzun")
        if _beta_is_rectification_question(question):
            return jsonify({
                "ok": False,
                "status": "rectification_service_separate",
                "error_code": "rectification_not_available_in_customer_api",
                "message": "Rektifikasyon uzman servisi ana müşteri API'sinden ayrıdır.",
            }), 422
        comparison_id = _beta_comparison_id(data.get("comparison_id"))

        with closing(_beta_db()) as conn:
            chart_id, profile_id, chart, stored_owner_user_id = _beta_load_chart(
                conn,
                data.get("chart_id"),
                data.get("profile_id"),
            )
            requested_owner_user_id = data.get("owner_user_id")
            if requested_owner_user_id is not None:
                requested_owner_user_id = _account_deletion_user_id(requested_owner_user_id)
                if stored_owner_user_id != requested_owner_user_id:
                    return jsonify({
                        "ok": False,
                        "status": "ownership_mismatch",
                        "error_code": "beta_chart_ownership_mismatch",
                    }), 403
            owner_user_id = stored_owner_user_id
            existing = _beta_existing_comparison(
                conn,
                comparison_id,
                profile_id,
                chart_id,
                question,
            )
            if existing:
                usage = _beta_usage_status(conn, profile_id)
                if existing["status"] == "in_progress":
                    return jsonify({
                        "ok": False,
                        "status": "comparison_in_progress",
                        "comparison_id": comparison_id,
                        "usage": usage,
                    }), 409
                stored = _beta_load_json(existing["response_json"])
                status_code = (
                    422
                    if existing["status"] == "clarification_required"
                    else 200
                    if stored.get("completed_count", 0)
                    else 502
                )
                return jsonify({
                    "ok": bool(stored.get("completed_count", 0)),
                    "replayed": True,
                    "profile_id": profile_id,
                    "chart_id": chart_id,
                    "usage": usage,
                    **stored,
                }), status_code

            usage_before = _beta_usage_status(conn, profile_id)
            if usage_before["heavy"]["remaining"] <= 0:
                return jsonify({
                    "ok": False,
                    "status": "heavy_limit_exceeded",
                    "comparison_id": comparison_id,
                    "usage": usage_before,
                }), 429

            created_at = _beta_now()
            conn.execute(
                """
                INSERT INTO beta_methodology_comparisons
                    (id, profile_id, chart_id, question, status, response_json, created_at, updated_at)
                VALUES (?, ?, ?, ?, 'in_progress', '{}', ?, ?)
                """,
                (comparison_id, profile_id, chart_id, question, created_at, created_at),
            )
            conn.commit()

        routing = _beta_question_route(
            question,
            chart,
            comparison_id,
            owner_user_id,
        )
        _beta_record_question_route(
            comparison_id,
            profile_id,
            chart_id,
            owner_user_id,
            question,
            routing,
        )
        if routing["selected"].get("clarification_required"):
            clarification = {
                "status": "clarification_required",
                "completed_count": 0,
                "error_code": "question_clarification_required",
                "question_route": routing["selected"],
                "clarification_question": routing["selected"].get(
                    "clarification_question"
                ),
            }
            with closing(_beta_db()) as conn:
                conn.execute(
                    """
                    UPDATE beta_methodology_comparisons
                    SET status = 'clarification_required', response_json = ?, updated_at = ?
                    WHERE id = ?
                    """,
                    (_beta_json(clarification), _beta_now(), comparison_id),
                )
                conn.commit()
                usage = _beta_usage_status(conn, profile_id)
            return jsonify({
                "ok": False,
                "replayed": False,
                "profile_id": profile_id,
                "chart_id": chart_id,
                "comparison_id": comparison_id,
                "usage": usage,
                **clarification,
            }), 422
        draft = _beta_build_chat_draft(
            question,
            chart,
            routing=routing,
            owner_user_id=owner_user_id,
            profile_id=profile_id,
            chart_id=chart_id,
        )
        comparison = run_methodology_comparison(
            draft,
            comparison_id,
            call_vertex_bridge,
        )
        # Preserve the server-controlled route and evidence provenance beside
        # the model result. The PWA uses this trace to show the exact transit
        # source/date/time without asking the model to repeat infrastructure
        # metadata in prose.
        comparison["context_trace"] = draft.get("context_trace")
        comparison["question_route"] = draft.get("question_route")
        comparison["routing_comparison"] = draft.get("routing_comparison")

        with closing(_beta_db()) as conn:
            updated_at = _beta_now()
            conn.execute(
                """
                UPDATE beta_methodology_comparisons
                SET status = ?, response_json = ?, updated_at = ?
                WHERE id = ?
                """,
                (comparison["status"], _beta_json(comparison), updated_at, comparison_id),
            )
            conn.execute(
                "INSERT INTO beta_usage_events (day, action, profile_id, created_at) VALUES (?, 'heavy', ?, ?)",
                (_beta_day(), profile_id, updated_at),
            )
            conn.commit()
            usage = _beta_usage_status(conn, profile_id)

        ok = comparison["completed_count"] > 0
        if not ok:
            failed_codes = [
                item.get("error") or item.get("error_code")
                for item in comparison.get("methodology_results") or []
                if isinstance(item, dict) and (item.get("error") or item.get("error_code"))
            ]
            comparison["error_code"] = (
                failed_codes[0] if failed_codes else "methodology_comparison_failed"
            )
        return jsonify({
            "ok": ok,
            "replayed": False,
            "profile_id": profile_id,
            "chart_id": chart_id,
            "usage": usage,
            **comparison,
        }), 200 if ok else 502

    except (KeyError, TypeError, ValueError) as exc:
        return jsonify({
            "ok": False,
            "status": "invalid_request",
            "error": str(exc),
        }), 400
    except MethodologyOrchestrationError as exc:
        if comparison_id:
            try:
                with closing(_beta_db()) as conn:
                    conn.execute(
                        """
                        UPDATE beta_methodology_comparisons
                        SET status = 'failed', response_json = ?, updated_at = ?
                        WHERE id = ?
                        """,
                        (_beta_json({"status": "failed", "error": exc.code}), _beta_now(), comparison_id),
                    )
                    conn.commit()
            except Exception:
                app.logger.exception("Beta metodoloji karşılaştırması hata kaydı güncellenemedi")
        return jsonify({
            "ok": False,
            "status": "comparison_failed",
            "error_code": exc.code,
        }), exc.http_status
    except Exception:
        app.logger.exception("Beta metodoloji karşılaştırması beklenmedik hatayla durdu")
        if comparison_id:
            try:
                with closing(_beta_db()) as conn:
                    conn.execute(
                        """
                        UPDATE beta_methodology_comparisons
                        SET status = 'failed', response_json = ?, updated_at = ?
                        WHERE id = ?
                        """,
                        (
                            _beta_json({"status": "failed", "error": "methodology_orchestration_failed"}),
                            _beta_now(),
                            comparison_id,
                        ),
                    )
                    conn.commit()
            except Exception:
                app.logger.exception("Beta metodoloji karşılaştırması beklenmedik hata kaydı güncellenemedi")
        return jsonify({
            "ok": False,
            "status": "comparison_failed",
            "error_code": "methodology_orchestration_failed",
        }), 500


@app.route("/api/v2/beta/question-route/diagnostic", methods=["POST"])
def api_v2_beta_question_route_diagnostic():
    """Compare legacy and Gemini routing without chart access or usage rights."""

    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            raise ValueError("Geçerli yönlendirici deneme isteği gerekli")
        questions = data.get("questions")
        if not isinstance(questions, list) or not 1 <= len(questions) <= 20:
            raise ValueError("questions 1 ile 20 soru içermeli")
        timezone_id = str(data.get("timezone_id") or "Europe/Istanbul").strip()
        chart_stub = {"birth": {"timezone_id": timezone_id}}
        results = []
        for raw_question in questions:
            question = str(raw_question or "").strip()
            if not question or len(question) > 2_000:
                raise ValueError("Her soru 1 ile 2000 karakter arasında olmalı")
            route_id = f"diagnostic-{uuid.uuid4()}"
            routing = _beta_question_route(
                question,
                chart_stub,
                route_id,
                mode_override="shadow",
            )
            _beta_record_question_route(
                route_id,
                "__diagnostic__",
                "question-router-diagnostic",
                None,
                question,
                routing,
            )
            results.append({
                "route_id": route_id,
                "question": question,
                "status": routing["status"],
                "agreement": routing["agreement"],
                "legacy": routing["legacy"],
                "model": routing["model"],
                "selected": routing["selected"],
                "error_code": routing["error_code"],
            })
        return jsonify({
            "ok": all(item["model"] is not None for item in results),
            "mode": "shadow",
            "count": len(results),
            "results": results,
        }), 200
    except (TypeError, ValueError) as exc:
        return jsonify({
            "ok": False,
            "status": "invalid_request",
            "error": str(exc),
        }), 400


@app.route("/api/v2/ai/generate", methods=["POST"])
def api_v2_ai_generate():
    """Server-only handoff from the Vedik API to the fixed Vertex bridge."""

    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            raise VertexBridgeClientError("vertex_request_invalid", 400)
        request_id, model_response = call_vertex_bridge(
            data.get("request_id"),
            data.get("request"),
        )
        return jsonify({
            "ok": True,
            "request_id": request_id,
            "response": model_response,
        })
    except VertexBridgeClientError as exc:
        messages = {
            "vertex_request_id_invalid": "Geçerli request_id gerekli.",
            "vertex_request_invalid": "Geçerli model isteği gerekli.",
            "vertex_contents_required": "Model isteğinde contents gerekli.",
            "vertex_request_too_large": "Model isteği güvenli boyut sınırını aşıyor.",
            "vertex_bridge_unavailable": "Vedik model geçidi yapılandırılmamış.",
            "vertex_bridge_config_invalid": "Vedik model geçidi ayarı geçersiz.",
            "vertex_bridge_rejected": "Vedik model geçidi isteği reddetti.",
            "vertex_bridge_unreachable": "Vedik model geçidine ulaşılamadı.",
            "vertex_bridge_response_too_large": "Vedik model geçidi yanıtı çok büyük.",
            "vertex_bridge_response_invalid": "Vedik model geçidi geçersiz yanıt verdi.",
        }
        return jsonify({
            "ok": False,
            "status": "model_unavailable" if exc.http_status >= 500 else "invalid_request",
            "error": messages.get(exc.code, "Vedik model isteği tamamlanamadı."),
            "error_code": exc.code,
        }), exc.http_status


@app.route("/api/v2/account/delete-data", methods=["POST"])
def api_v2_account_delete_data():
    """Idempotently remove one Supabase user's Railway-side personal data."""

    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            raise ValueError("Geçerli silme isteği gerekli")
        user_id = _account_deletion_user_id(data.get("user_id"))
        request_id = _account_deletion_request_id(data.get("request_id"))

        with closing(_beta_db()) as conn:
            deleted_rows = _delete_beta_user_records(conn, user_id)
        directory_deleted = _delete_user_data_directory(user_id)

        return jsonify({
            "ok": True,
            "status": "railway_user_data_deleted",
            "request_id": request_id,
            "deleted": {
                "beta_rows": deleted_rows,
                "user_directory": directory_deleted,
            },
        })
    except (TypeError, ValueError) as exc:
        return jsonify({
            "ok": False,
            "status": "invalid_request",
            "error": str(exc),
        }), 400
    except Exception:
        return jsonify({
            "ok": False,
            "status": "delete_failed",
            "error": "Railway kullanıcı verisi silinemedi.",
        }), 500


@app.route("/api/v2/beta/feedback", methods=["POST"])
def api_v2_beta_feedback():
    try:
        data = request.get_json() or {}
        feedback_id = str(uuid.uuid4())
        rating = str(data.get("rating") or "").strip()
        comment = str(data.get("comment") or "").strip()
        if not rating and not comment:
            raise ValueError("rating veya comment gerekli")

        with closing(_beta_db()) as conn:
            conn.execute(
                """
                INSERT INTO beta_feedback
                    (id, message_id, profile_id, rating, comment, created_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    feedback_id,
                    data.get("message_id"),
                    data.get("profile_id"),
                    rating,
                    comment,
                    _beta_now(),
                ),
            )
            conn.commit()

        return jsonify({
            "ok": True,
            "status": "feedback_saved",
            "feedback_id": feedback_id,
        })

    except (KeyError, TypeError, ValueError) as e:
        return jsonify({"error": f"Geçersiz feedback verisi: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"error": f"Beta feedback hatası: {str(e)}"}), 500


@app.route("/api/v2/beta/usage", methods=["GET"])
def api_v2_beta_usage():
    try:
        profile_id = request.args.get("profile_id")
        with closing(_beta_db()) as conn:
            usage = _beta_usage_status(conn, profile_id)
            feedback_count = conn.execute(
                "SELECT COUNT(*) FROM beta_feedback WHERE profile_id = ? OR ? IS NULL",
                (profile_id, profile_id),
            ).fetchone()[0]
            message_count = conn.execute(
                "SELECT COUNT(*) FROM beta_chat_messages WHERE profile_id = ? OR ? IS NULL",
                (profile_id, profile_id),
            ).fetchone()[0]
            comparison_count = conn.execute(
                "SELECT COUNT(*) FROM beta_methodology_comparisons WHERE profile_id = ? OR ? IS NULL",
                (profile_id, profile_id),
            ).fetchone()[0]

        return jsonify({
            "ok": True,
            "status": "usage_ready",
            "profile_id": profile_id,
            "usage": usage,
            "counts": {
                "chat_messages": message_count,
                "feedback": feedback_count,
                "methodology_comparisons": comparison_count,
            },
        })

    except Exception as e:
        return jsonify({"error": f"Beta kullanım hatası: {str(e)}"}), 500


